-- =============================================================================
-- Migration: V10__seed_banco_questoes_multipla_escolha.sql
-- Descrição: Amplia o banco de questões para revisão MMEEBB com questões ORIGINAIS de
--            múltipla escolha (decisão com a orientadora: só questões fechadas).
--            (1) Cria as disciplinas de internato Urgência e Emergência e Saúde Mental
--                (Medicina) e Programação Orientada a Objetos e Gerência de Projetos (SI).
--            (2) Desativa as questões abertas (FLASHCARD) da V2/V3. As filas de revisão já
--                filtram flashcard.active; agendamentos e tentativas antigas são preservados.
--            (3) Insere as novas questões. Disciplinas da V2 usam o id fixo, como nas seeds
--                anteriores; as disciplinas novas são resolvidas pelo código.
-- Gerada por docs/10-banco-questoes-qa-carga/scripts/gerar_v10.py (fragmentos JSON validados).
-- Autor: Níckolas Tavares / Projeto TCC UNIPAM
-- =============================================================================

-- -----------------------------------------------------------------------------
