-- -----------------------------------------------------------------------------
INSERT INTO tb_subject (course_id, code, name, description, active)
VALUES
    (1, 'URG_EMERG', 'Urgência e Emergência', 'Suporte de Vida (BLS/ACLS), Choque, Sepse, Intoxicações e Emergências Tempo-Dependentes (IAM, AVC).', TRUE),
    (1, 'SAUDE_MENTAL', 'Saúde Mental', 'Transtornos de Humor e Ansiedade, Risco de Suicídio, Psicoses, Dependência Química e Rede de Atenção Psicossocial (RAPS).', TRUE),
    (2, 'PROG_OO', 'Programação Orientada a Objetos', 'Classes e Objetos, Encapsulamento, Herança, Polimorfismo, Interfaces, Coleções e Tratamento de Exceções.', TRUE),
    (2, 'GER_PROJ', 'Gerência de Projetos de Software', 'Escopo, Cronograma, Custos, Riscos, PMBOK, Scrum, Kanban e Métricas de Projeto.', TRUE)
