    'Hipertireoidismo com bócio difuso e oftalmopatia sugere doença de Graves, causada por anticorpos que estimulam o receptor do TSH; o TRAb positivo confirma o diagnóstico. A calcitonina é marcador do carcinoma medular, e a punção avalia nódulos, não o hipertireoidismo difuso.',
