    'Consensos SBEM de doenças da tireoide (questão original)',
    TRUE
),
(
    1,
    'Endocrinologia - Doenças da Tireoide',
    'MULTIPLE_CHOICE',
    'Gestante de 9 semanas com doença de Graves recém-diagnosticada e hipertireoidismo franco precisa de tionamida. Qual é a escolha neste momento da gestação?',
    'B',
