    'No primeiro trimestre prefere-se o propiltiouracil, pois o metimazol está associado a malformações nesse período; depois do primeiro trimestre pode-se trocar para metimazol pela hepatotoxicidade do propiltiouracil. O iodo radioativo é contraindicado na gestação.',
