(
    1,
    'Endocrinologia - Insuficiência Adrenal',
    'MULTIPLE_CHOICE',
    'Mulher de 40 anos com fadiga, perda de peso, hipotensão e hiperpigmentação de mucosas e dobras. Qual perfil laboratorial é esperado na insuficiência adrenal primária?',
    'A',
    '["A) Cortisol baixo, ACTH elevado, hiponatremia e hipercalemia", "B) Cortisol baixo, ACTH baixo e potássio normal", "C) Cortisol elevado, ACTH suprimido e hipocalemia", "D) Cortisol normal, ACTH baixo e hipernatremia"]'::jsonb,
    'Na doença de Addison a adrenal falha: o cortisol cai e o ACTH sobe, causando a hiperpigmentação. A perda de aldosterona leva a hiponatremia e hipercalemia. ACTH baixo indicaria causa central, e cortisol elevado com hipocalemia lembra síndrome de Cushing.',
    'EASY',
    'SBEM / Endocrine Society - insuficiência adrenal (questão original)',
