(
    1,
    'Endocrinologia - Insuficiência Adrenal',
    'MULTIPLE_CHOICE',
    'Paciente com doença de Addison conhecida chega com vômitos, dor abdominal, PA de 70x40 mmHg e sódio de 126 mEq/L após quadro gripal. Qual é a conduta imediata?',
    'B',
    '["A) Aguardar o cortisol sérico para confirmar a crise antes de tratar", "B) Hidrocortisona 100 mg IV em bolus e soro fisiológico 0,9%, sem aguardar resultados de exames", "C) Fludrocortisona oral isolada", "D) Dexametasona oral e alta com retorno em 48 horas"]'::jsonb,
    'Na crise adrenal o tratamento é imediato: hidrocortisona IV em dose de estresse e reposição volêmica com solução salina, coletando exames sem atrasar a medicação. Fludrocortisona oral não age a tempo e não é necessária durante a hidrocortisona em dose alta.',
    'MEDIUM',
