(
    1,
    'Endocrinologia - Insuficiência Adrenal',
    'MULTIPLE_CHOICE',
    'Homem usou prednisona 30 mg/dia por 6 meses e a suspendeu abruptamente. Evolui com astenia, náuseas e hipotensão postural. Qual achado diferencia esse quadro da insuficiência adrenal primária?',
    'C',
    '["A) Presença de hipercalemia acentuada", "B) ACTH muito elevado", "C) Ausência de hiperpigmentação e de hipercalemia, com ACTH baixo", "D) Hiperpigmentação cutânea difusa"]'::jsonb,
    'O corticoide exógeno suprime o eixo hipotálamo-hipófise, gerando insuficiência adrenal central com ACTH baixo, sem hiperpigmentação. A aldosterona depende do sistema renina-angiotensina e fica preservada, por isso não há hipercalemia; a hiponatremia pode ocorrer.',
