(
    1,
    'Gastroenterologia - DRGE e Doença Ulcerosa Péptica',
    'MULTIPLE_CHOICE',
    'Homem de 32 anos com pirose e regurgitação duas vezes por semana há 3 meses. Nega disfagia, perda de peso, anemia ou vômitos. Qual a conduta inicial mais adequada?',
    'D',
    '["A) Endoscopia digestiva alta antes de qualquer tratamento", "B) pHmetria esofágica de 24 horas para confirmar o diagnóstico", "C) Encaminhamento para fundoplicatura laparoscópica", "D) Teste terapêutico com inibidor de bomba de prótons em dose plena por 4 a 8 semanas"]'::jsonb,
    'Paciente jovem, com sintomas típicos e sem sinais de alarme, pode receber IBP empírico. Endoscopia inicial fica para sinais de alarme ou idade mais avançada; pHmetria e cirurgia são reservadas a casos refratários ou atípicos.',
    'EASY',
    'Consenso Brasileiro da Doença do Refluxo Gastroesofágico - FBG (questão original)',
