),
(
    1,
    'Gastroenterologia - DRGE e Doença Ulcerosa Péptica',
    'MULTIPLE_CHOICE',
    'Mulher de 45 anos com úlcera duodenal e teste da urease positivo, sem alergia a penicilina e sem uso prévio de macrolídeos. Qual o esquema de erradicação de primeira linha recomendado no Brasil?',
    'D',
    '["A) Metronidazol em monoterapia por 14 dias", "B) IBP em dose padrão, amoxicilina e claritromicina por apenas 5 dias", "C) IBP isolado em dose dobrada por 8 semanas, sem antibiótico", "D) IBP em dose padrão, amoxicilina 1 g e claritromicina 500 mg, de 12 em 12 horas, por 14 dias"]'::jsonb,
    'O IV Consenso Brasileiro sobre H. pylori mantém a terapia tripla padrão por 14 dias como primeira linha. Cursos curtos reduzem a taxa de erradicação e monoterapia antibiótica ou IBP isolado não erradicam a bactéria.',
    'MEDIUM',
    'IV Consenso Brasileiro sobre Helicobacter pylori - FBG 2018 (questão original)',
    TRUE
),
(
    1,
    'Gastroenterologia - DRGE e Doença Ulcerosa Péptica',
    'MULTIPLE_CHOICE',
    'Após terminar a terapia de erradicação do H. pylori, qual estratégia confirma corretamente a cura da infecção?',
    'B',
    '["A) Nenhum controle, pois a terapia tripla tem eficácia próxima de 100%", "B) Teste respiratório com ureia marcada ou antígeno fecal, ao menos 4 semanas após os antibióticos e 2 semanas sem IBP", "C) Sorologia IgG para H. pylori logo após o fim do tratamento", "D) Teste respiratório no dia seguinte ao término dos antibióticos, mantendo o IBP"]'::jsonb,
    'O controle deve usar teste de infecção ativa (respiratório, antígeno fecal ou biópsia), respeitando intervalo após antibióticos e IBP para evitar falso negativo. A sorologia IgG pode permanecer positiva por meses após a cura.',
    'MEDIUM',
    'IV Consenso Brasileiro sobre Helicobacter pylori - FBG 2018 (questão original)',
    TRUE
),
(
    1,
    'Gastroenterologia - Hemorragia Digestiva',
    'MULTIPLE_CHOICE',
    'Homem cirrótico chega com hematêmese volumosa, PA 90x60 mmHg e FC 118 bpm. Além da ressuscitação volêmica cautelosa, o que deve ser iniciado antes da endoscopia?',
    'A',
    '["A) Vasoconstritor esplâncnico (terlipressina ou octreotida) e antibioticoprofilaxia com ceftriaxona", "B) Plasma fresco congelado para normalizar o INR antes da endoscopia", "C) Propranolol endovenoso para reduzir a pressão portal", "D) Transfusão de hemácias até hemoglobina acima de 10 g/dL"]'::jsonb,
    'Na suspeita de hemorragia varicosa, vasoativo e antibiótico profilático reduzem ressangramento, infecção e mortalidade; a endoscopia com ligadura deve ocorrer em até 12 horas. Betabloqueador não é usado na fase aguda e hipertransfusão aumenta a pressão portal.',
    'MEDIUM',
    'Consenso Baveno VII e Sociedade Brasileira de Hepatologia (questão original)',
    TRUE
),
(
    1,
    'Gastroenterologia - Hemorragia Digestiva',
    'MULTIPLE_CHOICE',
    'Mulher de 60 anos, sem coronariopatia, com hemorragia digestiva alta por úlcera, hemodinamicamente estável após cristaloide, Hb 7,8 g/dL. Qual a estratégia transfusional recomendada?',
    'A',
    '["A) Restritiva: transfundir se Hb menor que 7 g/dL, com alvo entre 7 e 9 g/dL", "B) Liberal: transfundir para manter Hb acima de 10 g/dL", "C) Transfundir apenas se o hematócrito da admissão for menor que 35%", "D) Transfundir duas unidades de hemácias em todo sangramento digestivo alto"]'::jsonb,
    'Em pacientes estáveis sem doença coronariana, a estratégia restritiva reduz ressangramento e mortalidade em relação à liberal. O hematócrito da admissão subestima a perda aguda e não deve guiar sozinho a transfusão.',
    'MEDIUM',
    'Diretrizes de hemorragia digestiva alta não varicosa - FBG/SOBED (questão original)',
