),
(
    1,
    'Gastroenterologia - Hemorragia Digestiva',
    'MULTIPLE_CHOICE',
    'Na endoscopia de paciente com hemorragia digestiva alta por úlcera gástrica, qual achado indica tratamento endoscópico hemostático?',
    'D',
    '["A) Úlcera de base limpa recoberta por fibrina", "B) Erosões superficiais múltiplas sem estigmas de sangramento", "C) Mancha plana pigmentada no fundo da úlcera", "D) Vaso visível não sangrante no leito da úlcera"]'::jsonb,
    'Vaso visível não sangrante (Forrest IIa) tem alto risco de ressangramento e exige hemostasia endoscópica associada a IBP. Base limpa (Forrest III) e mancha plana pigmentada (Forrest IIc) têm baixo risco e não precisam de terapia endoscópica.',
