(
    1,
    'Hematologia - Anticoagulação e Trombocitopenias',
    'MULTIPLE_CHOICE',
    'Mulher de 30 anos com petéquias e gengivorragia, plaquetas 12.000/mm³, demais séries normais, esfregaço sem esquizócitos e sem esplenomegalia. Qual o tratamento de primeira linha?',
    'A',
    '["A) Corticoide, como prednisona ou dexametasona em pulso", "B) Transfusão profilática de plaquetas como tratamento principal", "C) Plasmaférese de urgência", "D) Esplenectomia imediata"]'::jsonb,
    'Plaquetopenia isolada sem outra causa sugere púrpura trombocitopênica imune; com sangramento e plaquetas muito baixas, o corticoide é a primeira linha (imunoglobulina se sangramento grave). Plasmaférese é tratamento da PTT, que cursa com esquizócitos.',
    'MEDIUM',
    'Associação Brasileira de Hematologia e Hemoterapia - PTI (questão original)',
    TRUE
),
(
    1,
    'Hematologia - Anticoagulação e Trombocitopenias',
    'MULTIPLE_CHOICE',
    'Homem em uso de varfarina por fibrilação atrial chega com melena volumosa, hipotensão e INR 6,5. Além da ressuscitação, qual a conduta para reverter a anticoagulação?',
    'B',
    '["A) Administrar vitamina K oral e repetir o INR em 48 horas", "B) Suspender a varfarina e administrar vitamina K endovenosa e concentrado de complexo protrombínico", "C) Administrar protamina endovenosa", "D) Apenas suspender a varfarina e aguardar a queda espontânea do INR"]'::jsonb,
    'Sangramento grave com antagonista da vitamina K exige reversão rápida com complexo protrombínico (ou plasma, se indisponível) somado à vitamina K endovenosa, que sustenta o efeito. Protamina reverte heparina, não varfarina.',
    'HARD',
    'Diretriz Brasileira de Antiagregantes e Anticoagulantes - SBC (questão original)',
    TRUE
),
(
    1,
    'Hematologia - Anticoagulação e Trombocitopenias',
    'MULTIPLE_CHOICE',
    'Paciente internado em uso de heparina não fracionada há 7 dias tem queda das plaquetas de 250.000 para 90.000/mm³ e nova trombose venosa profunda. Qual a conduta?',
    'C',
    '["A) Iniciar varfarina imediatamente como único anticoagulante", "B) Transfundir plaquetas profilaticamente e manter a heparina", "C) Suspender toda heparina e iniciar anticoagulante não heparínico, como argatrobana ou fondaparinux", "D) Trocar a heparina não fracionada por enoxaparina"]'::jsonb,
    'Queda maior que 50% entre o 5º e o 10º dia com trombose sugere trombocitopenia induzida por heparina. Toda heparina, inclusive a de baixo peso, deve ser suspensa; varfarina isolada na fase aguda pode causar necrose cutânea e gangrena venosa.',
    'HARD',
    'Associação Brasileira de Hematologia e Hemoterapia - TIH (questão original)',
    TRUE
),
(
    1,
    'Hematologia - Diagnóstico Diferencial de Anemias',
    'MULTIPLE_CHOICE',
    'Mulher com anemia ferropriva por menorragia inicia sulfato ferroso oral. Qual orientação está correta?',
    'C',
    '["A) Usar ferro endovenoso como primeira escolha para todas as pacientes", "B) Tomar o comprimido junto com leite ou antiácido para melhorar a absorção", "C) Manter o ferro por cerca de 3 meses após a normalização da hemoglobina para repor os estoques", "D) Suspender o ferro assim que a hemoglobina normalizar"]'::jsonb,
    'Após corrigir a Hb, mantém-se o ferro para recompor os depósitos (guiado pela ferritina). Leite e antiácidos reduzem a absorção, e o ferro endovenoso fica para intolerância, má absorção ou necessidade de reposição rápida.',
    'EASY',
    'Associação Brasileira de Hematologia e Hemoterapia - anemias carenciais (questão original)',
