),
(
    1,
    'Hematologia - Diagnóstico Diferencial de Anemias',
    'MULTIPLE_CHOICE',
    'Homem de 68 anos, diabético em uso de metformina há 10 anos, com fadiga, parestesias em pés e perda de sensibilidade vibratória. Hb 9,5 g/dL e VCM 114 fL. Qual o diagnóstico mais provável?',
    'A',
    '["A) Anemia megaloblástica por deficiência de vitamina B12", "B) Anemia ferropriva", "C) Anemia megaloblástica por deficiência de ácido fólico", "D) Anemia da doença crônica"]'::jsonb,
    'O uso prolongado de metformina reduz a absorção de B12; macrocitose com neuropatia periférica e perda vibratória sugere deficiência de B12. A deficiência de folato causa macrocitose, mas não a neuropatia, e as outras anemias não são macrocíticas.',
