(
    1,
    'Hematologia - Diagnóstico Diferencial de Anemias',
    'MULTIPLE_CHOICE',
    'Mulher de 35 anos com fadiga e icterícia. Hb 7,2 g/dL, reticulócitos 9%, LDH elevada, haptoglobina indetectável, esferócitos no esfregaço e Coombs direto positivo para IgG. Qual o tratamento de primeira linha?',
    'B',
    '["A) Reposição de ferro endovenoso", "B) Prednisona em torno de 1 mg/kg/dia", "C) Esplenectomia imediata", "D) Transfusão de plaquetas"]'::jsonb,
    'O quadro é de anemia hemolítica autoimune por anticorpos quentes (IgG), cuja primeira linha é o corticoide. Esplenectomia e rituximabe são opções de segunda linha; ferro não corrige hemólise e não há plaquetopenia descrita.',
    'HARD',
    'Associação Brasileira de Hematologia e Hemoterapia - anemias hemolíticas (questão original)',
    TRUE
),
(
    1,
    'Hepatologia - Cirrose e Complicações',
    'MULTIPLE_CHOICE',
    'Cirrótico com ascite apresenta dor abdominal difusa e febre baixa. Qual achado na paracentese diagnóstica confirma peritonite bacteriana espontânea?',
    'D',
    '["A) Leucócitos totais acima de 100 células/mm³ com predomínio linfocitário", "B) Gradiente albumina soro-ascite maior que 1,1 g/dL", "C) Proteína total do líquido ascítico menor que 1,5 g/dL", "D) Contagem de polimorfonucleares maior ou igual a 250 células/mm³ no líquido ascítico"]'::jsonb,
    'O diagnóstico de PBE é feito por PMN maior ou igual a 250/mm³, mesmo com cultura negativa. GASA alto só indica hipertensão portal e proteína baixa é fator de risco, não critério diagnóstico.',
    'EASY',
    'Diretriz da Sociedade Brasileira de Hepatologia - complicações da cirrose (questão original)',
    TRUE
),
(
    1,
    'Hepatologia - Cirrose e Complicações',
    'MULTIPLE_CHOICE',
    'Cirrótico com peritonite bacteriana espontânea, creatinina 1,6 mg/dL e bilirrubina 4,5 mg/dL, já em uso de ceftriaxona. Qual medida adicional reduz a incidência de lesão renal e a mortalidade?',
    'B',
    '["A) Furosemida em dose alta para manter diurese", "B) Albumina endovenosa 1,5 g/kg no primeiro dia e 1 g/kg no terceiro dia", "C) Associação de aminoglicosídeo para ampliar o espectro", "D) Paracentese de grande volume diária até secar a ascite"]'::jsonb,
    'A albumina no D1 e D3 reduz síndrome hepatorrenal e mortalidade, sobretudo com disfunção renal ou bilirrubina elevada. Diuréticos em excesso e aminoglicosídeos são nefrotóxicos nesse contexto.',
    'MEDIUM',
    'Diretriz da Sociedade Brasileira de Hepatologia - complicações da cirrose (questão original)',
    TRUE
),
(
    1,
    'Hepatologia - Cirrose e Complicações',
    'MULTIPLE_CHOICE',
    'Cirrótico é trazido sonolento e desorientado, com asterixis, após episódio de constipação. Não há sinais de sangramento ou infecção. Qual o tratamento inicial de escolha?',
    'D',
    '["A) Restrição proteica rigorosa, abaixo de 0,5 g/kg/dia", "B) Flumazenil de rotina em todos os casos", "C) Benzodiazepínico para controle da agitação", "D) Lactulose titulada para 2 a 3 evacuações pastosas por dia, corrigindo o fator precipitante"]'::jsonb,
    'A lactulose é a base do tratamento da encefalopatia hepática, junto com a correção do precipitante. Restrição proteica rigorosa piora a sarcopenia e não é recomendada; benzodiazepínicos podem precipitar ou agravar o quadro.',
    'MEDIUM',
    'Diretriz da Sociedade Brasileira de Hepatologia - encefalopatia hepática (questão original)',
    TRUE
),
(
    1,
    'Hepatologia - Hepatites Virais',
    'MULTIPLE_CHOICE',
    'Homem de 50 anos tem teste rápido anti-HCV reagente em campanha de testagem. Pelo protocolo do Ministério da Saúde, qual o próximo passo diagnóstico?',
    'B',
    '["A) Repetir o anti-HCV em 6 meses e só então decidir a conduta", "B) Solicitar carga viral (HCV-RNA) para confirmar infecção ativa", "C) Considerar infecção resolvida se as transaminases estiverem normais", "D) Indicar biópsia hepática para confirmar o diagnóstico"]'::jsonb,
    'O anti-HCV indica exposição, mas cerca de um quarto dos infectados elimina o vírus espontaneamente; a confirmação de infecção ativa exige HCV-RNA detectável. Transaminases normais não excluem hepatite C crônica.',
    'EASY',
    'PCDT Hepatite C e Coinfecções - Ministério da Saúde (questão original)',
    TRUE
),
(
    1,
    'Hepatologia - Hepatites Virais',
    'MULTIPLE_CHOICE',
    'Doador de sangue tem a seguinte sorologia: HBsAg não reagente, anti-HBc total reagente e anti-HBs reagente. Qual a interpretação?',
    'D',
    '["A) Imunidade exclusivamente vacinal", "B) Hepatite B crônica com replicação viral", "C) Hepatite B aguda em fase inicial", "D) Infecção pelo vírus B no passado, resolvida, com imunidade natural"]'::jsonb,
    'Anti-HBc total indica contato com o vírus e o anti-HBs com HBsAg negativo indica resolução. A vacina gera apenas anti-HBs, sem anti-HBc; infecção crônica ou aguda inicial teriam HBsAg reagente.',
    'MEDIUM',
    'PCDT Hepatite B e Coinfecções - Ministério da Saúde (questão original)',
    TRUE
),
(
    1,
    'Hepatologia - Hepatites Virais',
    'MULTIPLE_CHOICE',
    'Paciente com icterícia há 3 semanas apresenta HBsAg não reagente, anti-HBs não reagente e anti-HBc IgM reagente. Qual a interpretação mais provável?',
    'B',
    '["A) Infecção antiga curada, sem relação com o quadro atual", "B) Hepatite B aguda na fase de janela imunológica", "C) Hepatite B crônica com mutação pré-core", "D) Resultado compatível apenas com vacinação recente"]'::jsonb,
    'Na janela, o HBsAg já negativou e o anti-HBs ainda não surgiu; o anti-HBc IgM é o único marcador de infecção aguda. Vacinação não gera anti-HBc e infecção antiga cursa com anti-HBc IgG, não IgM.',
    'HARD',
    'PCDT Hepatite B e Coinfecções - Ministério da Saúde (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Dengue e Arboviroses',
    'MULTIPLE_CHOICE',
    'Homem de 72 anos, hipertenso, com dengue no 3º dia de febre, sem sinais de alarme e sem sinais de choque. Qual é a conduta adequada?',
    'A',
    '["A) Solicitar hemograma e manter hidratação oral supervisionada na unidade até o resultado", "B) Liberar para casa com hidratação oral, sem exames", "C) Iniciar hidratação venosa imediata em leito de observação", "D) Prescrever AAS para a febre e a mialgia"]'::jsonb,
    'Idade acima de 65 anos e comorbidades colocam o paciente sem sinais de alarme no grupo B do Ministério da Saúde, com hemograma obrigatório e hidratação oral supervisionada. AAS e anti-inflamatórios são contraindicados na dengue pelo risco de sangramento.',
    'EASY',
    'Dengue: diagnóstico e manejo clínico - Ministério da Saúde 2024 (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Dengue e Arboviroses',
    'MULTIPLE_CHOICE',
    'Mulher de 25 anos no 5º dia de febre por dengue, já afebril, refere dor abdominal intensa e contínua e vômitos persistentes. PA 110x70 mmHg, sem sinais de choque. Qual é a conduta adequada?',
    'B',
    '["A) Hidratação oral e acompanhamento ambulatorial, com retorno se surgirem sinais de alarme", "B) Hidratação venosa imediata em leito de observação ou internação, com reavaliação clínica e laboratorial frequente", "C) Hemograma e hidratação oral supervisionada na unidade até o resultado", "D) Expansão volêmica rápida em unidade de terapia intensiva por choque"]'::jsonb,
    'Dor abdominal intensa e contínua e vômitos persistentes são sinais de alarme: a paciente é do grupo C da classificação do Ministério da Saúde e precisa de hidratação venosa imediata. O grupo D exige choque, sangramento grave ou disfunção grave de órgão, ausentes no caso.',
    'MEDIUM',
    'Dengue: diagnóstico e manejo clínico - Ministério da Saúde 2024 (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Dengue e Arboviroses',
    'MULTIPLE_CHOICE',
    'Mulher de 50 anos com febre alta há 2 dias e artralgia intensa, simétrica, em mãos e tornozelos, em área com circulação de chikungunya e dengue. Qual a analgesia inicial recomendada?',
    'C',
    '["A) Ibuprofeno em dose plena desde o primeiro dia", "B) Ácido acetilsalicílico em dose anti-inflamatória", "C) Dipirona ou paracetamol, evitando anti-inflamatórios enquanto não se descarta dengue", "D) Prednisona 20 mg/dia na fase aguda"]'::jsonb,
    'Na fase aguda da chikungunya, usam-se dipirona ou paracetamol; AINEs devem ser evitados até excluir dengue e o AAS é contraindicado. Corticoide não é recomendado na fase aguda, ficando para a fase subaguda.',
    'MEDIUM',
    'Chikungunya: manejo clínico - Ministério da Saúde (questão original)',
    TRUE
),
(
    1,
    'Infectologia - HIV: Diagnóstico e TARV',
    'MULTIPLE_CHOICE',
    'Homem de 28 anos com diagnóstico recente de HIV, sem tuberculose ativa, não gestante e com função renal normal. Qual o esquema antirretroviral inicial preferencial pelo PCDT do Ministério da Saúde?',
    'C',
    '["A) Tenofovir, lamivudina e efavirenz", "B) Zidovudina, lamivudina e lopinavir/ritonavir", "C) Tenofovir, lamivudina e dolutegravir", "D) Dolutegravir em monoterapia"]'::jsonb,
    'O esquema preferencial atual é TDF/3TC associado a dolutegravir, pela alta potência, barreira genética elevada e boa tolerância. O efavirenz deixou de ser preferencial e monoterapia não é aceitável no início do tratamento.',
    'EASY',
    'PCDT Manejo da Infecção pelo HIV em Adultos - Ministério da Saúde (questão original)',
    TRUE
),
(
    1,
    'Infectologia - HIV: Diagnóstico e TARV',
    'MULTIPLE_CHOICE',
    'Na UBS, uma mulher de 30 anos tem dois testes rápidos para HIV, de fabricantes diferentes, ambos reagentes, realizados em sequência. Qual a conduta?',
    'A',
    '["A) Considerar o diagnóstico estabelecido e solicitar carga viral e contagem de CD4 na vinculação ao serviço", "B) Solicitar ELISA de quarta geração e só então firmar o diagnóstico", "C) Aguardar Western blot antes de comunicar o diagnóstico", "D) Repetir os dois testes rápidos após 30 dias para confirmar"]'::jsonb,
    'No fluxograma com dois testes rápidos, TR1 e TR2 reagentes definem amostra reagente para HIV; a carga viral coletada na sequência também ajuda a afastar erro de amostra. Não é necessário Western blot nem repetir a testagem antes de vincular ao cuidado.',
    'MEDIUM',
    'Manual Técnico para o Diagnóstico da Infecção pelo HIV - MS (questão original)',
    TRUE
),
(
    1,
    'Infectologia - HIV: Diagnóstico e TARV',
    'MULTIPLE_CHOICE',
    'Pessoa vivendo com HIV inicia tratamento para tuberculose pulmonar com RHZE e vai iniciar TARV com tenofovir, lamivudina e dolutegravir. Qual ajuste é necessário?',
    'A',
    '["A) Dolutegravir 50 mg de 12 em 12 horas enquanto durar o uso de rifampicina", "B) Manter dolutegravir 50 mg uma vez ao dia, sem ajuste", "C) Retirar a lamivudina para evitar interação com a rifampicina", "D) Substituir a rifampicina por isoniazida em monoterapia"]'::jsonb,
    'A rifampicina induz o metabolismo do dolutegravir, reduzindo seus níveis; por isso a dose é dobrada (50 mg 12/12 h) durante o uso de rifampicina e por cerca de 2 semanas após. Retirar a rifampicina enfraquece o esquema de TB.',
    'HARD',
    'PCDT Manejo da Infecção pelo HIV em Adultos - Ministério da Saúde (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Infecção Urinária e Endocardite',
    'MULTIPLE_CHOICE',
    'Mulher de 26 anos, não gestante, com disúria e polaciúria há 1 dia, sem febre ou dor lombar. Qual a conduta mais adequada?',
    'A',
    '["A) Tratamento empírico com fosfomicina 3 g em dose única, sem necessidade de urocultura", "B) Amoxicilina por 7 dias", "C) Ciprofloxacino por 14 dias após urocultura obrigatória", "D) Internação para antibiótico endovenoso"]'::jsonb,
    'Cistite não complicada em mulher pode ser tratada empiricamente com fosfomicina dose única ou nitrofurantoína por 5 dias. Fluoroquinolonas devem ser poupadas e a amoxicilina tem alta resistência entre as enterobactérias.',
    'EASY',
    'Diretrizes brasileiras de ITU não complicada - SBU/SBI (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Infecção Urinária e Endocardite',
    'MULTIPLE_CHOICE',
    'Idosa de 82 anos, institucionalizada, sem febre, disúria ou alteração do estado mental, tem urocultura de rotina com mais de 100.000 UFC/mL de E. coli. Qual a conduta?',
    'D',
    '["A) Iniciar profilaxia antibiótica contínua", "B) Repetir a urocultura semanalmente e tratar se persistir", "C) Tratar com antibiótico por 7 dias para evitar pielonefrite", "D) Não tratar, pois se trata de bacteriúria assintomática"]'::jsonb,
    'Bacteriúria assintomática só deve ser tratada em gestantes e antes de procedimento urológico com sangramento de mucosa. Em idosos, o tratamento não reduz desfechos e aumenta resistência e efeitos adversos.',
    'MEDIUM',
    'Diretrizes brasileiras de ITU - SBU/SBI (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Infecção Urinária e Endocardite',
    'MULTIPLE_CHOICE',
    'Na suspeita de endocardite infecciosa, qual dos achados abaixo é critério maior de Duke?',
    'B',
    '["A) Uso de drogas injetáveis", "B) Vegetação valvar demonstrada ao ecocardiograma", "C) Febre maior ou igual a 38 °C", "D) Nódulos de Osler"]'::jsonb,
    'Evidência de acometimento endocárdico (vegetação, abscesso ou nova regurgitação) e hemoculturas típicas são os critérios maiores. Febre, fenômenos imunológicos como nódulos de Osler e predisposição são critérios menores.',
    'MEDIUM',
    'Critérios de Duke modificados - Diretriz Brasileira de Valvopatias SBC (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Infecção Urinária e Endocardite',
    'MULTIPLE_CHOICE',
    'Homem de 30 anos, usuário de drogas injetáveis, com febre alta, sopro sistólico que aumenta na inspiração e múltiplos nódulos pulmonares escavados à tomografia. Qual a valva e o agente mais prováveis?',
    'A',
    '["A) Valva tricúspide e Staphylococcus aureus", "B) Valva aórtica e Enterococcus faecalis", "C) Valva pulmonar e Candida albicans", "D) Valva mitral e Streptococcus do grupo viridans"]'::jsonb,
    'Em usuários de drogas injetáveis predomina a endocardite de câmaras direitas por S. aureus; o sopro que aumenta na inspiração (Rivero-Carvallo) e os êmbolos sépticos pulmonares reforçam a tricúspide. Estreptococos viridans associam-se a valvas esquerdas e foco dentário.',
    'HARD',
    'Diretriz Brasileira de Valvopatias - SBC (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Sífilis Adquirida',
    'MULTIPLE_CHOICE',
    'Homem de 24 anos com úlcera genital única, indolor, de bordas endurecidas, surgida há 10 dias, com teste rápido treponêmico reagente. Qual o tratamento?',
    'A',
    '["A) Penicilina G benzatina 2,4 milhões UI intramuscular em dose única", "B) Azitromicina 1 g dose única como primeira escolha", "C) Penicilina G benzatina 2,4 milhões UI semanal por 3 semanas", "D) Penicilina G cristalina endovenosa por 14 dias"]'::jsonb,
    'Cancro duro caracteriza sífilis primária (recente), tratada com dose única de 2,4 milhões UI de penicilina benzatina. Três doses são para sífilis tardia e penicilina cristalina é para neurossífilis.',
    'EASY',
    'PCDT Atenção Integral às Pessoas com IST - Ministério da Saúde 2022 (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Sífilis Adquirida',
    'MULTIPLE_CHOICE',
    'Mulher não gestante, assintomática, tem VDRL 1:8 e teste treponêmico reagente em exame admissional, sem tratamento prévio e sem saber quando se infectou. Qual o tratamento?',
    'D',
    '["A) Doxiciclina por 7 dias como primeira escolha", "B) Penicilina G benzatina 2,4 milhões UI em dose única", "C) Nenhum tratamento, por ser provável cicatriz sorológica", "D) Penicilina G benzatina 2,4 milhões UI intramuscular semanal por 3 semanas"]'::jsonb,
    'Sífilis latente de duração ignorada é tratada como tardia: 3 doses semanais de 2,4 milhões UI (7,2 milhões UI no total). Sem tratamento prévio documentado, não se pode assumir cicatriz sorológica.',
    'MEDIUM',
    'PCDT Atenção Integral às Pessoas com IST - Ministério da Saúde 2022 (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Sífilis Adquirida',
    'MULTIPLE_CHOICE',
    'Homem tratado adequadamente para sífilis secundária com VDRL inicial 1:32. Seis meses depois, o VDRL é 1:128. Qual a interpretação e conduta?',
    'D',
    '["A) Oscilação esperada do teste, bastando repetir em 12 meses", "B) Cicatriz sorológica, sem necessidade de nova conduta", "C) Falha comprovada pela persistência do teste treponêmico reagente", "D) Aumento de duas diluições sugere reinfecção ou reativação; deve ser retratado e investigado"]'::jsonb,
    'Elevação de duas ou mais diluições do VDRL indica reinfecção ou reativação e exige retratamento e avaliação de neurossífilis quando indicado. O teste treponêmico costuma permanecer reagente por toda a vida e não serve para controle de cura.',
    'HARD',
    'PCDT Atenção Integral às Pessoas com IST - Ministério da Saúde 2022 (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Tuberculose',
    'MULTIPLE_CHOICE',
    'Adulto de 40 anos, 70 kg, com tuberculose pulmonar sensível, caso novo. Qual o esquema básico preconizado pelo Ministério da Saúde?',
    'A',
    '["A) Rifampicina, isoniazida, pirazinamida e etambutol por 2 meses, seguidos de rifampicina e isoniazida por 4 meses", "B) Rifampicina, isoniazida e pirazinamida por 2 meses, seguidos de isoniazida por 10 meses", "C) Rifampicina, isoniazida, pirazinamida e etambutol por 6 meses contínuos", "D) Isoniazida isolada por 9 meses"]'::jsonb,
    'O esquema básico para adultos é 2RHZE/4RH, em doses fixas combinadas por faixa de peso. Isoniazida isolada é tratamento de infecção latente, não de doença ativa.',
    'EASY',
    'Manual de Recomendações para o Controle da Tuberculose no Brasil - MS (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Tuberculose',
    'MULTIPLE_CHOICE',
    'Homem com tosse há 4 semanas, febre vespertina e emagrecimento. Qual exame é recomendado como diagnóstico inicial, por detectar o M. tuberculosis e a resistência à rifampicina em poucas horas?',
    'C',
    '["A) Prova tuberculínica", "B) Radiografia de tórax isolada", "C) Teste rápido molecular para tuberculose (TRM-TB) no escarro", "D) Dosagem de adenosina deaminase sérica"]'::jsonb,
    'O TRM-TB detecta o DNA do bacilo e mutações associadas à resistência à rifampicina em cerca de 2 horas. A prova tuberculínica indica infecção, não doença ativa, e a radiografia é sugestiva, não confirmatória.',
    'MEDIUM',
    'Manual de Recomendações para o Controle da Tuberculose no Brasil - MS (questão original)',
    TRUE
),
(
    1,
    'Infectologia - Tuberculose',
    'MULTIPLE_CHOICE',
    'Contato domiciliar adulto de paciente bacilífero está assintomático, tem radiografia de tórax normal e prova tuberculínica de 8 mm. Qual a conduta?',
    'C',
    '["A) Apenas orientar retorno se surgirem sintomas, sem tratamento", "B) Iniciar o esquema RHZE por 6 meses", "C) Tratar infecção latente, por exemplo com isoniazida por 6 a 9 meses, rifampicina por 4 meses ou rifapentina com isoniazida", "D) Revacinar com BCG e repetir a prova tuberculínica em 1 ano"]'::jsonb,
    'Em contatos com PT maior ou igual a 5 mm e doença ativa afastada (sem sintomas e radiografia normal), indica-se tratamento da infecção latente. RHZE é para doença ativa e a revacinação BCG não é recomendada.',
    'HARD',
    'Protocolo de Vigilância da Infecção Latente pelo M. tuberculosis - MS (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Distúrbios Hidroeletrolíticos e Ácido-Base',
    'MULTIPLE_CHOICE',
    'Paciente com DRC tem potássio de 7,1 mEq/L e ECG com ondas T apiculadas e alargamento do QRS. Qual é a primeira medida?',
    'D',
    '["A) Poliestirenossulfonato de cálcio oral como medida isolada", "B) Furosemida intravenosa como medida isolada", "C) Aguardar nova dosagem de potássio para confirmar", "D) Gluconato de cálcio a 10% intravenoso"]'::jsonb,
    'Com alterações eletrocardiográficas, a prioridade é estabilizar a membrana do miocárdio com cálcio IV, que age em minutos mas não reduz o potássio. Em seguida, insulina com glicose e beta-2 agonista deslocam o potássio para as células, e resinas, diuréticos ou diálise o removem.',
    'MEDIUM',
    'SBN / literatura nefrológica de referência (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Distúrbios Hidroeletrolíticos e Ácido-Base',
    'MULTIPLE_CHOICE',
    'Gasometria e eletrólitos: pH 7,20, HCO3 12 mEq/L, Na 138 mEq/L, Cl 104 mEq/L. Qual condição é compatível com o ânion gap encontrado?',
    'A',
    '["A) Acidose lática por hipoperfusão tecidual", "B) Diarreia aguda volumosa", "C) Acidose tubular renal distal", "D) Uso de acetazolamida"]'::jsonb,
    'Ânion gap = 138 - (104 + 12) = 22 mEq/L, elevado, indicando acúmulo de ânion não medido, como lactato, cetoânions ou toxinas. Diarreia, acidose tubular renal e acetazolamida causam acidose hiperclorêmica com ânion gap normal, por perda de bicarbonato.',
    'MEDIUM',
    'SBN / literatura nefrológica de referência (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Distúrbios Hidroeletrolíticos e Ácido-Base',
    'MULTIPLE_CHOICE',
    'Idosa em uso de hidroclorotiazida tem sódio de 114 mEq/L, com náuseas leves e sem convulsão ou rebaixamento, em quadro há vários dias. Qual princípio deve guiar a correção?',
    'C',
    '["A) Corrigir até 135 mEq/L nas primeiras 12 horas", "B) Elevar o sódio em 20 mEq/L no primeiro dia, já que é crônica", "C) Limitar a elevação do sódio a cerca de 8 a 10 mEq/L nas primeiras 24 horas", "D) Não há limite, desde que se use soro fisiológico 0,9%"]'::jsonb,
    'Na hiponatremia crônica o cérebro se adaptou, e a correção rápida pode causar síndrome de desmielinização osmótica. O aumento deve ficar em torno de 8 a 10 mEq/L em 24 horas, menos em pacientes de alto risco, e mesmo com soro fisiológico o sódio pode subir rápido demais.',
    'HARD',
    'SBN / literatura nefrológica de referência (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Doença Renal Crônica',
    'MULTIPLE_CHOICE',
    'Pelo KDIGO, qual condição define doença renal crônica?',
    'D',
    '["A) Creatinina acima de 1,5 mg/dL em uma única dosagem", "B) TFG menor que 90 mL/min/1,73m² por mais de 2 semanas", "C) Necessidade de terapia renal substitutiva", "D) TFG menor que 60 mL/min/1,73m² ou marcador de lesão renal, como albuminúria de 30 mg/g ou mais, por mais de 3 meses"]'::jsonb,
    'A DRC é definida por alteração da estrutura ou da função renal por mais de 3 meses com implicação para a saúde: TFG abaixo de 60 ou marcadores de lesão, como albuminúria de pelo menos 30 mg/g. Uma dosagem isolada não define cronicidade, e diálise é só o estágio final.',
    'EASY',
    'KDIGO 2024 / SBN - doença renal crônica (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Doença Renal Crônica',
    'MULTIPLE_CHOICE',
    'Paciente com DRC estágio 4 tem hemoglobina de 8,9 g/dL, anemia normocítica, ferritina de 60 ng/mL e saturação de transferrina de 12%. Qual é o passo inicial?',
    'D',
    '["A) Iniciar eritropoetina imediatamente, sem avaliar ferro", "B) Transfundir para manter hemoglobina acima de 13 g/dL", "C) Prescrever ácido fólico isolado", "D) Repor ferro antes de considerar agente estimulador da eritropoese"]'::jsonb,
    'Ferritina e saturação de transferrina baixas indicam deficiência de ferro, que deve ser corrigida antes de iniciar agente estimulador, sob pena de má resposta. Manter hemoglobina alta, acima de cerca de 11,5 g/dL, com esses agentes aumenta risco de AVC e trombose.',
    'MEDIUM',
    'KDIGO 2024 / SBN - doença renal crônica (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Doença Renal Crônica',
    'MULTIPLE_CHOICE',
    'No distúrbio mineral e ósseo da DRC avançada, qual é o perfil laboratorial típico do hiperparatireoidismo secundário?',
    'C',
    '["A) Fósforo baixo, cálcio elevado, PTH suprimido e calcitriol elevado", "B) Fósforo normal, cálcio elevado, PTH elevado e calcitriol elevado", "C) Fósforo elevado, cálcio normal ou baixo, PTH elevado e calcitriol baixo", "D) Fósforo baixo, cálcio baixo, PTH baixo e calcitriol normal"]'::jsonb,
    'Com a perda de néfrons há retenção de fósforo e queda da ativação renal da vitamina D (calcitriol), o que reduz o cálcio e estimula a paratireoide. O resultado é PTH elevado com fósforo alto. Cálcio alto com PTH alto sugere hiperparatireoidismo primário ou terciário.',
    'HARD',
    'KDIGO 2024 / SBN - doença renal crônica (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Injúria Renal Aguda',
    'MULTIPLE_CHOICE',
    'Idoso com vômitos há 3 dias evolui com aumento de creatinina e oligúria. Qual achado urinário sugere IRA pré-renal, e não necrose tubular aguda?',
    'B',
    '["A) Fração de excreção de sódio maior que 2%", "B) Fração de excreção de sódio menor que 1%", "C) Cilindros granulosos pigmentados abundantes", "D) Osmolaridade urinária semelhante à plasmática"]'::jsonb,
    'Na IRA pré-renal o túbulo está íntegro e reabsorve sódio e água avidamente, com FENa abaixo de 1% e urina concentrada. Na necrose tubular aguda a FENa passa de 2%, a urina fica isostenúrica e aparecem cilindros granulosos.',
    'EASY',
    'KDIGO - injúria renal aguda (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Injúria Renal Aguda',
    'MULTIPLE_CHOICE',
    'Paciente com IRA grave em tratamento clínico. Qual dos achados abaixo é indicação de diálise de urgência?',
    'A',
    '["A) Pericardite urêmica com atrito pericárdico", "B) Creatinina de 4,0 mg/dL isolada, sem complicações", "C) Ureia de 120 mg/dL em paciente assintomático", "D) Oligúria há 8 horas com potássio e bicarbonato normais"]'::jsonb,
    'Diálise de urgência é indicada por complicações refratárias: hipercalemia, acidose metabólica grave, hipervolemia, intoxicações dialisáveis e uremia sintomática, como pericardite ou encefalopatia. Valores isolados de creatinina ou ureia, sem repercussão, não são indicação por si.',
    'MEDIUM',
    'KDIGO - injúria renal aguda (questão original)',
    TRUE
),
(
    1,
    'Nefrologia - Injúria Renal Aguda',
    'MULTIPLE_CHOICE',
    'Diabético com TFG de 35 mL/min/1,73m² fará tomografia com contraste iodado intravenoso, indispensável para o diagnóstico. Qual medida tem melhor evidência para reduzir o risco de lesão renal associada ao contraste?',
    'B',
    '["A) Furosemida intravenosa profilática", "B) Hidratação com cristaloide isotônico antes e depois do exame", "C) Hemodiálise profilática logo após o exame", "D) Manitol intravenoso antes da injeção do contraste"]'::jsonb,
    'A medida recomendada é a expansão volêmica com cristaloide isotônico, junto com a menor dose possível de contraste e a suspensão temporária de nefrotóxicos. Diuréticos e manitol podem piorar a lesão, e a hemodiálise profilática não traz benefício.',
    'MEDIUM',
    'KDIGO - injúria renal aguda (questão original)',
    TRUE
),
(
    1,
    'Neurologia - AVC e Demências',
    'MULTIPLE_CHOICE',
    'Mulher de 76 anos com declínio progressivo de memória episódica há 2 anos, diagnóstico de doença de Alzheimer leve e causas reversíveis afastadas. Qual o tratamento farmacológico inicial?',
    'C',
    '["A) Haloperidol contínuo", "B) Memantina como única opção para a fase leve", "C) Inibidor da acetilcolinesterase, como donepezila, rivastigmina ou galantamina", "D) Benzodiazepínico ao deitar"]'::jsonb,
    'Inibidores da acetilcolinesterase são a primeira linha na doença de Alzheimer leve a moderada, pelo PCDT. A memantina é indicada nas fases moderada a grave; antipsicóticos e benzodiazepínicos pioram cognição e quedas.',
    'EASY',
    'PCDT Doença de Alzheimer - Ministério da Saúde (questão original)',
    TRUE
),
(
    1,
    'Neurologia - AVC e Demências',
    'MULTIPLE_CHOICE',
    'Mulher de 70 anos teve AIT com amaurose fugaz à direita há 5 dias. O Doppler mostra estenose de 80% na carótida interna direita. Qual a conduta para prevenção secundária?',
    'C',
    '["A) Apenas tratamento clínico, sem indicação de intervenção", "B) Anticoagulação oral permanente", "C) Endarterectomia carotídea, preferencialmente nas primeiras 2 semanas, com terapia clínica otimizada", "D) Endarterectomia somente se houver novo evento"]'::jsonb,
    'Estenose carotídea sintomática de 70 a 99% tem indicação de revascularização, com maior benefício quando feita precocemente, associada a antiagregante, estatina e controle pressórico.',
    'MEDIUM',
    'Diretrizes de prevenção secundária do AVC - SBDCV/AHA 2021 (questão original)',
    TRUE
),
(
    1,
    'Neurologia - AVC e Demências',
    'MULTIPLE_CHOICE',
    'Homem de 64 anos com AVC isquêmico menor (NIHSS 2), não cardioembólico, sem indicação de trombólise, avaliado em 12 horas do início. Qual a antiagregação recomendada?',
    'D',
    '["A) Anticoagulação plena com heparina", "B) AAS associado a clopidogrel por tempo indeterminado", "C) AAS isolado indefinidamente desde o primeiro dia", "D) AAS associado a clopidogrel por 21 dias, seguido de monoterapia antiplaquetária"]'::jsonb,
    'No AVC menor ou AIT de alto risco, a dupla antiagregação iniciada precocemente e mantida por cerca de 21 dias reduz recorrência; prolongá-la aumenta sangramento sem benefício. Anticoagulação não é indicada em AVC não cardioembólico.',
    'HARD',
    'Diretrizes de prevenção secundária do AVC - SBDCV/AHA 2021 (questão original)',
    TRUE
),
(
    1,
    'Neurologia - Cefaleias e Epilepsia',
    'MULTIPLE_CHOICE',
    'Mulher de 30 anos com enxaqueca sem aura, 6 crises incapacitantes por mês, sem asma ou outras comorbidades. Qual opção é fármaco de primeira linha para profilaxia?',
    'C',
    '["A) Sumatriptano em uso diário", "B) Tramadol contínuo", "C) Propranolol", "D) Dipirona diária"]'::jsonb,
    'Betabloqueadores como o propranolol, além de topiramato e amitriptilina, são profiláticos de primeira linha. Uso diário de analgésicos ou triptanos favorece cefaleia por uso excessivo de medicação e opioides não são indicados.',
    'EASY',
    'Consenso da Sociedade Brasileira de Cefaleia - profilaxia da migrânea (questão original)',
    TRUE
),
(
    1,
    'Neurologia - Cefaleias e Epilepsia',
    'MULTIPLE_CHOICE',
    'Mulher de 45 anos com cefaleia súbita, de intensidade máxima em menos de 1 minuto, descrita como a pior da vida, sem déficit focal. Qual a conduta inicial?',
    'D',
    '["A) Analgesia com triptano e alta com orientações", "B) Ressonância de crânio eletiva ambulatorial", "C) Eletroencefalograma", "D) Tomografia de crânio sem contraste com urgência e, se normal, punção lombar"]'::jsonb,
    'Cefaleia em trovoada é sinal de alarme para hemorragia subaracnóidea. A tomografia sem contraste é o exame inicial; se normal e a suspeita persistir, a punção lombar busca xantocromia. Triptanos são contraindicados até excluir causa vascular.',
    'MEDIUM',
    'Sociedade Brasileira de Cefaleia - sinais de alarme (questão original)',
    TRUE
),
(
    1,
    'Neurologia - Cefaleias e Epilepsia',
    'MULTIPLE_CHOICE',
    'Homem de 30 anos teve a primeira crise tônico-clônica generalizada da vida, sem desencadeante. Exame neurológico, ressonância de crânio e eletroencefalograma são normais. Qual é a conduta mais adequada?',
    'B',
    '["A) Iniciar dois anticonvulsivantes em associação", "B) Não iniciar anticonvulsivante de rotina, orientar sobre o risco de recorrência e cuidados, e decidir em conjunto com o paciente", "C) Iniciar fenobarbital por toda a vida", "D) Indicar cirurgia de epilepsia"]'::jsonb,
    'Após uma única crise não provocada, com exames normais, o risco de recorrência é moderado e o tratamento costuma começar a partir da segunda crise ou quando há alto risco (lesão estrutural, EEG epileptiforme). A decisão é compartilhada, com orientação sobre direção veicular e segurança.',
    'MEDIUM',
    'Diretrizes da ILAE e da ABN para epilepsia (questão original)',
    TRUE
),
(
    1,
    'Neurologia - Cefaleias e Epilepsia',
    'MULTIPLE_CHOICE',
    'Mulher de 22 anos com epilepsia generalizada idiopática recém-diagnosticada deseja engravidar nos próximos anos. Qual orientação sobre a escolha do anticonvulsivante é correta?',
    'C',
    '["A) Suspender qualquer anticonvulsivante assim que planejar a gestação", "B) Usar carbamazepina, primeira escolha nas epilepsias generalizadas idiopáticas", "C) Evitar o valproato e preferir lamotrigina ou levetiracetam", "D) Preferir o valproato por ser o mais eficaz, independentemente do plano de gestação"]'::jsonb,
    'O valproato tem o maior risco de malformações e de prejuízo do neurodesenvolvimento fetal, devendo ser evitado em mulheres em idade fértil sempre que houver alternativa. Lamotrigina e levetiracetam têm melhor perfil; suspender o tratamento expõe a crises, e a carbamazepina pode agravar ausências e mioclonias.',
    'HARD',
    'Academia Brasileira de Neurologia - epilepsia na mulher (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Asma e DPOC',
    'MULTIPLE_CHOICE',
    'Adulto com asma leve tem sintomas cerca de duas vezes por mês e usa apenas salbutamol de resgate. Qual tratamento as recomendações atuais (SBPT e GINA) preferem?',
    'A',
    '["A) Budesonida-formoterol inalatório por demanda", "B) Manter salbutamol por demanda em monoterapia", "C) Montelucaste como tratamento preferencial", "D) Prednisona oral em ciclos mensais"]'::jsonb,
    'O uso isolado de broncodilatador de curta ação sem corticoide inalatório aumenta o risco de crises graves e morte e não é mais recomendado. Na asma leve prefere-se corticoide inalatório com formoterol por demanda. Corticoide oral de manutenção não é tratamento de asma leve.',
    'MEDIUM',
    'Recomendações SBPT para asma e DPOC / GINA / GOLD (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Asma e DPOC',
    'MULTIPLE_CHOICE',
    'Paciente com DPOC apresenta, há 3 dias, piora da dispneia, aumento do volume e purulência do escarro, sem sinais de insuficiência respiratória grave. Qual conduta é adequada?',
    'C',
    '["A) Apenas antibiótico, sem corticoide", "B) Corticoide sistêmico por 30 dias, sem antibiótico", "C) Broncodilatador de curta ação, corticoide sistêmico por cerca de 5 dias e antibiótico", "D) Suspender broncodilatadores e iniciar metilxantina intravenosa"]'::jsonb,
    'Exacerbação com aumento de dispneia, volume e purulência do escarro se beneficia de antibiótico. Associam-se broncodilatador de curta ação e corticoide sistêmico, como prednisona 40 mg por cerca de 5 dias; cursos longos só aumentam efeitos adversos.',
    'MEDIUM',
    'Recomendações SBPT para asma e DPOC / GINA / GOLD (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Asma e DPOC',
    'MULTIPLE_CHOICE',
    'Paciente com DPOC estável, em tratamento otimizado e sem tabagismo, tem em repouso PaO2 de 53 mmHg e SpO2 de 87% em ar ambiente, em duas medidas com intervalo de semanas. Qual é a conduta?',
    'D',
    '["A) Oxigênio apenas durante crises de dispneia", "B) Não indicar oxigênio, pois não há cor pulmonale", "C) Indicar ventilação mecânica invasiva domiciliar", "D) Indicar oxigenoterapia domiciliar prolongada por pelo menos 15 horas por dia"]'::jsonb,
    'PaO2 de 55 mmHg ou menos, ou SpO2 de 88% ou menos em repouso, com paciente estável, indica oxigenoterapia domiciliar prolongada, que reduz mortalidade quando usada ao menos 15 horas por dia. Cor pulmonale ou policitemia só são exigidos se a PaO2 estiver entre 56 e 59 mmHg.',
    'MEDIUM',
    'Recomendações SBPT para asma e DPOC / GINA / GOLD (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Derrame Pleural',
    'MULTIPLE_CHOICE',
    'Na análise do líquido pleural, qual achado classifica o derrame como exsudato pelos critérios de Light?',
    'B',
    '["A) Relação proteína pleural/sérica menor que 0,5", "B) Relação proteína pleural/sérica maior que 0,5", "C) Relação LDH pleural/sérica menor que 0,6", "D) LDH pleural menor que metade do limite superior sérico"]'::jsonb,
    'Pelos critérios de Light, é exsudato se houver ao menos um: relação de proteínas maior que 0,5, relação de LDH maior que 0,6 ou LDH pleural maior que dois terços do limite superior do soro. Os demais valores apresentados são compatíveis com transudato.',
    'EASY',
    'SBPT - derrame pleural (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Derrame Pleural',
    'MULTIPLE_CHOICE',
    'Paciente com pneumonia tem derrame pleural moderado. A toracocentese mostra líquido turvo, não purulento, com pH 7,05, glicose de 35 mg/dL e LDH elevada. Qual é a conduta?',
    'A',
    '["A) Drenagem torácica associada à antibioticoterapia", "B) Apenas antibiótico, sem abordagem pleural", "C) Repetir toracocentese diagnóstica em 7 dias", "D) Pleurodese química imediata"]'::jsonb,
    'pH abaixo de 7,2 e glicose abaixo de 60 mg/dL indicam derrame parapneumônico complicado, que exige drenagem além do antibiótico, assim como o empiema. Sem drenagem, o derrame tende a se tornar loculado. Pleurodese é usada em derrames recidivantes, sobretudo neoplásicos.',
    'MEDIUM',
    'SBPT - derrame pleural (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Derrame Pleural',
    'MULTIPLE_CHOICE',
    'Paciente com IC em uso de furosemida há vários dias tem derrame pleural com relação proteína pleural/sérica de 0,55 e os demais critérios de Light negativos. Qual exame ajuda a reclassificar como transudato?',
    'C',
    '["A) Adenosina deaminase pleural acima de 40 U/L", "B) Triglicerídeos pleurais acima de 110 mg/dL", "C) Gradiente de albumina soro-pleural maior que 1,2 g/dL", "D) Amilase pleural elevada"]'::jsonb,
    'Diuréticos concentram proteínas e LDH no líquido pleural e podem gerar falso exsudato na IC. Gradiente de albumina soro-pleural acima de 1,2 g/dL, ou de proteínas acima de 3,1 g/dL, sustenta transudato. ADA sugere tuberculose, triglicerídeos altos quilotórax, e amilase pancreatite ou ruptura esofágica.',
    'HARD',
    'SBPT - derrame pleural (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Pneumonia Adquirida na Comunidade',
    'MULTIPLE_CHOICE',
    'Qual é o agente etiológico mais frequente da pneumonia adquirida na comunidade em adultos, em todos os cenários de atendimento?',
    'B',
    '["A) Pseudomonas aeruginosa", "B) Streptococcus pneumoniae", "C) Staphylococcus aureus resistente à meticilina", "D) Klebsiella pneumoniae produtora de carbapenemase"]'::jsonb,
    'O pneumococo é o principal agente da PAC no ambulatório, na enfermaria e na UTI, e por isso a cobertura empírica sempre o inclui. Pseudomonas, MRSA e enterobactérias multirresistentes estão ligados a fatores de risco específicos ou à infecção hospitalar.',
    'EASY',
    'Diretriz Brasileira de PAC SBPT 2018 (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Pneumonia Adquirida na Comunidade',
    'MULTIPLE_CHOICE',
    'Homem de 35 anos, previamente hígido, sem uso recente de antibiótico, tem PAC com CRB-65 igual a zero e boa saturação. Qual tratamento empírico é adequado?',
    'D',
    '["A) Levofloxacino oral como primeira escolha", "B) Internação para ceftriaxona intravenosa", "C) Apenas sintomáticos, sem antibiótico", "D) Amoxicilina oral em regime ambulatorial"]'::jsonb,
    'Paciente sem comorbidades e de baixo risco é tratado em casa com amoxicilina ou macrolídeo, segundo a diretriz brasileira. Quinolonas respiratórias ficam para comorbidades ou uso recente de antibiótico, e o tratamento parenteral não se justifica no baixo risco.',
    'MEDIUM',
    'Diretriz Brasileira de PAC SBPT 2018 (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Pneumonia Adquirida na Comunidade',
    'MULTIPLE_CHOICE',
    'Paciente de 68 anos com PAC evolui com choque séptico e necessidade de vasopressor, sem fatores de risco para Pseudomonas ou MRSA. Qual esquema empírico é recomendado?',
    'D',
    '["A) Amoxicilina oral em dose alta", "B) Azitromicina oral em monoterapia", "C) Meropenem com vancomicina para todos os casos de PAC grave", "D) Betalactâmico intravenoso, como ceftriaxona, associado a macrolídeo, como azitromicina"]'::jsonb,
    'A PAC grave com indicação de UTI exige betalactâmico IV associado a macrolídeo, ou a quinolona respiratória, para cobrir pneumococo e atípicos. Cobertura para Pseudomonas e MRSA só se justifica quando há fatores de risco para esses agentes.',
    'HARD',
    'Diretriz Brasileira de PAC SBPT 2018 (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Tromboembolismo Pulmonar',
    'MULTIPLE_CHOICE',
    'Paciente com dor torácica tem baixa probabilidade clínica de TEP pelo escore de Wells, e o D-dímero é negativo. Como interpretar?',
    'B',
    '["A) O TEP está confirmado e deve ser anticoagulado", "B) O TEP pode ser razoavelmente excluído, sem necessidade de angiotomografia", "C) É obrigatório solicitar angiotomografia mesmo assim", "D) O resultado só vale se a probabilidade clínica for alta"]'::jsonb,
    'O D-dímero tem alto valor preditivo negativo: com probabilidade clínica baixa ou intermediária, um resultado negativo exclui TEP com segurança. Ele é pouco específico, então positivo não confirma, e em probabilidade alta não deve ser usado, indo-se direto à imagem.',
    'EASY',
    'SBPT / ESC - tromboembolismo pulmonar (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Tromboembolismo Pulmonar',
    'MULTIPLE_CHOICE',
    'Mulher de 55 anos com TEP confirmado por angiotomografia mantém PAS de 80 mmHg por mais de 15 minutos, sem resposta a volume e sem contraindicações a sangramento. Qual tratamento é indicado?',
    'C',
    '["A) Apenas anticoagulação oral com rivaroxabana e alta", "B) Filtro de veia cava inferior como medida isolada", "C) Trombólise sistêmica, por exemplo com alteplase, além da anticoagulação", "D) AAS em dose alta"]'::jsonb,
    'TEP com hipotensão sustentada é de alto risco, e a reperfusão com trombolítico sistêmico é indicada na ausência de contraindicação, associada à heparina. Embolectomia cirúrgica ou por cateter fica para contraindicação ou falha. Filtro de cava não trata o êmbolo já presente.',
    'MEDIUM',
    'SBPT / ESC - tromboembolismo pulmonar (questão original)',
    TRUE
),
(
    1,
    'Pneumologia - Tromboembolismo Pulmonar',
    'MULTIPLE_CHOICE',
    'Gestante de 24 semanas tem TEP confirmado, hemodinamicamente estável. Qual é o anticoagulante de escolha?',
    'A',
    '["A) Heparina de baixo peso molecular em dose terapêutica", "B) Varfarina com alvo de INR entre 2 e 3", "C) Rivaroxabana", "D) Apixabana"]'::jsonb,
    'Na gestação a heparina de baixo peso molecular é a escolha, pois não atravessa a placenta. A varfarina é teratogênica e pode causar sangramento fetal, e os anticoagulantes orais diretos são contraindicados por falta de segurança na gravidez.',
    'MEDIUM',
    'SBPT / ESC - tromboembolismo pulmonar (questão original)',
    TRUE
),
(
    1,
    'Reumatologia - Artrite Reumatoide e Gota',
    'MULTIPLE_CHOICE',
    'Mulher de 42 anos com artrite reumatoide recém-diagnosticada, sem contraindicações. Qual o medicamento modificador do curso da doença de primeira escolha?',
    'A',
    '["A) Metotrexato", "B) Alopurinol", "C) Anti-TNF como primeira medicação", "D) Prednisona em dose alta como monoterapia prolongada"]'::jsonb,
    'O metotrexato é a âncora do tratamento inicial da AR pelas recomendações da SBR. Corticoide é ponte em dose baixa e por curto período, e imunobiológicos ficam para falha de MMCD sintéticos.',
    'EASY',
    'Recomendações da SBR para tratamento da artrite reumatoide (questão original)',
    TRUE
),
(
    1,
    'Reumatologia - Artrite Reumatoide e Gota',
    'MULTIPLE_CHOICE',
    'Homem com monoartrite aguda de primeira metatarsofalângica. Qual achado confirma o diagnóstico de gota?',
    'B',
    '["A) Ácido úrico sérico acima de 7 mg/dL durante a crise", "B) Cristais em forma de agulha, com birrefringência negativa à luz polarizada, no líquido sinovial", "C) Cristais romboides com birrefringência positiva no líquido sinovial", "D) Melhora completa com colchicina"]'::jsonb,
    'O padrão-ouro é a identificação de cristais de urato monossódico. O ácido úrico sérico pode estar normal na crise, e cristais romboides com birrefringência positiva são de pirofosfato de cálcio.',
    'EASY',
    'Recomendações da SBR para diagnóstico e tratamento da gota (questão original)',
    TRUE
),
(
    1,
    'Reumatologia - Artrite Reumatoide e Gota',
    'MULTIPLE_CHOICE',
    'Na investigação de poliartrite simétrica de mãos, qual autoanticorpo tem maior especificidade para artrite reumatoide e associa-se a doença mais erosiva?',
    'C',
    '["A) Anti-Ro/SSA", "B) Fator reumatoide", "C) Anti-CCP (antipeptídeo citrulinado cíclico)", "D) Fator antinuclear"]'::jsonb,
    'O anti-CCP tem especificidade em torno de 95% e prediz doença erosiva. O fator reumatoide é menos específico, aparecendo em outras doenças e em idosos saudáveis; FAN e anti-Ro são mais ligados a lúpus e Sjögren.',
    'MEDIUM',
    'Recomendações da SBR para diagnóstico da artrite reumatoide (questão original)',
    TRUE
),
(
    1,
    'Reumatologia - Artrite Reumatoide e Gota',
    'MULTIPLE_CHOICE',
    'Homem com gota, três crises no último ano e tofos em cotovelos, inicia alopurinol. Qual o alvo de ácido úrico sérico e a medida associada no início do tratamento?',
    'B',
    '["A) Normalização do ácido úrico apenas durante as crises", "B) Ácido úrico abaixo de 6 mg/dL, ou menor que 5 com tofos, com profilaxia com colchicina em baixa dose", "C) Ácido úrico abaixo de 6 mg/dL, suspendendo o alopurinol a cada nova crise", "D) Ácido úrico abaixo de 8 mg/dL, sem necessidade de profilaxia"]'::jsonb,
    'O alvo do tratamento hipouricemiante é urato abaixo de 6 mg/dL (abaixo de 5 com tofos), com profilaxia anti-inflamatória nos primeiros meses. Suspender o alopurinol em crise causa oscilação do urato e não é recomendado.',
    'MEDIUM',
    'Recomendações da SBR para diagnóstico e tratamento da gota (questão original)',
    TRUE
),
(
    1,
    'Reumatologia - Lúpus Eritematoso Sistêmico',
    'MULTIPLE_CHOICE',
    'Mulher de 27 anos com lúpus eritematoso sistêmico, com manifestações cutâneas e articulares controladas. Qual medicação é recomendada para praticamente todos os pacientes, salvo contraindicação?',
    'C',
    '["A) Prednisona em dose alta contínua", "B) Ciclofosfamida em pulsos mensais", "C) Hidroxicloroquina, com acompanhamento oftalmológico periódico", "D) Rituximabe de manutenção"]'::jsonb,
    'A hidroxicloroquina reduz surtos, dano acumulado e trombose e aumenta a sobrevida, sendo indicada para quase todos com LES. Imunossupressores potentes e corticoide em dose alta ficam para doença grave e por tempo limitado.',
    'EASY',
    'Consenso da SBR para o tratamento do lúpus eritematoso sistêmico (questão original)',
    TRUE
),
(
    1,
    'Reumatologia - Lúpus Eritematoso Sistêmico',
    'MULTIPLE_CHOICE',
    'Em paciente com lúpus eritematoso sistêmico, qual combinação laboratorial melhor se correlaciona com atividade da doença, sobretudo nefrite?',
    'B',
    '["A) FAN com título alto isoladamente", "B) Anti-DNA dupla hélice elevado com complemento (C3 e C4) baixo", "C) Anticorpos antifosfolípides positivos", "D) Anti-Sm positivo com complemento elevado"]'::jsonb,
    'Anti-dsDNA em ascensão e consumo de complemento acompanham atividade, especialmente renal. O anti-Sm é muito específico, mas não varia com a atividade, e o título do FAN não serve para monitorar.',
    'MEDIUM',
    'Consenso da SBR para o tratamento do lúpus eritematoso sistêmico (questão original)',
    TRUE
),
(
    1,
    'Reumatologia - Lúpus Eritematoso Sistêmico',
    'MULTIPLE_CHOICE',
    'Mulher com lúpus apresenta proteinúria de 1,2 g/24 h, hematúria dismórfica e cilindros hemáticos, com creatinina normal. Qual o próximo passo mais adequado?',
    'D',
    '["A) Apenas aumentar a dose de hidroxicloroquina e reavaliar em 6 meses", "B) Aguardar elevação da creatinina para indicar investigação", "C) Iniciar hemodiálise de forma preventiva", "D) Biópsia renal para definir a classe histológica e orientar a terapia"]'::jsonb,
    'Proteinúria maior ou igual a 0,5 g/24 h com sedimento ativo indica biópsia renal, pois a classe da nefrite lúpica define a imunossupressão. Creatinina normal não exclui nefrite proliferativa grave.',
    'HARD',
    'Consenso da SBR para nefrite lúpica (questão original)',
    TRUE
);

-- -----------------------------------------------------------------------------
-- 4. MEDICINA — CIR_GERAL (54 questões)
-- -----------------------------------------------------------------------------
INSERT INTO tb_flashcard (subject_id, topic, question_type, question, answer, options_json, explanation, difficulty, source, active)
VALUES
(
    2,
    'Abdome Agudo - Apendicite Aguda',
    'MULTIPLE_CHOICE',
    'Menino de 9 anos com dor em fossa ilíaca direita há 20 horas, náuseas e febre baixa. O exame é sugestivo, mas não conclusivo, de apendicite. Qual é o exame de imagem inicial preferencial?',
    'A',
    '["A) Ultrassonografia de abdome", "B) Tomografia computadorizada de abdome com contraste", "C) Radiografia simples de abdome em ortostase", "D) Ressonância magnética com gadolínio", "E) Enema opaco"]'::jsonb,
    'Em crianças, a ultrassonografia é o exame inicial na suspeita de apendicite: não usa radiação ionizante e tem boa acurácia em mãos experientes. A tomografia fica reservada para casos inconclusivos, e a radiografia simples tem baixo rendimento diagnóstico.',
    'EASY',
    'Diretrizes WSES (Jerusalém) para apendicite aguda 2020 (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo - Apendicite Aguda',
    'MULTIPLE_CHOICE',
    'Homem de 35 anos com 7 dias de dor em fossa ilíaca direita, febre e massa palpável. Está estável. A tomografia mostra apendicite com abscesso periapendicular bem delimitado de 5 cm. Qual é a conduta inicial mais adequada?',
    'B',
    '["A) Apendicectomia por laparotomia mediana imediata", "B) Antibioticoterapia e drenagem percutânea do abscesso guiada por imagem", "C) Alta com antibiótico oral, sem drenagem", "D) Colonoscopia de urgência antes de qualquer tratamento"]'::jsonb,
    'Na apendicite complicada com abscesso bem formado, em paciente estável, o tratamento inicial não operatório com antibiótico e drenagem percutânea reduz complicações em relação à cirurgia imediata, que encontra tecidos inflamados e aderidos. Abscesso grande não se resolve só com antibiótico oral ambulatorial.',
    'MEDIUM',
    'Diretrizes WSES (Jerusalém) para apendicite aguda 2020 (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo - Apendicite Aguda',
    'MULTIPLE_CHOICE',
    'Gestante de 22 semanas com dor em flanco e fossa ilíaca direita, leucocitose e febre baixa. A ultrassonografia não visualizou o apêndice. Qual é o próximo exame de imagem recomendado?',
    'C',
    '["A) Tomografia computadorizada com contraste iodado", "B) Repetir a ultrassonografia somente após 72 horas", "C) Ressonância magnética sem gadolínio", "D) Radiografia simples de abdome com proteção pélvica"]'::jsonb,
    'Na gestante com suspeita de apendicite e ultrassonografia inconclusiva, a ressonância sem contraste é o exame indicado: tem boa acurácia e não expõe o feto à radiação. Esperar 72 horas aumenta o risco de perfuração, que eleva muito a perda fetal.',
    'HARD',
    'Diretrizes WSES 2020 e ACR Appropriateness Criteria (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Obstrutivo - Obstrução Intestinal',
    'MULTIPLE_CHOICE',
    'Mulher de 60 anos, com histerectomia prévia, apresenta distensão, vômitos e parada de eliminação de gases há 1 dia. Sinais vitais normais, abdome sem peritonite. Qual é o manejo inicial?',
    'D',
    '["A) Laparotomia exploradora imediata", "B) Laxativo oral e dieta rica em fibras", "C) Colonoscopia descompressiva de urgência", "D) Jejum, sonda nasogástrica aberta, hidratação venosa e correção de eletrólitos"]'::jsonb,
    'Obstrução de delgado por bridas sem sinais de sofrimento de alça é tratada inicialmente de forma conservadora: repouso intestinal, descompressão por sonda, reposição volêmica e de eletrólitos e reavaliação seriada. Laxativo oral é contraindicado na obstrução mecânica.',
    'EASY',
    'Diretrizes de Bolonha para obstrução por aderências (WSES 2017) (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Obstrutivo - Obstrução Intestinal',
    'MULTIPLE_CHOICE',
    'Idoso de 78 anos, constipado crônico e acamado, tem distensão abdominal volumosa e assimétrica há 2 dias. A radiografia mostra alça colônica muito dilatada em U invertido. Não há peritonite nem sinais de isquemia. Qual é a conduta inicial?',
    'A',
    '["A) Descompressão endoscópica por retossigmoidoscopia, seguida de sigmoidectomia eletiva", "B) Laparotomia com colectomia total de urgência", "C) Enema baritado como tratamento definitivo", "D) Observação apenas, pois o volvo sempre se desfaz sozinho"]'::jsonb,
    'Volvo de sigmoide sem sinais de isquemia ou perfuração é inicialmente distorcido por via endoscópica. Como a recidiva é alta, indica-se sigmoidectomia eletiva, de preferência na mesma internação. Cirurgia de urgência fica para isquemia, perfuração ou falha da descompressão.',
    'MEDIUM',
    'ASCRS Clinical Practice Guidelines for Colonic Volvulus 2021 (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Obstrutivo - Obstrução Intestinal',
    'MULTIPLE_CHOICE',
    'Paciente com obstrução de delgado por bridas, sem sinais de estrangulamento, recebe contraste hidrossolúvel pela sonda nasogástrica. A radiografia após 24 horas mostra contraste no cólon. O que esse achado indica?',
    'B',
    '["A) Necessidade de laparotomia imediata", "B) Alta probabilidade de resolução com o tratamento não operatório", "C) Obstrução completa que exige enterólise", "D) Perfuração intestinal contida"]'::jsonb,
    'Pelas diretrizes de Bolonha, a chegada do contraste hidrossolúvel ao cólon em até 24 horas prediz resolução sem cirurgia. Se o contraste não alcançar o cólon, a chance de falha do tratamento conservador é alta e a cirurgia deve ser considerada.',
    'HARD',
    'Diretrizes de Bolonha para obstrução por aderências (WSES 2017) (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Perfurativo - Úlcera Péptica Perfurada',
    'MULTIPLE_CHOICE',
    'Homem de 70 anos com dor abdominal súbita e difusa, abdome em tábua. Está muito debilitado e não consegue ficar em pé para a radiografia de tórax. Qual incidência radiográfica ajuda a detectar pneumoperitônio?',
    'C',
    '["A) Abdome em decúbito dorsal com raios verticais", "B) Tórax em decúbito ventral", "C) Abdome em decúbito lateral esquerdo com raios horizontais", "D) Abdome em decúbito lateral direito com raios verticais"]'::jsonb,
    'Com o paciente em decúbito lateral esquerdo e raios horizontais, o ar livre sobe e se acumula entre o fígado e a parede abdominal, onde é visto com facilidade. Em decúbito dorsal com raios verticais, pequenas quantidades de ar livre passam despercebidas. Na dúvida, a tomografia é o exame mais sensível.',
    'MEDIUM',
    'Diretrizes WSES para úlcera péptica perfurada 2020 (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Perfurativo - Úlcera Péptica Perfurada',
    'MULTIPLE_CHOICE',
    'Homem de 45 anos com úlcera duodenal anterior perfurada, de 6 mm, diagnosticada 8 horas após o início da dor e hemodinamicamente estável. Qual é o tratamento cirúrgico padrão?',
    'D',
    '["A) Gastrectomia subtotal com reconstrução em Y de Roux", "B) Vagotomia troncular com antrectomia de rotina", "C) Tratamento apenas clínico com IBP venoso, sem cirurgia", "D) Rafia da perfuração com epiploplastia, seguida de IBP e erradicação do H. pylori"]'::jsonb,
    'Perfuração duodenal pequena é tratada com rafia simples e epiplon (técnica de Graham), por via aberta ou laparoscópica. A cirurgia para reduzir ácido caiu em desuso porque IBP e erradicação do H. pylori controlam a doença. Ressecção gástrica fica para perfurações grandes ou suspeita de câncer.',
    'MEDIUM',
    'Diretrizes WSES para úlcera péptica perfurada 2020 (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Perfurativo - Úlcera Péptica Perfurada',
    'MULTIPLE_CHOICE',
    'Mulher de 66 anos é operada por perfuração de úlcera na pequena curvatura gástrica. Diferentemente da úlcera duodenal perfurada, qual cuidado é obrigatório durante o procedimento?',
    'A',
    '["A) Biopsiar as bordas da úlcera para afastar neoplasia gástrica", "B) Realizar vagotomia troncular associada", "C) Deixar a perfuração aberta e drenar a cavidade", "D) Fazer gastrostomia descompressiva de rotina"]'::jsonb,
    'Uma parcela das úlceras gástricas perfuradas é um adenocarcinoma. Por isso, as bordas devem ser biopsiadas (ou a lesão ressecada) para orientar o tratamento oncológico. Na úlcera duodenal, a malignidade é rara e a biópsia não é rotina.',
    'MEDIUM',
    'Diretrizes WSES para úlcera péptica perfurada 2020 (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Vascular - Isquemia Intestinal',
    'MULTIPLE_CHOICE',
    'Mulher de 74 anos com fibrilação atrial sem anticoagulação apresenta dor abdominal súbita e muito intensa, mas o abdome está flácido e pouco doloroso à palpação. Qual é a principal hipótese?',
    'B',
    '["A) Cólica renal por cálculo ureteral", "B) Isquemia mesentérica aguda por embolia da artéria mesentérica superior", "C) Gastroenterite aguda", "D) Apendicite aguda retrocecal"]'::jsonb,
    'Dor desproporcional ao exame físico em paciente com fonte embólica, como fibrilação atrial, é o quadro clássico da embolia da artéria mesentérica superior. A peritonite surge só quando já há necrose, por isso o diagnóstico precisa ser precoce.',
    'EASY',
    'Diretrizes ESVS 2017 e WSES 2022 para isquemia mesentérica aguda (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Vascular - Isquemia Intestinal',
    'MULTIPLE_CHOICE',
    'Na suspeita de isquemia mesentérica aguda em paciente com função renal limítrofe, qual é o exame de imagem de escolha para confirmar o diagnóstico?',
    'C',
    '["A) Ultrassonografia abdominal convencional", "B) Radiografia simples de abdome", "C) Angiotomografia de abdome, sem adiar o exame por causa da creatinina", "D) Dosagem isolada do D-dímero, dispensando imagem"]'::jsonb,
    'A angiotomografia com fases arterial e venosa é o exame de escolha: mostra a oclusão vascular e sinais de sofrimento da alça. Pela alta mortalidade da doença, a insuficiência renal não deve atrasar o exame. O D-dímero é sensível, mas não confirma o diagnóstico.',
    'MEDIUM',
    'Diretrizes ESVS 2017 e WSES 2022 para isquemia mesentérica aguda (questão original)',
    TRUE
),
(
    2,
    'Abdome Agudo Vascular - Isquemia Intestinal',
    'MULTIPLE_CHOICE',
    'Idosa de 80 anos, após episódio de hipotensão, tem dor em flanco esquerdo e evacuação com sangue vivo. A colonoscopia mostra mucosa edemaciada e friável na flexura esplênica, sem necrose. Não há peritonite. Qual é a conduta mais adequada?',
    'D',
    '["A) Colectomia esquerda de urgência", "B) Embolectomia da artéria mesentérica superior", "C) Anticoagulação plena e alta hospitalar", "D) Tratamento de suporte: hidratação, repouso intestinal e reavaliação seriada"]'::jsonb,
    'O quadro é de colite isquêmica não gangrenosa, em área de irrigação limítrofe. A maioria dos casos se resolve com suporte clínico, com antibiótico nos casos moderados ou graves. Cirurgia é reservada para gangrena, perfuração ou piora clínica.',
    'MEDIUM',
    'Diretrizes ACG 2015 para colite isquêmica (questão original)',
    TRUE
),
(
    2,
    'Hérnias Abdominais - Parede Abdominal',
    'MULTIPLE_CHOICE',
    'Qual hérnia da região da virilha tem maior risco de encarceramento e estrangulamento, motivo pelo qual se recomenda operá-la mesmo quando pouco sintomática?',
    'D',
    '["A) Hérnia inguinal direta", "B) Hérnia inguinal indireta pequena e redutível", "C) Diástase dos músculos retos", "D) Hérnia femoral"]'::jsonb,
    'A hérnia femoral passa por um anel estreito e rígido, sob o ligamento inguinal e medial à veia femoral, o que explica o alto risco de estrangulamento. Por isso o reparo é recomendado mesmo em pacientes oligossintomáticos. É mais comum em mulheres. Diástase dos retos não é hérnia verdadeira.',
    'EASY',
    'Diretrizes HerniaSurge para hérnia inguinal 2018 (questão original)',
    TRUE
),
(
    2,
    'Hérnias Abdominais - Parede Abdominal',
    'MULTIPLE_CHOICE',
    'Homem de 45 anos com hérnia inguinal unilateral primária e sintomática será operado por via aberta. Qual técnica é recomendada como primeira escolha pelas diretrizes internacionais?',
    'A',
    '["A) Reparo com tela sem tensão pela técnica de Lichtenstein", "B) Herniorrafia de Bassini sem tela", "C) Apenas a ligadura alta do saco herniário", "D) Herniorrafia de McVay como rotina"]'::jsonb,
    'As diretrizes HerniaSurge recomendam reparo com tela, aberto (Lichtenstein) ou laparoscópico, porque reduz a recidiva em relação às técnicas com tensão como Bassini e McVay. A ligadura isolada do saco é o tratamento da hérnia indireta da criança, não do adulto.',
    'MEDIUM',
    'Diretrizes HerniaSurge para hérnia inguinal 2018 (questão original)',
    TRUE
),
(
    2,
    'Hérnias Abdominais - Parede Abdominal',
    'MULTIPLE_CHOICE',
    'Paciente operada por hérnia femoral encarcerada tem apenas parte da parede antimesentérica da alça presa no anel, com isquemia local, sem quadro obstrutivo prévio. Como se chama esse tipo de hérnia?',
    'B',
    '["A) Hérnia de Littré", "B) Hérnia de Richter", "C) Hérnia de Amyand", "D) Hérnia de Spiegel"]'::jsonb,
    'Na hérnia de Richter, só parte da circunferência da alça fica presa. Pode estrangular e perfurar sem causar obstrução, o que atrasa o diagnóstico. Littré contém o divertículo de Meckel, Amyand contém o apêndice e Spiegel ocorre na linha semilunar.',
    'HARD',
    'Sabiston Textbook of Surgery, 21ª edição (questão original)',
    TRUE
),
(
    2,
    'Perioperatório - Profilaxia de TEV',
    'MULTIPLE_CHOICE',
    'Paciente com alto risco de tromboembolismo venoso será submetido a cirurgia de grande porte, mas tem alto risco de sangramento. Qual é a profilaxia mais adequada no pós-operatório imediato?',
    'A',
    '["A) Compressão pneumática intermitente dos membros inferiores", "B) Enoxaparina em dose plena terapêutica", "C) Varfarina iniciada no dia da cirurgia", "D) Nenhuma profilaxia até a alta hospitalar"]'::jsonb,
    'Quando o risco de sangramento contraindica a anticoagulação, a profilaxia mecânica, de preferência por compressão pneumática intermitente, é a opção. A profilaxia farmacológica deve ser iniciada assim que o risco de sangramento diminuir.',
    'MEDIUM',
    'Diretrizes ACCP (CHEST) para prevenção de TEV em cirurgia (questão original)',
    TRUE
),
(
    2,
    'Perioperatório - Profilaxia de TEV',
    'MULTIPLE_CHOICE',
    'Mulher de 62 anos, com função renal normal, fará colectomia por câncer de cólon. Qual é a profilaxia farmacológica de TEV usual no pós-operatório?',
    'B',
    '["A) Enoxaparina 1 mg/kg por via subcutânea de 12 em 12 horas", "B) Enoxaparina 40 mg por via subcutânea uma vez ao dia", "C) Ácido acetilsalicílico 100 mg como agente isolado", "D) Heparina não fracionada em bomba contínua com TTPa alvo"]'::jsonb,
    'Cirurgia abdominal oncológica de grande porte tem alto risco de TEV. A profilaxia usual é enoxaparina 40 mg SC uma vez ao dia (30 mg se a depuração de creatinina for menor que 30 mL/min), associada a métodos mecânicos. A dose de 1 mg/kg a cada 12 horas é terapêutica, não profilática.',
    'MEDIUM',
    'Diretrizes ACCP (CHEST) para prevenção de TEV em cirurgia (questão original)',
    TRUE
),
(
    2,
    'Perioperatório - Profilaxia de TEV',
    'MULTIPLE_CHOICE',
    'Após cirurgia oncológica abdominal ou pélvica de grande porte, por quanto tempo se recomenda manter a profilaxia farmacológica de TEV com heparina de baixo peso molecular?',
    'C',
    '["A) Somente durante as primeiras 24 horas", "B) Até o paciente começar a deambular, mesmo que seja no 2º dia", "C) Cerca de 4 semanas após a cirurgia", "D) Por 6 meses, em dose terapêutica"]'::jsonb,
    'Em cirurgia oncológica abdominal ou pélvica de grande porte, o risco de TEV continua após a alta. As diretrizes recomendam profilaxia estendida por cerca de 4 semanas com heparina de baixo peso molecular, o que reduz a trombose venosa profunda sem aumento importante de sangramento.',
    'HARD',
    'Diretrizes ASCO 2023 e ACCP para profilaxia de TEV no câncer (questão original)',
    TRUE
),
(
    2,
    'Perioperatório - Risco Cirúrgico e Antibioticoprofilaxia',
    'MULTIPLE_CHOICE',
    'Paciente de 55 anos com hipertensão e diabetes tipo 2 bem controlados, sem limitação funcional, será submetido a colecistectomia eletiva. Qual é sua classificação ASA?',
    'A',
    '["A) ASA II", "B) ASA I", "C) ASA III", "D) ASA IV"]'::jsonb,
    'ASA II é o paciente com doença sistêmica leve e sem limitação funcional, como hipertensão ou diabetes bem controlados. ASA I é o indivíduo saudável, e ASA III tem doença sistêmica grave com limitação funcional.',
    'EASY',
    'Classificação ASA, American Society of Anesthesiologists (questão original)',
    TRUE
),
(
    2,
    'Perioperatório - Risco Cirúrgico e Antibioticoprofilaxia',
    'MULTIPLE_CHOICE',
    'Na antibioticoprofilaxia de uma cirurgia limpa-contaminada com cefazolina, quando a dose deve ser administrada?',
    'C',
    '["A) Na véspera da cirurgia, à noite", "B) Ao final da cirurgia, no fechamento da pele", "C) Até 60 minutos antes da incisão da pele", "D) Somente se surgir febre no pós-operatório"]'::jsonb,
    'A dose deve ser dada nos 60 minutos que antecedem a incisão, para que haja concentração adequada nos tecidos durante a cirurgia. Para vancomicina e fluoroquinolonas, a infusão começa até 120 minutos antes. Dose dada após o fechamento não previne infecção do sítio cirúrgico.',
    'EASY',
    'Diretrizes ASHP/IDSA/SIS/SHEA 2013 e ANVISA (questão original)',
    TRUE
),
(
    2,
    'Perioperatório - Risco Cirúrgico e Antibioticoprofilaxia',
    'MULTIPLE_CHOICE',
    'Mulher de 68 anos, hipertensa, sem sintomas cardíacos, será submetida a cirurgia abdominal eletiva de risco intermediário. Ela sobe dois lances de escada sem cansaço. Qual é a conduta cardiológica pré-operatória?',
    'B',
    '["A) Cintilografia miocárdica obrigatória antes da cirurgia", "B) Prosseguir com a cirurgia, sem testes de estresse adicionais", "C) Cateterismo cardíaco antes da cirurgia", "D) Adiar a cirurgia para fazer teste ergométrico de rotina"]'::jsonb,
    'Paciente assintomático com capacidade funcional de 4 METs ou mais, como subir dois lances de escada, pode seguir para a cirurgia sem testes de estresse, porque eles não mudam a conduta. Os testes ficam para baixa capacidade funcional quando o resultado alteraria o manejo.',
    'MEDIUM',
    'Diretriz SBC de Avaliação Cardiovascular Perioperatória 2017 e ACC/AHA (questão original)',
    TRUE
),
(
    2,
    'Perioperatório - Risco Cirúrgico e Antibioticoprofilaxia',
    'MULTIPLE_CHOICE',
    'Paciente recebeu cefazolina antes da incisão para uma gastrectomia que já dura 5 horas, com perda sanguínea estimada de 800 mL. Qual é a conduta correta na antibioticoprofilaxia?',
    'D',
    '["A) Não repetir a dose e manter o antibiótico por 7 dias", "B) Trocar por carbapenêmico de amplo espectro", "C) Suspender a profilaxia, pois a primeira dose já protegeu toda a cirurgia", "D) Repetir a dose de cefazolina durante a cirurgia e não prolongar além de 24 horas"]'::jsonb,
    'A cefazolina deve ser repetida a cada 4 horas de cirurgia ou se a perda de sangue passar de 1.500 mL. Aqui a dose se repete pela duração. A profilaxia não deve ir além de 24 horas, pois isso não reduz infecção e aumenta resistência e risco de C. difficile.',
    'HARD',
    'Diretrizes ASHP/IDSA/SIS/SHEA 2013 e ANVISA (questão original)',
    TRUE
),
(
    2,
    'Proctologia - Doenças Orificiais',
    'MULTIPLE_CHOICE',
    'Paciente relata que os mamilos hemorroidários prolapsam durante a evacuação e voltam sozinhos para dentro do canal anal. Qual é o grau da doença hemorroidária interna?',
    'D',
    '["A) Grau I", "B) Grau III", "C) Grau IV", "D) Grau II"]'::jsonb,
    'Na classificação de Goligher, o grau I sangra sem prolapso, o grau II prolapsa e reduz espontaneamente, o grau III precisa de redução manual e o grau IV é irredutível. O grau II costuma ser tratado com medidas clínicas e procedimentos ambulatoriais, como a ligadura elástica.',
    'EASY',
    'Diretrizes ASCRS para doença hemorroidária 2018 (questão original)',
    TRUE
),
(
    2,
    'Proctologia - Doenças Orificiais',
    'MULTIPLE_CHOICE',
    'Homem de 35 anos, sem incontinência, tem fissura anal posterior crônica com plicoma sentinela. Fez 8 semanas de fibras, banhos de assento e bloqueador de canal de cálcio tópico, sem melhora. Qual é o tratamento indicado?',
    'A',
    '["A) Esfincterotomia lateral interna parcial", "B) Fistulotomia", "C) Hemorroidectomia de Milligan-Morgan", "D) Dilatação anal forçada"]'::jsonb,
    'Na fissura crônica sem resposta ao tratamento clínico, a esfincterotomia lateral interna parcial é o padrão, com altas taxas de cicatrização e baixo risco de incontinência em pacientes selecionados. A dilatação anal forçada foi abandonada por causar lesão esfincteriana imprevisível.',
    'MEDIUM',
    'Diretrizes ASCRS para fissura anal 2023 (questão original)',
    TRUE
),
(
    2,
    'Proctologia - Doenças Orificiais',
    'MULTIPLE_CHOICE',
    'Homem de 40 anos tem dor perianal intensa e contínua há 3 dias, febre e área endurecida, quente e dolorosa ao lado do ânus, ainda sem flutuação. Qual é a conduta?',
    'B',
    '["A) Antibiótico oral isolado e retorno em 2 semanas", "B) Drenagem cirúrgica do abscesso, sem esperar flutuação", "C) Fistulotomia imediata com busca ativa do orifício interno", "D) Compressas mornas e esperar a drenagem espontânea"]'::jsonb,
    'O abscesso anorretal é tratado com drenagem cirúrgica assim que diagnosticado, mesmo sem flutuação, porque a pele espessa e a gordura perianal retardam esse sinal. Antibiótico sozinho não resolve. Antibiótico associado é reservado a celulite extensa, imunossupressão ou sepse.',
    'MEDIUM',
    'Diretrizes ASCRS para abscesso anorretal e fístula 2022 (questão original)',
    TRUE
),
(
    2,
    'Proctologia - Doenças Orificiais',
    'MULTIPLE_CHOICE',
    'Paciente com fístula anal tem orifício externo localizado posteriormente a uma linha transversal imaginária que passa pelo centro do ânus. Pela regra de Goodsall, como é provável que seja o trajeto?',
    'C',
    '["A) Retilíneo e radial até a cripta mais próxima", "B) Sempre interesfincteriano e curto, em direção à linha média anterior", "C) Curvo, terminando em cripta na linha média posterior", "D) Sem orifício interno, pois é uma fístula cega"]'::jsonb,
    'Pela regra de Goodsall, orifícios externos posteriores à linha transversal costumam ter trajeto curvo até a cripta da linha média posterior. Orifícios anteriores tendem a seguir em linha reta e radial. A regra orienta a busca do orifício interno, mas tem exceções, sobretudo em orifícios anteriores distantes do ânus.',
    'HARD',
    'Diretrizes ASCRS para abscesso anorretal e fístula 2022 (questão original)',
    TRUE
),
(
    2,
    'Pâncreas - Pancreatite Aguda',
    'MULTIPLE_CHOICE',
    'Pelos critérios de Atlanta revisados, quando se confirma o diagnóstico de pancreatite aguda?',
    'B',
    '["A) Com qualquer elevação de amilase, mesmo sem dor abdominal", "B) Com 2 de 3 critérios: dor típica, lipase ou amilase 3 vezes acima do normal e imagem compatível", "C) Somente com tomografia mostrando necrose pancreática", "D) Com a dosagem de PCR acima de 150 mg/L"]'::jsonb,
    'O diagnóstico exige 2 de 3 critérios: dor abdominal típica, lipase ou amilase pelo menos 3 vezes acima do limite superior e achados de imagem. Assim, a tomografia não é obrigatória quando a clínica e a enzima já fecham o diagnóstico. A PCR serve para gravidade, não para diagnóstico.',
    'EASY',
    'Classificação de Atlanta revisada 2012 (questão original)',
    TRUE
),
(
    2,
    'Pâncreas - Pancreatite Aguda',
    'MULTIPLE_CHOICE',
    'Mulher de 40 anos teve pancreatite aguda biliar leve e já se alimenta sem dor no 3º dia. A ultrassonografia mostra colelitíase. Quando deve ser feita a colecistectomia?',
    'C',
    '["A) Somente após 6 meses, para o pâncreas se recuperar", "B) Apenas se houver novo episódio de pancreatite", "C) Na mesma internação, antes da alta", "D) Não há indicação de colecistectomia"]'::jsonb,
    'Na pancreatite biliar leve, a colecistectomia na mesma internação reduz muito a recorrência de eventos biliares e de nova pancreatite em comparação com a cirurgia tardia. Em formas graves com coleções, ela é adiada até a resolução do processo inflamatório.',
    'MEDIUM',
    'Diretrizes ACG 2024 e IAP/APA para pancreatite aguda (questão original)',
    TRUE
),
(
    2,
    'Pâncreas - Pancreatite Aguda',
    'MULTIPLE_CHOICE',
    'Homem com pancreatite aguda necrosante evolui na 4ª semana com febre e piora clínica. A tomografia mostra necrose encapsulada com bolhas de gás. Qual é a conduta mais adequada?',
    'D',
    '["A) Necrosectomia aberta imediata por laparotomia", "B) Manter sem antibiótico, pois a necrose infectada não se trata", "C) Antibiótico profilático deveria ter sido iniciado no 1º dia em toda pancreatite", "D) Antibiótico com boa penetração pancreática e abordagem escalonada, começando por drenagem minimamente invasiva"]'::jsonb,
    'Gás na necrose sugere infecção. O tratamento é antibiótico (como carbapenêmico) e abordagem escalonada: drenagem percutânea ou endoscópica e, se preciso, necrosectomia minimamente invasiva, de preferência após o encapsulamento. Antibiótico profilático não é recomendado na pancreatite.',
    'HARD',
    'Diretrizes IAP/APA 2013 e ACG 2024 para pancreatite aguda (questão original)',
    TRUE
),
(
    2,
    'Pós-operatório - Febre e Cicatrização de Feridas',
    'MULTIPLE_CHOICE',
    'Na fase de remodelação da cicatrização, qual tipo de colágeno passa a predominar na cicatriz madura, substituindo o depositado na fase proliferativa?',
    'B',
    '["A) Colágeno tipo II", "B) Colágeno tipo I", "C) Colágeno tipo III", "D) Colágeno tipo IV"]'::jsonb,
    'Na fase proliferativa, os fibroblastos depositam principalmente colágeno tipo III. Na remodelação, ele é substituído pelo tipo I, mais organizado e resistente. Mesmo assim, a cicatriz alcança no máximo cerca de 80% da força tênsil da pele íntegra.',
    'EASY',
    'Sabiston Textbook of Surgery, 21ª edição (questão original)',
    TRUE
),
(
    2,
    'Pós-operatório - Febre e Cicatrização de Feridas',
    'MULTIPLE_CHOICE',
    'No 6º dia após colectomia com anastomose primária, o paciente tem febre, taquicardia, dor abdominal e íleo prolongado. Qual é a hipótese principal e o exame indicado?',
    'D',
    '["A) Atelectasia; fisioterapia respiratória apenas", "B) Reação ao anestésico; observação sem exames", "C) Flebite no acesso venoso; troca do cateter apenas", "D) Fístula de anastomose ou abscesso intra-abdominal; tomografia de abdome com contraste"]'::jsonb,
    'Febre entre o 5º e o 7º dia de pós-operatório de cirurgia colorretal, com dor e sinais sistêmicos, deve levantar suspeita de fístula de anastomose ou abscesso. A tomografia com contraste orienta drenagem percutânea ou reoperação. Atelectasia não deve ser assumida como causa de febre.',
    'MEDIUM',
    'Sabiston Textbook of Surgery, 21ª edição (questão original)',
    TRUE
),
(
    2,
    'Pós-operatório - Febre e Cicatrização de Feridas',
    'MULTIPLE_CHOICE',
    'Após apendicectomia por apendicite perfurada, o cirurgião deixa a pele aberta e a sutura no 4º dia, quando a ferida está limpa e com tecido de granulação. Como se chama esse tipo de fechamento?',
    'C',
    '["A) Primeira intenção", "B) Segunda intenção", "C) Terceira intenção, ou fechamento primário retardado", "D) Cicatrização por epitelização espontânea"]'::jsonb,
    'Na terceira intenção (primário retardado), a ferida contaminada fica aberta por alguns dias e é suturada depois, o que reduz a infecção. Na primeira intenção, a ferida é fechada no ato cirúrgico. Na segunda intenção, ela fecha sozinha por granulação e contração.',
    'MEDIUM',
    'Sabiston Textbook of Surgery, 21ª edição (questão original)',
    TRUE
),
(
    2,
    'Pós-operatório - Febre e Cicatrização de Feridas',
    'MULTIPLE_CHOICE',
    'Doze horas após laparotomia, o paciente tem febre alta, dor na ferida desproporcional ao esperado, pele escurecida com bolhas e crepitação. Qual é a conduta?',
    'A',
    '["A) Desbridamento cirúrgico amplo imediato associado a antibiótico de amplo espectro", "B) Antitérmico e reavaliação no dia seguinte", "C) Abertura parcial da pele e curativo simples, sem antibiótico", "D) Investigar atelectasia com radiografia de tórax antes de qualquer conduta"]'::jsonb,
    'Febre muito precoce com dor desproporcional, bolhas e crepitação sugere infecção necrotizante da ferida (estreptococo do grupo A ou clostrídio). É uma emergência: desbridamento cirúrgico amplo e imediato, antibiótico de amplo espectro e suporte. Cada hora de atraso aumenta a mortalidade.',
    'HARD',
    'Diretrizes IDSA 2014 para infecções de pele e partes moles (questão original)',
    TRUE
),
(
    2,
    'Queimaduras - Avaliação e Manejo Inicial',
    'MULTIPLE_CHOICE',
    'Criança escaldada com água quente tem lesão dolorosa, rosada, úmida e com bolhas, que fica pálida à pressão e volta a corar. Qual é a profundidade mais provável?',
    'D',
    '["A) Primeiro grau", "B) Segundo grau profundo", "C) Terceiro grau", "D) Segundo grau superficial"]'::jsonb,
    'Bolhas, dor intensa, leito úmido e rosado com reenchimento capilar preservado indicam segundo grau superficial, que costuma cicatrizar em até 2 a 3 semanas sem enxerto. O primeiro grau não tem bolhas. O terceiro grau é seco, endurecido e indolor.',
    'EASY',
    'Cartilha para tratamento de emergência das queimaduras, Ministério da Saúde (questão original)',
    TRUE
),
(
    2,
    'Queimaduras - Avaliação e Manejo Inicial',
    'MULTIPLE_CHOICE',
    'Adulto tem queimaduras de segundo grau em toda a cabeça e pescoço e nos dois membros superiores completos. Também tem eritema sem bolhas em todo o dorso. Pela regra dos nove, qual é a superfície corporal queimada para fins de reposição volêmica?',
    'A',
    '["A) 27%", "B) 45%", "C) 18%", "D) 36%"]'::jsonb,
    'Cabeça e pescoço valem 9% e cada membro superior 9%, somando 27%. Queimaduras de primeiro grau, como o eritema do dorso, não entram no cálculo da superfície queimada para reposição volêmica. Contar o dorso eleva o total para 45% e leva a excesso de volume.',
    'MEDIUM',
    'ATLS 10ª Edição e Ministério da Saúde (questão original)',
    TRUE
),
(
    2,
    'Queimaduras - Avaliação e Manejo Inicial',
    'MULTIPLE_CHOICE',
    'Vítima retirada de um quarto em chamas está confusa, com cefaleia e SpO2 de 98% no oxímetro de pulso. Qual é a interpretação correta e a conduta inicial?',
    'B',
    '["A) A SpO2 normal exclui intoxicação por monóxido de carbono", "B) O oxímetro pode superestimar a saturação por carboxi-hemoglobina; dar O2 a 100% e dosar COHb na gasometria", "C) A confusão se explica só pela dor; analgesia e observação", "D) Iniciar hiperventilação para eliminar o monóxido de carbono"]'::jsonb,
    'O oxímetro comum não diferencia carboxi-hemoglobina de oxi-hemoglobina e mostra saturação falsamente normal. Em incêndio em local fechado com sintomas neurológicos, deve-se dar O2 a 100% por máscara não reinalante, dosar a COHb e avaliar lesão inalatória e necessidade de via aérea definitiva.',
    'HARD',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - ATLS 10ª Edição',
    'MULTIPLE_CHOICE',
    'Na sala de trauma, o médico pergunta o nome a um motociclista e ele responde com voz clara e normal. O que essa resposta indica naquele momento?',
    'A',
    '["A) Via aérea pérvia, ventilação presente e perfusão cerebral adequada", "B) Ausência de lesão de coluna cervical", "C) Que a avaliação primária pode ser dispensada", "D) Ausência de hemorragia interna"]'::jsonb,
    'Pelo ATLS, uma resposta verbal adequada mostra que a via aérea está pérvia, que há ar para falar e que o cérebro está sendo perfundido. Não exclui lesão cervical nem hemorragia, e a avaliação primária ABCDE continua obrigatória, com reavaliações frequentes.',
    'EASY',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - ATLS 10ª Edição',
    'MULTIPLE_CHOICE',
    'Em qual das vítimas de trauma abaixo há indicação formal de via aérea definitiva pelo ATLS?',
    'B',
    '["A) Glasgow 14 com hálito etílico", "B) Escala de coma de Glasgow igual a 8 após TCE", "C) Fratura de clavícula e SpO2 de 97% em ar ambiente", "D) Ferimento corto-contuso no couro cabeludo com sangramento controlado"]'::jsonb,
    'Glasgow igual ou menor que 8 indica via aérea definitiva, pois o paciente não protege a via aérea. Outras indicações incluem apneia, risco de obstrução (queimadura inalatória, hematoma cervical em expansão), hipóxia refratária e incapacidade de manter a oxigenação com máscara.',
    'MEDIUM',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - ATLS 10ª Edição',
    'MULTIPLE_CHOICE',
    'Criança de 8 anos com trauma facial grave não consegue ser ventilada com bolsa-válvula-máscara e a intubação orotraqueal falhou. Qual é a via aérea de resgate recomendada pelo ATLS nessa idade?',
    'C',
    '["A) Cricotireoidostomia cirúrgica aberta", "B) Traqueostomia eletiva no centro cirúrgico", "C) Cricotireoidostomia por punção com agulha e ventilação a jato", "D) Intubação nasotraqueal às cegas"]'::jsonb,
    'Em crianças, o ATLS recomenda a cricotireoidostomia por punção, porque a cartilagem cricoide é o único suporte circunferencial da traqueia e a técnica cirúrgica pode causar lesão grave e estenose. A nasotraqueal às cegas é contraindicada no trauma facial grave e na apneia.',
    'HARD',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - Choque Hemorrágico',
    'MULTIPLE_CHOICE',
    'Adulto vítima de trauma chega taquicárdico e com sinais de choque hemorrágico. Qual é a reposição volêmica inicial recomendada pelo ATLS enquanto se providencia sangue?',
    'D',
    '["A) 5 litros de soro fisiológico em infusão rápida", "B) Solução de albumina 20% como primeira escolha", "C) Soro glicosado 5% em acesso central", "D) Bolus de 1 litro de cristaloide isotônico aquecido"]'::jsonb,
    'O ATLS recomenda bolus inicial de 1 litro de cristaloide isotônico aquecido no adulto (20 mL/kg na criança) e avaliar a resposta. Volumes grandes de cristaloide pioram coagulopatia, hipotermia e acidose; quem não responde precisa de hemoderivados e controle do sangramento.',
    'EASY',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - Choque Hemorrágico',
    'MULTIPLE_CHOICE',
    'Sobre o uso de ácido tranexâmico no trauma com hemorragia significativa, qual afirmativa está correta?',
    'A',
    '["A) Deve ser iniciado nas primeiras 3 horas após o trauma", "B) É indicado apenas após 6 horas, quando a fibrinólise já está instalada", "C) Substitui o controle cirúrgico do sangramento", "D) Só é útil em pacientes com hemofilia"]'::jsonb,
    'O ácido tranexâmico reduz a mortalidade por sangramento quando dado nas primeiras 3 horas (1 g em 10 minutos e 1 g em 8 horas). Depois de 3 horas, não há benefício e pode haver dano. Ele complementa o controle do sangramento, não o substitui.',
    'MEDIUM',
    'ATLS 10ª Edição e estudo CRASH-2 (questão original)',
    TRUE
),
(
    2,
    'Trauma - Choque Hemorrágico',
    'MULTIPLE_CHOICE',
    'A hipotensão permissiva é uma estratégia aceita no choque hemorrágico antes do controle do sangramento. Em qual situação ela está contraindicada?',
    'B',
    '["A) Ferimento penetrante de tronco em adulto jovem", "B) Trauma cranioencefálico grave associado", "C) Fratura de pelve com sangramento ativo", "D) Lesão hepática aguardando laparotomia"]'::jsonb,
    'No TCE, a hipotensão reduz a perfusão cerebral e aumenta a lesão secundária, com piora clara da mortalidade. Por isso a hipotensão permissiva não é usada e a pressão sistólica deve ser mantida nos alvos do TCE. Nas demais situações, ela é aceitável até o controle do sangramento.',
    'HARD',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Abdominal',
    'MULTIPLE_CHOICE',
    'Vítima de colisão de carro chega hipotensa, sem resposta à reposição inicial, com FAST positivo para líquido no espaço hepatorrenal. Tórax e pelve sem fontes de sangramento. Qual é a conduta?',
    'B',
    '["A) Tomografia de abdome com contraste antes de decidir", "B) Laparotomia exploradora de urgência", "C) Lavado peritoneal diagnóstico para confirmar o FAST", "D) Observação em UTI com hemogramas seriados"]'::jsonb,
    'Paciente instável com FAST positivo tem hemorragia intra-abdominal e precisa de controle cirúrgico imediato. Levar um paciente instável à tomografia é perigoso, e o lavado peritoneal não acrescenta nada quando o FAST já é positivo.',
    'EASY',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Abdominal',
    'MULTIPLE_CHOICE',
    'Motorista de 30 anos com marca do cinto de segurança no abdome está estável, consciente, com dor abdominal leve e FAST negativo. Qual é o exame mais indicado?',
    'C',
    '["A) Alta, pois o FAST negativo exclui lesão", "B) Laparotomia exploradora imediata", "C) Tomografia de abdome e pelve com contraste venoso", "D) Radiografia simples de abdome"]'::jsonb,
    'Em paciente estável com trauma fechado e dor abdominal, a tomografia com contraste é o exame de escolha. O FAST negativo não exclui lesões de víscera oca, pâncreas, retroperitônio ou de órgão sólido sem hemoperitônio. O sinal do cinto aumenta a suspeita de lesão de alça e de mesentério.',
    'MEDIUM',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Abdominal',
    'MULTIPLE_CHOICE',
    'Paciente estável após queda tem lesão esplênica grau III na tomografia, com extravasamento ativo de contraste (blush), sem peritonite. Em centro com radiologia intervencionista, qual é a conduta preferível?',
    'D',
    '["A) Esplenectomia imediata por laparotomia", "B) Alta com retorno ambulatorial", "C) Repetir a tomografia em 7 dias, sem intervenção", "D) Angiografia com embolização, mantendo o tratamento não operatório"]'::jsonb,
    'No paciente estável com lesão esplênica, o tratamento não operatório é preferido. A presença de blush aumenta o risco de falha, e a angioembolização reduz esse risco e preserva o baço. A esplenectomia fica para instabilidade ou falha do tratamento conservador.',
    'MEDIUM',
    'ATLS 10ª Edição e Diretrizes WSES para trauma esplênico 2017 (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Cranioencefálico',
    'MULTIPLE_CHOICE',
    'Após queda de moto, o paciente abre os olhos somente à pressão, fala palavras inapropriadas e localiza o estímulo doloroso. Qual é o escore na escala de coma de Glasgow?',
    'A',
    '["A) 10", "B) 8", "C) 12", "D) 13"]'::jsonb,
    'Abertura ocular à pressão vale 2, palavras inapropriadas valem 3 e localizar o estímulo vale 5, somando 10. Isso classifica o TCE como moderado (9 a 12).',
    'EASY',
    'ATLS 10ª Edição e escala de coma de Glasgow (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Cranioencefálico',
    'MULTIPLE_CHOICE',
    'Jovem leva pancada na região temporal, perde a consciência por instantes, recupera-se e conversa normalmente. Duas horas depois, piora do nível de consciência e anisocoria. A tomografia mostra coleção hiperdensa biconvexa. Qual é o diagnóstico?',
    'B',
    '["A) Hematoma subdural agudo por ruptura de veias ponte", "B) Hematoma extradural, em geral por lesão da artéria meníngea média", "C) Hemorragia subaracnóidea aneurismática", "D) Lesão axonal difusa"]'::jsonb,
    'Intervalo lúcido seguido de piora rápida e imagem em lente biconvexa caracterizam o hematoma extradural, frequentemente associado a fratura temporal e lesão da artéria meníngea média. O subdural tem forma de crescente e decorre de veias ponte. A drenagem cirúrgica precoce tem bom prognóstico.',
    'MEDIUM',
    'ATLS 10ª Edição (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Cranioencefálico',
    'MULTIPLE_CHOICE',
    'Paciente intubado por TCE grave, sem sinais de herniação cerebral. Qual medida de ventilação é recomendada para prevenir lesão cerebral secundária?',
    'C',
    '["A) Hiperventilação profilática com PaCO2 de 25 mmHg", "B) Hipoventilação com PaCO2 acima de 55 mmHg", "C) Manter normoventilação, com PaCO2 entre 35 e 45 mmHg", "D) Manter SpO2 entre 85% e 88%"]'::jsonb,
    'No TCE grave, deve-se evitar hipóxia e hipotensão e manter a normocapnia. A hiperventilação profilática causa vasoconstrição cerebral e isquemia. Ela só é admitida por pouco tempo como ponte em herniação iminente, até o tratamento definitivo.',
    'HARD',
    'ATLS 10ª Edição e Brain Trauma Foundation 4ª edição (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Torácico',
    'MULTIPLE_CHOICE',
    'Jovem com facada no precórdio chega com hipotensão, estase jugular e bulhas cardíacas abafadas. Qual é o diagnóstico mais provável?',
    'C',
    '["A) Pneumotórax simples", "B) Contusão pulmonar", "C) Tamponamento cardíaco", "D) Fratura de esterno isolada"]'::jsonb,
    'Hipotensão, turgência jugular e bulhas abafadas formam a tríade de Beck, típica do tamponamento cardíaco. O eFAST confirma o derrame pericárdico rapidamente, e o tratamento definitivo é cirúrgico. O pneumotórax hipertensivo também causa estase jugular, mas com murmúrio abolido e timpanismo.',
    'EASY',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Torácico',
    'MULTIPLE_CHOICE',
    'Vítima de ferimento por arma branca no hemitórax direito apresenta ferida aberta que borbulha e aspira ar a cada inspiração. Qual é a conduta imediata?',
    'D',
    '["A) Fechar a ferida com sutura completa na sala de trauma", "B) Introduzir o dreno torácico pela própria ferida", "C) Curativo oclusivo fixado nos quatro lados e observação", "D) Curativo oclusivo fixado em três lados, seguido de drenagem torácica longe da ferida"]'::jsonb,
    'No pneumotórax aberto, o curativo fixado em três lados funciona como válvula: deixa o ar sair na expiração e impede a entrada na inspiração. A seguir, drena-se o tórax por outra incisão. Ocluir os quatro lados sem dreno pode gerar pneumotórax hipertensivo.',
    'MEDIUM',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Trauma - Trauma Torácico',
    'MULTIPLE_CHOICE',
    'Idoso após colisão tem segmento da parede torácica com movimento paradoxal e SpO2 de 88%. A tomografia mostra fraturas de costelas em vários pontos e contusão pulmonar extensa. Qual é a principal causa da hipóxia e o eixo do tratamento?',
    'A',
    '["A) Contusão pulmonar subjacente; analgesia eficaz, oxigênio e ventilação, com cautela na infusão de cristaloide", "B) Movimento paradoxal; fixação externa imediata com sacos de areia", "C) Pneumotórax oculto; drenagem bilateral profilática", "D) Dor isolada; observação sem oxigênio"]'::jsonb,
    'No tórax instável, a hipóxia decorre principalmente da contusão pulmonar e da dor que limita a ventilação. O tratamento inclui oxigênio, analgesia potente (inclusive bloqueios regionais), ventilação quando necessária e evitar excesso de cristaloide, que piora a contusão. Imobilizar a parede não é recomendado.',
    'HARD',
    'ATLS 10ª Edição - American College of Surgeons (questão original)',
    TRUE
),
(
    2,
    'Vias Biliares - Colelitíase e Coledocolitíase',
    'MULTIPLE_CHOICE',
    'Homem de 50 anos, sem comorbidades, descobre cálculos na vesícula em ultrassonografia de rotina. Nunca teve dor ou outro sintoma. Qual é a conduta habitual?',
    'C',
    '["A) Colecistectomia videolaparoscópica de urgência", "B) Ácido ursodesoxicólico por toda a vida", "C) Conduta expectante, com orientação sobre os sintomas de cólica biliar", "D) Colangiopancreatografia endoscópica retrógrada"]'::jsonb,
    'Na colelitíase assintomática, o risco anual de desenvolver sintomas ou complicações é baixo, e a cirurgia de rotina não é indicada. O paciente deve ser orientado a procurar atendimento se tiver cólica biliar. Existem exceções, como cálculos muito grandes, pólipos de 1 cm ou mais e anemias hemolíticas.',
    'EASY',
    'Diretrizes EASL para litíase biliar 2016 (questão original)',
    TRUE
),
(
    2,
    'Vias Biliares - Colelitíase e Coledocolitíase',
    'MULTIPLE_CHOICE',
    'Mulher de 58 anos com febre de 39 °C e calafrios, icterícia e dor em hipocôndrio direito. A ultrassonografia mostra colédoco de 12 mm com cálculo no interior. Pressão e consciência normais. Qual é a conduta?',
    'D',
    '["A) Colecistectomia isolada de urgência, sem abordar o colédoco", "B) Antibiótico oral e alta hospitalar", "C) Somente ácido ursodesoxicólico", "D) Antibiótico venoso e drenagem biliar por CPRE, com colecistectomia depois"]'::jsonb,
    'A tríade de Charcot com cálculo no colédoco define colangite aguda. O tratamento é antibiótico venoso e desobstrução da via biliar, preferencialmente por CPRE com papilotomia, com urgência proporcional à gravidade. Depois, faz-se a colecistectomia para evitar recidiva.',
    'MEDIUM',
    'Diretrizes de Tóquio TG18 e ASGE 2019 para coledocolitíase (questão original)',
    TRUE
),
(
    2,
    'Vias Biliares - Colelitíase e Coledocolitíase',
    'MULTIPLE_CHOICE',
    'Mulher de 45 anos com cólica biliar tem bilirrubina total de 2,8 mg/dL e colédoco de 8 mm na ultrassonografia, sem cálculo visível no colédoco e sem colangite. Pelo critério de risco da ASGE, qual é o próximo passo antes da colecistectomia?',
    'A',
    '["A) Colangiorressonância ou ecoendoscopia para investigar o colédoco", "B) CPRE terapêutica imediata para todos os casos", "C) Colecistectomia sem nenhuma avaliação do colédoco", "D) Tomografia de abdome sem contraste como exame definitivo"]'::jsonb,
    'Esses dados colocam a paciente em risco intermediário de coledocolitíase. A ASGE recomenda confirmar com colangiorressonância ou ecoendoscopia (ou colangiografia intraoperatória), reservando a CPRE, que tem riscos como pancreatite, para quem tem cálculo confirmado ou risco alto.',
    'HARD',
    'Diretrizes ASGE 2019 para coledocolitíase (questão original)',
    TRUE
);

-- -----------------------------------------------------------------------------
-- 5. MEDICINA — PEDIATRIA (54 questões)
-- -----------------------------------------------------------------------------
INSERT INTO tb_flashcard (subject_id, topic, question_type, question, answer, options_json, explanation, difficulty, source, active)
VALUES
(
    3,
    'Aleitamento Materno - Diretrizes OMS',
    'MULTIPLE_CHOICE',
    'Segundo o Ministério da Saúde, em qual situação materna o aleitamento materno é contraindicado no Brasil, devendo o lactente receber fórmula infantil?',
    'C',
    '["A) Mãe com mastite puerperal em tratamento", "B) Mãe com hepatite B, com o RN vacinado e tendo recebido imunoglobulina", "C) Mãe vivendo com HIV", "D) Mãe tabagista que não conseguiu cessar o fumo"]'::jsonb,
    'No Brasil, mães vivendo com HIV (e também com HTLV 1/2) não devem amamentar, e o SUS fornece fórmula infantil. Na mastite a amamentação deve continuar; na hepatite B a imunoprofilaxia do RN permite amamentar; o tabagismo exige orientação, não suspensão.',
    'EASY',
    'Ministério da Saúde - Saúde da Criança: Aleitamento Materno (questão original)',
    TRUE
),
(
    3,
    'Aleitamento Materno - Diretrizes OMS',
    'MULTIPLE_CHOICE',
    'Mãe de lactente de 7 meses em alimentação complementar pergunta quando pode começar a adoçar sucos e papas com açúcar. Pelo Guia Alimentar para Crianças Brasileiras Menores de 2 Anos, qual a orientação?',
    'C',
    '["A) Pode usar açúcar a partir dos 9 meses, em pequena quantidade", "B) Pode usar mel no lugar do açúcar desde os 6 meses", "C) Não oferecer açúcar nem alimentos com açúcar antes dos 2 anos", "D) Pode usar açúcar a partir de 1 ano, quando a criança come a comida da família"]'::jsonb,
    'O Guia do MS (2019) recomenda não oferecer açúcar nem preparações ou produtos que o contenham até os 2 anos, e evitar ultraprocessados. O mel é ainda contraindicado no 1º ano pelo risco de botulismo, por isso a opção com mel está errada.',
    'MEDIUM',
    'Guia Alimentar para Crianças Brasileiras Menores de 2 Anos - MS 2019 (questão original)',
    TRUE
),
(
    3,
    'Aleitamento Materno - Diretrizes OMS',
    'MULTIPLE_CHOICE',
    'Ao observar uma mamada no alojamento conjunto, qual achado indica pega adequada?',
    'A',
    '["A) Boca bem aberta, lábio inferior virado para fora e queixo tocando a mama", "B) Bochechas encovadas a cada sucção", "C) Mais aréola visível abaixo do que acima da boca do bebê", "D) Estalidos audíveis durante a sucção"]'::jsonb,
    'Na pega adequada a boca está bem aberta, o lábio inferior evertido, o queixo toca a mama e aparece mais aréola acima do que abaixo da boca. Bochechas encovadas e estalidos sugerem sucção ineficaz e pega incorreta.',
    'MEDIUM',
    'Ministério da Saúde - Caderno de Atenção Básica 23 (questão original)',
    TRUE
),
(
    3,
    'Emergências Pediátricas - Choque, Convulsão Febril e Intoxicações',
    'MULTIPLE_CHOICE',
    'Criança de 18 meses, previamente hígida, teve crise tônico-clônica generalizada de 3 minutos durante febre por virose, recuperando a consciência em seguida. Exame neurológico normal. Qual a conduta?',
    'C',
    '["A) Iniciar fenobarbital profilático por 2 anos", "B) Solicitar EEG e ressonância de crânio antes da alta", "C) Orientar e tranquilizar a família, tratar a febre e não indicar EEG, neuroimagem ou anticonvulsivante contínuo", "D) Prescrever antitérmico de horário para evitar nova crise"]'::jsonb,
    'É uma convulsão febril simples (6 meses a 5 anos, generalizada, menor que 15 minutos, única em 24 horas). Tem bom prognóstico e não exige exames nem profilaxia; antitérmico melhora o conforto mas não previne recorrência.',
    'MEDIUM',
    'SBP - Convulsão febril (questão original)',
    TRUE
),
(
    3,
    'Emergências Pediátricas - Choque, Convulsão Febril e Intoxicações',
    'MULTIPLE_CHOICE',
    'Criança de 2 anos ingeriu, há 30 minutos, um gole de produto de limpeza alcalino (soda cáustica diluída). Está estável, com sialorreia e recusa alimentar. Qual é a conduta adequada?',
    'A',
    '["A) Jejum, avaliação das vias aéreas e endoscopia digestiva alta nas primeiras 12 a 24 horas", "B) Induzir o vômito com xarope de ipeca", "C) Oferecer vinagre ou suco de limão para neutralizar o álcali", "D) Lavagem gástrica com sonda calibrosa"]'::jsonb,
    'Na ingestão de cáusticos não se induz vômito, não se tenta neutralizar nem se faz lavagem, pois o refluxo do agente e a reação química ampliam a lesão. Mantém-se jejum, protege-se a via aérea e a endoscopia nas primeiras 12 a 24 horas define a gravidade das lesões.',
    'MEDIUM',
    'Tratado de Pediatria da SBP - Intoxicações (questão original)',
    TRUE
),
(
    3,
    'Emergências Pediátricas - Choque, Convulsão Febril e Intoxicações',
    'MULTIPLE_CHOICE',
    'Criança em choque séptico continua hipotensa e com má perfusão após 40 mL/kg de cristaloide na primeira hora, já com antibiótico. Qual droga vasoativa é recomendada como primeira escolha?',
    'C',
    '["A) Dopamina", "B) Dobutamina isolada", "C) Adrenalina ou noradrenalina", "D) Vasopressina isolada"]'::jsonb,
    'A Surviving Sepsis Campaign pediátrica (2020) recomenda adrenalina ou noradrenalina, em vez de dopamina, no choque refratário a volume, podendo iniciar por acesso periférico ou intraósseo. Dobutamina e vasopressina não são primeira escolha isoladas.',
    'HARD',
    'Surviving Sepsis Campaign - Pediatria 2020 (questão original)',
    TRUE
),
(
    3,
    'Gastroenterologia Pediátrica - Desidratação',
    'MULTIPLE_CHOICE',
    'Criança de 2 anos com diarreia aguda está alerta, com olhos normais, bebe normalmente e a prega cutânea desaparece rapidamente. Pelo manejo do Ministério da Saúde, qual conduta se aplica?',
    'A',
    '["A) Tratamento no domicílio, com mais líquidos e soro de reidratação oral após cada evacuação", "B) Reidratação oral supervisionada na unidade de saúde", "C) Hidratação venosa", "D) Internação para observação"]'::jsonb,
    'Sem sinais de desidratação aplica-se o Plano A: aumentar a oferta de líquidos e de SRO após cada evacuação, manter a alimentação, suplementar zinco e orientar os sinais de alerta. A reidratação oral na unidade (Plano B) é para desidratação, e a hidratação venosa (Plano C) para desidratação grave.',
    'EASY',
    'Ministério da Saúde - Manejo do Paciente com Diarreia (questão original)',
    TRUE
),
(
    3,
    'Gastroenterologia Pediátrica - Desidratação',
    'MULTIPLE_CHOICE',
    'No Plano A do Ministério da Saúde para uma criança de 1 ano com diarreia aguda, qual suplementação deve ser prescrita?',
    'C',
    '["A) Ferro 3 mg/kg/dia por 30 dias", "B) Vitamina A 200.000 UI diárias por 5 dias", "C) Zinco 20 mg/dia por 10 a 14 dias", "D) Probiótico obrigatório por 30 dias"]'::jsonb,
    'O MS orienta zinco por 10 a 14 dias em menores de 5 anos com diarreia: 10 mg/dia abaixo de 6 meses e 20 mg/dia a partir de 6 meses. Reduz duração e gravidade do episódio e recorrências nos meses seguintes.',
    'MEDIUM',
    'Ministério da Saúde - Manejo do Paciente com Diarreia (questão original)',
    TRUE
),
(
    3,
    'Gastroenterologia Pediátrica - Desidratação',
    'MULTIPLE_CHOICE',
    'Criança de 2 anos com diarreia está letárgica, não consegue beber, tem olhos muito fundos, pulso fraco e prega cutânea que desaparece muito lentamente. Qual a conduta inicial pelo Plano C do MS?',
    'C',
    '["A) SRO 100 mL/kg em 4 horas na unidade de saúde", "B) Soro glicosado 5%, 20 mL/kg em bolus", "C) Expansão venosa com soro fisiológico 0,9%, 20 mL/kg em 30 minutos, repetindo conforme reavaliação", "D) Hidratação venosa de manutenção e reavaliação em 24 horas"]'::jsonb,
    'Desidratação grave exige Plano C. Para menores de 5 anos o MS indica fase rápida com SF 0,9% 20 mL/kg em 30 minutos, repetida até a hidratação, com reavaliação a cada etapa. Soro glicosado não expande volemia e a via oral não é segura na letargia.',
    'HARD',
    'Ministério da Saúde - Manejo do Paciente com Diarreia (questão original)',
    TRUE
),
(
    3,
    'Imunização - Calendário PNI',
    'MULTIPLE_CHOICE',
    'Recém-nascido saudável de 1 dia de vida, ainda na maternidade. Pelo Calendário Nacional de Vacinação, quais vacinas devem ser aplicadas?',
    'B',
    '["A) Hepatite B e pentavalente", "B) BCG e hepatite B", "C) BCG e VIP", "D) BCG, hepatite B e rotavírus"]'::jsonb,
    'Ao nascer o PNI prevê BCG em dose única e a dose de hepatite B, idealmente nas primeiras 12 a 24 horas. Pentavalente, VIP e rotavírus iniciam aos 2 meses.',
    'EASY',
    'Calendário Nacional de Vacinação - PNI/MS (questão original)',
    TRUE
),
(
    3,
    'Imunização - Calendário PNI',
    'MULTIPLE_CHOICE',
    'Criança de 9 meses, com calendário em dia até então, comparece à sala de vacina. Qual vacina de rotina do PNI está prevista para essa idade em todo o território nacional?',
    'C',
    '["A) Tríplice viral", "B) Hepatite A", "C) Febre amarela", "D) Varicela"]'::jsonb,
    'A febre amarela é aplicada aos 9 meses em todo o país, com reforço aos 4 anos. Tríplice viral entra aos 12 meses; hepatite A e o componente varicela (tetra viral) aos 15 meses.',
    'MEDIUM',
    'Calendário Nacional de Vacinação - PNI/MS (questão original)',
    TRUE
),
(
    3,
    'Imunização - Calendário PNI',
    'MULTIPLE_CHOICE',
    'Lactente de 4 meses e 10 dias nunca foi vacinado e chega à UBS pela primeira vez. Em relação à vacina oral de rotavírus humano, qual a conduta correta pelo PNI?',
    'D',
    '["A) Aplicar a primeira dose e a segunda após 30 dias", "B) Aplicar dose única de reforço", "C) Aplicar só após completar o esquema de pentavalente", "D) Não aplicar, pois passou da idade máxima para a primeira dose"]'::jsonb,
    'O PNI permite a 1ª dose de rotavírus até 3 meses e 15 dias e a 2ª até 7 meses e 29 dias, pela associação de doses tardias com maior risco de invaginação intestinal. Fora dessa janela a vacina não deve ser iniciada; as demais vacinas atrasadas são atualizadas.',
    'HARD',
    'Calendário Nacional de Vacinação - PNI/MS (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Doenças Exantemáticas',
    'MULTIPLE_CHOICE',
    'Lactente de 10 meses teve febre alta por 3 dias, em bom estado geral. No dia em que a febre cessou surgiu exantema maculopapular róseo no tronco. Qual o diagnóstico mais provável?',
    'A',
    '["A) Exantema súbito (roséola), pelo herpesvírus humano 6", "B) Sarampo", "C) Escarlatina", "D) Doença de Kawasaki"]'::jsonb,
    'O exantema súbito é típico de lactentes: febre alta por 3 a 5 dias e exantema que aparece quando a febre desaparece. No sarampo e na escarlatina o exantema surge com a febre, e Kawasaki exige febre persistente por 5 dias ou mais.',
    'EASY',
    'Tratado de Pediatria SBP - Doenças exantemáticas (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Doenças Exantemáticas',
    'MULTIPLE_CHOICE',
    'Escolar de 7 anos, afebril, apresenta eritema intenso nas bochechas com aspecto de face esbofeteada e, dias depois, exantema rendilhado nos membros. Qual complicação é mais temida se a criança tiver anemia falciforme?',
    'D',
    '["A) Glomerulonefrite pós-infecciosa", "B) Síndrome de Reye", "C) Panencefalite esclerosante subaguda", "D) Crise aplásica transitória"]'::jsonb,
    'O quadro é de eritema infeccioso pelo parvovírus B19, que infecta precursores eritroides e pode causar crise aplásica em pacientes com hemólise crônica. A panencefalite é tardia do sarampo, e a síndrome de Reye se associa ao AAS na varicela e influenza.',
    'MEDIUM',
    'Tratado de Pediatria SBP - Doenças exantemáticas (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Doenças Exantemáticas',
    'MULTIPLE_CHOICE',
    'Criança de 6 anos tem febre, dor de garganta e exantema áspero em lixa, mais intenso nas dobras com linhas de Pastia, palidez perioral e língua em framboesa. Qual o agente e o tratamento?',
    'B',
    '["A) Staphylococcus aureus; oxacilina venosa", "B) Streptococcus pyogenes; penicilina benzatina dose única ou amoxicilina por 10 dias", "C) Parvovírus B19; sintomáticos", "D) Vírus Epstein-Barr; amoxicilina por 5 dias"]'::jsonb,
    'Exantema em lixa, sinal de Pastia, palidez perioral e língua em framboesa definem a escarlatina pelo estreptococo beta-hemolítico do grupo A, tratada como a faringite estreptocócica. Amoxicilina na mononucleose costuma provocar exantema e não está indicada.',
    'HARD',
    'Tratado de Pediatria SBP - Doenças exantemáticas (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Laringite Aguda / Crupe',
    'MULTIPLE_CHOICE',
    'Na radiografia cervical em incidência anteroposterior de uma criança com laringotraqueobronquite viral, qual sinal pode ser observado?',
    'B',
    '["A) Sinal do polegar, por edema da epiglote", "B) Sinal da torre (ponta de lápis), por estreitamento subglótico", "C) Sinal da vela de barco, por timo normal", "D) Imagem em vidro fosco difusa"]'::jsonb,
    'No crupe o edema subglótico afila a coluna aérea, formando o sinal da torre ou ponta de lápis. O sinal do polegar, em perfil, é da epiglotite. A radiografia não é necessária para o diagnóstico, que é clínico.',
    'EASY',
    'Tratado de Pediatria SBP - Obstrução inflamatória aguda de vias aéreas (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Laringite Aguda / Crupe',
    'MULTIPLE_CHOICE',
    'Criança de 2 anos tem tosse ladrante e rouquidão há 1 dia, sem estridor em repouso, sem tiragem e com boa saturação. Qual a conduta mais adequada?',
    'D',
    '["A) Nebulização com adrenalina e internação", "B) Amoxicilina oral por 7 dias", "C) Intubação orotraqueal eletiva", "D) Dexametasona oral em dose única e alta com orientações"]'::jsonb,
    'Mesmo no crupe leve a dose única de dexametasona reduz a evolução e o retorno ao serviço. A adrenalina nebulizada é reservada ao estridor em repouso ou desconforto moderado a grave, e o quadro é viral, sem indicação de antibiótico.',
    'MEDIUM',
    'Tratado de Pediatria SBP - Obstrução inflamatória aguda de vias aéreas (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Laringite Aguda / Crupe',
    'MULTIPLE_CHOICE',
    'Criança de 3 anos, sem vacinas, apresenta febre alta súbita, toxemia, sialorreia e posição em tripé, sem tosse ladrante. Qual a conduta inicial mais adequada?',
    'C',
    '["A) Examinar a orofaringe com abaixador de língua para confirmar o diagnóstico", "B) Deitar a criança e puncionar acesso venoso antes de chamar a equipe de via aérea", "C) Manter a criança calma no colo dos pais e garantir a via aérea em ambiente controlado, sem examinar a orofaringe com abaixador", "D) Nebulizar com adrenalina e liberar após 4 horas de observação"]'::jsonb,
    'O quadro sugere epiglotite (Haemophilus influenzae tipo b em não vacinados). Manipulação da orofaringe, decúbito e procedimentos dolorosos podem precipitar obstrução total; a via aérea deve ser assegurada por equipe experiente, seguida de antibiótico.',
    'HARD',
    'Tratado de Pediatria SBP - Obstrução inflamatória aguda de vias aéreas (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Meningite Bacteriana',
    'MULTIPLE_CHOICE',
    'Qual perfil do líquor é característico de meningite bacteriana aguda na criança?',
    'B',
    '["A) Pleocitose linfocitária, glicose normal e proteína discretamente elevada", "B) Pleocitose com predomínio de neutrófilos, glicose baixa e proteína elevada", "C) Celularidade normal, glicose normal e proteína muito elevada", "D) Pleocitose eosinofílica com glicose normal"]'::jsonb,
    'Na meningite bacteriana há centenas a milhares de células com predomínio neutrofílico, hipoglicorraquia e hiperproteinorraquia. Predomínio linfocitário com glicose normal sugere etiologia viral; dissociação proteinocitológica lembra Guillain-Barré.',
    'EASY',
    'Ministério da Saúde - Guia de Vigilância em Saúde: meningites (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Meningite Bacteriana',
    'MULTIPLE_CHOICE',
    'Criança de 2 anos, previamente hígida, chega com febre, vômitos, rigidez de nuca e petéquias. Após coleta de hemocultura, qual antibiótico empírico é indicado?',
    'D',
    '["A) Amoxicilina oral em dose alta", "B) Ampicilina associada a gentamicina", "C) Azitromicina endovenosa", "D) Ceftriaxona endovenosa"]'::jsonb,
    'Acima de 3 meses os agentes principais são meningococo e pneumococo, cobertos pela ceftriaxona (cefalosporina de 3ª geração), que não deve ser adiada se a punção lombar demorar. Ampicilina com gentamicina é esquema neonatal.',
    'MEDIUM',
    'Ministério da Saúde - Guia de Vigilância em Saúde: meningites (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Meningite Bacteriana',
    'MULTIPLE_CHOICE',
    'No tratamento empírico da meningite bacteriana no período neonatal, a ampicilina faz parte do esquema. Qual agente justifica sua inclusão, por não ser coberto pelas cefalosporinas?',
    'A',
    '["A) Listeria monocytogenes", "B) Streptococcus agalactiae", "C) Escherichia coli", "D) Neisseria meningitidis"]'::jsonb,
    'Listeria monocytogenes é intrinsecamente resistente às cefalosporinas, por isso a ampicilina entra no esquema do RN e do lactente jovem. Estreptococo do grupo B, E. coli e meningococo costumam ser cobertos pelas cefalosporinas de 3ª geração.',
    'HARD',
    'Tratado de Pediatria SBP - Meningites bacterianas (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Otite Média e Faringoamigdalite',
    'MULTIPLE_CHOICE',
    'Qual é a bactéria mais frequentemente isolada na otite média aguda da criança?',
    'C',
    '["A) Staphylococcus aureus", "B) Pseudomonas aeruginosa", "C) Streptococcus pneumoniae", "D) Streptococcus pyogenes"]'::jsonb,
    'Pneumococo é o principal agente da otite média aguda, seguido de Haemophilus influenzae não tipável e Moraxella catarrhalis. Pseudomonas e S. aureus são mais associados à otite externa e à otite crônica.',
    'EASY',
    'SBP - Otite média aguda (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Otite Média e Faringoamigdalite',
    'MULTIPLE_CHOICE',
    'Criança de 3 anos tem otalgia intensa e febre de 39,5 °C; a otoscopia mostra membrana timpânica abaulada e hiperemiada. Não usou antibiótico nos últimos 30 dias nem tem conjuntivite. Qual a primeira escolha?',
    'C',
    '["A) Azitromicina oral por 3 dias", "B) Ceftriaxona intramuscular dose única", "C) Amoxicilina oral", "D) Gotas otológicas de ciprofloxacino"]'::jsonb,
    'Na otite média aguda com sinais de gravidade a amoxicilina é a primeira escolha. Amoxicilina-clavulanato fica para uso recente de amoxicilina ou otite com conjuntivite; macrolídeos, só na alergia; ceftriaxona IM, para quem não aceita via oral; gotas não tratam a orelha média com membrana íntegra.',
    'MEDIUM',
    'SBP - Otite média aguda (questão original)',
    TRUE
),
(
    3,
    'Infectologia Pediátrica - Otite Média e Faringoamigdalite',
    'MULTIPLE_CHOICE',
    'Escolar com faringoamigdalite estreptocócica confirmada por teste rápido chega ao 6º dia de sintomas sem tratamento. Qual afirmação sobre o antibiótico está correta?',
    'A',
    '["A) Ainda está indicado, pois iniciado até 9 dias do início dos sintomas previne a febre reumática", "B) Não está mais indicado, pois só previne febre reumática se iniciado nas primeiras 48 horas", "C) Está indicado principalmente para prevenir a glomerulonefrite pós-estreptocócica", "D) Deve ser feito por 5 dias com cefalexina para evitar resistência"]'::jsonb,
    'O tratamento da faringite estreptocócica (penicilina benzatina ou amoxicilina por 10 dias) iniciado até o 9º dia dos sintomas previne a febre reumática. Ele não previne a glomerulonefrite pós-estreptocócica de forma comprovada.',
    'HARD',
    'SBC / SBP - Diretrizes de febre reumática (questão original)',
    TRUE
),
(
    3,
    'Nefrologia Pediátrica - Infecção do Trato Urinário',
    'MULTIPLE_CHOICE',
    'Qual o agente etiológico mais frequente da infecção do trato urinário na criança?',
    'A',
    '["A) Escherichia coli", "B) Staphylococcus saprophyticus", "C) Enterococcus faecalis", "D) Pseudomonas aeruginosa"]'::jsonb,
    'A E. coli uropatogênica responde pela maioria das ITUs pediátricas. S. saprophyticus aparece em adolescentes sexualmente ativas, e Pseudomonas e enterococo em ITU complicada, com malformações ou após manipulação.',
    'EASY',
    'SBP - Infecção do trato urinário na infância (questão original)',
    TRUE
),
(
    3,
    'Nefrologia Pediátrica - Infecção do Trato Urinário',
    'MULTIPLE_CHOICE',
    'Criança de 2 anos com pielonefrite confirmada está em bom estado geral, hidratada e aceitando bem a via oral. Qual a conduta?',
    'D',
    '["A) Internação obrigatória para antibiótico venoso", "B) Nitrofurantoína oral por 5 dias", "C) Aguardar o resultado da urocultura antes de tratar", "D) Antibiótico oral ambulatorial, com reavaliação em 48 a 72 horas"]'::jsonb,
    'Pielonefrite em criança com bom estado geral e aceitação oral pode ser tratada por via oral (por exemplo, cefalosporina), com eficácia igual à venosa. Nitrofurantoína não atinge nível no parênquima renal e não serve para ITU febril.',
    'MEDIUM',
    'SBP - Infecção do trato urinário na infância (questão original)',
    TRUE
),
(
    3,
    'Nefrologia Pediátrica - Infecção do Trato Urinário',
    'MULTIPLE_CHOICE',
    'Lactente de 1 ano teve o primeiro episódio de ITU febril, com boa resposta ao tratamento. Qual a investigação por imagem inicial recomendada?',
    'B',
    '["A) Uretrocistografia miccional de rotina em todos os casos", "B) Ultrassonografia de rins e vias urinárias, reservando a uretrocistografia miccional para alteração ou recorrência", "C) Tomografia de abdome com contraste", "D) Nenhuma investigação, nem mesmo ultrassonografia"]'::jsonb,
    'Após a primeira ITU febril em lactente faz-se ultrassonografia renal e de vias urinárias. A uretrocistografia miccional fica para ultrassom alterado, ITU febril recorrente ou evolução atípica, evitando irradiação e sondagem desnecessárias.',
    'HARD',
    'SBP - Infecção do trato urinário na infância (questão original)',
    TRUE
),
(
    3,
    'Nefrologia Pediátrica - Síndrome Nefrótica e Nefrítica',
