    'Na glomerulonefrite pós-estreptocócica há consumo transitório do complemento, com C3 baixo que normaliza em até 6 a 8 semanas. C3 baixo persistente sugere outra glomerulopatia, como a membranoproliferativa.',
    'EASY',
