    'D',
    '["A) Biópsia renal antes de qualquer tratamento", "B) Ciclofosfamida como primeira linha", "C) Restrição proteica rigorosa sem corticoide", "D) Corticoterapia oral com prednisona ou prednisolona, sem biópsia renal inicial"]'::jsonb,
    'Nessa faixa etária o quadro típico corresponde, na maioria, à doença de lesões mínimas, sensível a corticoide. Trata-se empiricamente com corticoide oral; a biópsia fica para corticorresistência ou apresentação atípica.',
