(
    3,
    'Nefrologia Pediátrica - Síndrome Nefrótica e Nefrítica',
    'MULTIPLE_CHOICE',
    'Na glomerulonefrite pós-estreptocócica com edema e hipertensão, qual o tratamento adequado?',
    'A',
    '["A) Restrição de sódio e de líquidos e diurético de alça, como furosemida", "B) Pulsoterapia com metilprednisolona", "C) Penicilina benzatina mensal para reverter a lesão renal", "D) Inibidor da ECA isolado com liberação de sal"]'::jsonb,
    'A hipertensão e o edema decorrem de retenção de sódio e água, por isso tratam-se com restrição hidrossalina e furosemida. Corticoide não tem papel, e o antibiótico erradica o estreptococo mas não altera o curso da nefrite.',
