(
    3,
    'Neonatologia - Icterícia e Triagens Neonatais',
    'MULTIPLE_CHOICE',
    'RN a termo apresenta icterícia visível com 18 horas de vida. Como deve ser interpretado esse achado?',
    'A',
    '["A) Icterícia patológica até prova em contrário, exigindo dosagem de bilirrubinas e investigação de hemólise", "B) Icterícia fisiológica, sem necessidade de exames", "C) Icterícia do leite materno, devendo suspender a amamentação", "D) Icterícia por baixa ingesta, tratada com complemento de glicose"]'::jsonb,
    'Icterícia nas primeiras 24 horas é sempre considerada patológica, frequentemente por doença hemolítica (incompatibilidade Rh ou ABO). A fisiológica aparece após 24 horas, e a do leite materno é tardia, após a primeira semana.',
    'EASY',
    'SBP - Icterícia no RN com idade gestacional ≥ 35 semanas (questão original)',
