),
(
    3,
    'Neonatologia - Icterícia e Triagens Neonatais',
    'MULTIPLE_CHOICE',
    'Segundo o Programa Nacional de Triagem Neonatal do Ministério da Saúde, qual o período ideal para a coleta do teste do pezinho?',
    'B',
    '["A) Nas primeiras 24 horas de vida, antes da alta", "B) Entre o 3º e o 5º dia de vida", "C) Entre o 10º e o 15º dia de vida", "D) Na consulta de 1 mês de puericultura"]'::jsonb,
    'O MS recomenda coletar entre o 3º e o 5º dia: antes de 48 horas de alimentação há risco de falso-negativo para fenilcetonúria e outras doenças, e coleta tardia atrasa o tratamento de condições como hipotireoidismo congênito.',
    'MEDIUM',
    'Programa Nacional de Triagem Neonatal - Ministério da Saúde (questão original)',
