(
    3,
    'Neonatologia - Icterícia e Triagens Neonatais',
    'MULTIPLE_CHOICE',
    'No teste do coraçãozinho de um RN de 38 semanas com 30 horas de vida, a saturação é 97% no membro superior direito e 93% no membro inferior. Qual a conduta?',
    'D',
    '["A) Considerar normal, pois a média das medidas está acima de 90%", "B) Dar alta e repetir o teste na consulta de 7 dias", "C) Iniciar prostaglandina imediatamente sem novos exames", "D) Considerar alterado, repetir a aferição em 1 hora e, se persistir, solicitar ecocardiograma em até 24 horas"]'::jsonb,
    'A oximetria é normal quando ambas as medidas são de 95% ou mais e a diferença é menor que 3%. Valor abaixo de 95% ou diferença de 3% ou mais exige nova aferição em 1 hora; se mantida, ecocardiograma em 24 horas, sem alta antes da investigação.',
    'HARD',
    'SBP / MS - Triagem neonatal de cardiopatia congênita crítica (questão original)',
    TRUE
),
(
    3,
    'Neonatologia - Reanimação em Sala de Parto',
    'MULTIPLE_CHOICE',
    'RN de 30 semanas nasce em apneia e, após os passos iniciais, mantém FC de 80 bpm. Pela diretriz de reanimação neonatal da SBP, com qual concentração de oxigênio se inicia a ventilação com pressão positiva?',
    'C',
    '["A) 21%", "B) 60%", "C) 30%", "D) 100%"]'::jsonb,
    'A SBP orienta iniciar a VPP com O2 a 30% no RN abaixo de 34 semanas e com ar ambiente (21%) no RN com 34 semanas ou mais, ajustando depois pela oximetria. O2 a 100% é reservado para a massagem cardíaca.',
    'MEDIUM',
    'Diretriz de Reanimação Neonatal SBP 2022 (questão original)',
    TRUE
),
(
    3,
    'Neonatologia - Reanimação em Sala de Parto',
    'MULTIPLE_CHOICE',
    'RN a termo nasce com líquido amniótico meconial, hipotônico e sem respirar. Pela diretriz da SBP, qual a conduta?',
    'B',
    '["A) Intubar de rotina para aspirar mecônio da traqueia antes de ventilar", "B) Realizar os passos iniciais e, se persistir em apneia, iniciar ventilação com pressão positiva ainda no primeiro minuto", "C) Aspirar boca e narinas do RN ainda no períneo, antes do desprendimento dos ombros", "D) Iniciar massagem cardíaca imediatamente"]'::jsonb,
    'A SBP não recomenda aspiração traqueal de rotina no RN não vigoroso com mecônio nem aspiração intraparto: atrasa a ventilação, que é o procedimento mais importante. Faz-se os passos iniciais e VPP no minuto de ouro se houver apneia ou FC abaixo de 100.',
    'MEDIUM',
    'Diretriz de Reanimação Neonatal SBP 2022 (questão original)',
    TRUE
),
(
    3,
    'Neonatologia - Reanimação em Sala de Parto',
    'MULTIPLE_CHOICE',
    'RN a termo em reanimação: após 30 segundos de ventilação com pressão positiva com técnica adequada por cânula traqueal, a FC continua 50 bpm. Qual o próximo passo?',
    'D',
    '["A) Administrar adrenalina antes de qualquer compressão", "B) Manter só a ventilação por mais 2 minutos com ar ambiente", "C) Administrar expansor de volume e reavaliar em 5 minutos", "D) Iniciar compressões torácicas coordenadas com a ventilação (3:1) e elevar o O2 para 100%"]'::jsonb,
    'Com FC abaixo de 60 bpm após 30 s de VPP efetiva, a SBP indica massagem cardíaca (técnica dos dois polegares) na relação 3:1 com a ventilação e O2 a 100%. Adrenalina vem se a FC seguir abaixo de 60 após 60 s de massagem e VPP; volume só se houver suspeita de hipovolemia.',
    'HARD',
    'Diretriz de Reanimação Neonatal SBP 2022 (questão original)',
    TRUE
),
(
    3,
    'Neonatologia - Sepse Neonatal',
    'MULTIPLE_CHOICE',
    'Quais são os agentes mais frequentes da sepse neonatal precoce, adquirida por transmissão vertical?',
    'A',
    '["A) Streptococcus agalactiae (grupo B) e Escherichia coli", "B) Staphylococcus coagulase-negativo e Candida", "C) Pseudomonas aeruginosa e Klebsiella multirresistente", "D) Streptococcus pneumoniae e Haemophilus influenzae"]'::jsonb,
    'A sepse precoce reflete a flora do trato genital materno: estreptococo do grupo B e E. coli predominam. Estafilococo coagulase-negativo, Candida e Gram-negativos multirresistentes são típicos da sepse tardia hospitalar.',
    'EASY',
    'Ministério da Saúde - Atenção à Saúde do Recém-Nascido (questão original)',
    TRUE
),
(
    3,
    'Neonatologia - Sepse Neonatal',
    'MULTIPLE_CHOICE',
    'RN de 36 horas, filho de mãe com bolsa rota há 24 horas e febre intraparto, evolui com desconforto respiratório e má perfusão. Após colher hemocultura, qual antibioticoterapia empírica é a mais indicada?',
    'C',
    '["A) Oxacilina associada a amicacina", "B) Vancomicina associada a meropenem", "C) Ampicilina associada a gentamicina", "D) Ceftriaxona isolada"]'::jsonb,
    'Na sepse precoce o esquema empírico clássico do MS é ampicilina mais aminoglicosídeo (gentamicina), cobrindo estreptococo do grupo B, Listeria e E. coli. Oxacilina com amicacina é usada na sepse tardia; ceftriaxona não cobre Listeria e desloca bilirrubina.',
    'MEDIUM',
    'Ministério da Saúde - Atenção à Saúde do Recém-Nascido (questão original)',
    TRUE
),
(
    3,
    'Neonatologia - Sepse Neonatal',
    'MULTIPLE_CHOICE',
    'Prematuro de 28 semanas, há 15 dias na UTI neonatal com cateter venoso central, apresenta apneias e instabilidade térmica. Qual o agente mais provável dessa sepse tardia?',
    'C',
    '["A) Streptococcus agalactiae", "B) Listeria monocytogenes", "C) Staphylococcus coagulase-negativo", "D) Treponema pallidum"]'::jsonb,
    'Na sepse tardia associada a cateter em prematuros, o estafilococo coagulase-negativo é o agente mais comum. Estreptococo do grupo B e Listeria predominam na sepse precoce de transmissão vertical.',
    'MEDIUM',
    'Ministério da Saúde - Atenção à Saúde do Recém-Nascido (questão original)',
