(
    3,
    'Pneumologia Pediátrica - Asma na Infância',
    'MULTIPLE_CHOICE',
    'Escolar de 8 anos com asma chega em crise com sibilos e tosse. Qual a primeira medida farmacológica?',
    'A',
    '["A) Beta-2 agonista de curta ação inalatório, preferencialmente por spray com espaçador", "B) Aminofilina endovenosa", "C) Antibiótico oral", "D) Montelucaste oral"]'::jsonb,
    'O broncodilatador beta-2 de curta ação inalatório (salbutamol, de preferência com espaçador) é o tratamento inicial da crise. Aminofilina não é rotina, e montelucaste não tem papel na crise aguda.',
    'EASY',
    'GINA 2024 / SBP - Asma na infância (questão original)',
