),
(
    3,
    'Pneumologia Pediátrica - Asma na Infância',
    'MULTIPLE_CHOICE',
    'Criança de 6 anos em crise asmática moderada recebeu as doses iniciais de broncodilatador com melhora parcial. Qual medida, iniciada precocemente, reduz o risco de internação?',
    'B',
    '["A) Antibiótico de amplo espectro", "B) Corticoide sistêmico, como prednisolona oral", "C) Antitussígeno", "D) Corticoide inalatório isolado em dose baixa"]'::jsonb,
    'Na crise moderada ou grave, ou sem resposta completa ao broncodilatador, o corticoide sistêmico na primeira hora reduz internação e recaída; a via oral é tão eficaz quanto a venosa quando tolerada.',
    'MEDIUM',
    'GINA 2024 / SBP - Asma na infância (questão original)',
