),
(
    3,
    'Pneumologia Pediátrica - Asma na Infância',
    'MULTIPLE_CHOICE',
    'Pré-escolar de 4 anos tem episódios de sibilância frequentes e sintomas que não são controlados só com broncodilatador de resgate. Qual o tratamento de manutenção preferencial?',
    'D',
    '["A) Beta-2 agonista de longa ação isolado", "B) Prednisolona oral contínua", "C) Salbutamol inalatório de horário, sem anti-inflamatório", "D) Corticoide inalatório em dose baixa, diário"]'::jsonb,
    'Para crianças de até 5 anos com sintomas não controlados, a GINA indica corticoide inalatório em dose baixa diário como controlador preferencial; montelucaste é alternativa. LABA isolado e beta-2 de horário não tratam a inflamação, e corticoide oral contínuo tem efeitos adversos inaceitáveis.',
