    3,
    'Pneumologia Pediátrica - Bronquiolite Viral Aguda',
    'MULTIPLE_CHOICE',
    'Qual das condições abaixo é fator de risco reconhecido para bronquiolite viral aguda grave?',
    'D',
    '["A) Aleitamento materno exclusivo", "B) Idade acima de 18 meses", "C) Sexo feminino", "D) Prematuridade"]'::jsonb,
    'Prematuridade, idade menor que 3 meses, cardiopatia congênita com repercussão hemodinâmica, doença pulmonar crônica e imunodeficiência aumentam o risco de evolução grave. O aleitamento materno é fator de proteção.',
    'EASY',
    'SBP - Diretrizes para o manejo da bronquiolite viral aguda (questão original)',
