),
(
    3,
    'Pneumologia Pediátrica - Bronquiolite Viral Aguda',
    'MULTIPLE_CHOICE',
    'Lactente de 2 meses com bronquiolite viral aguda, saturação de 95% e FR de 48 irpm. A mãe refere que ele parou de respirar por alguns segundos em casa. Qual a conduta?',
    'B',
    '["A) Alta com lavagem nasal, pois a saturação está normal", "B) Internar para monitorização, pois apneia é critério de internação", "C) Alta com salbutamol inalatório e retorno em 48 horas", "D) Alta com prednisolona oral por 3 dias"]'::jsonb,
    'Apneia, especialmente em menores de 3 meses, indica internação mesmo com saturação normal, assim como hipoxemia, desconforto importante e baixa aceitação alimentar. Broncodilatador e corticoide não alteram o curso da doença.',
    'MEDIUM',
    'SBP - Diretrizes para o manejo da bronquiolite viral aguda (questão original)',
