(
    3,
    'Pneumologia Pediátrica - Bronquiolite Viral Aguda',
    'MULTIPLE_CHOICE',
    'Lactente de 5 meses com quadro típico de bronquiolite, hidratado e com saturação de 96%, será tratado em casa. Qual exame complementar é necessário de rotina?',
    'A',
    '["A) Nenhum, pois o diagnóstico é clínico", "B) Radiografia de tórax", "C) Hemograma e PCR", "D) Pesquisa viral em secreção nasal"]'::jsonb,
    'Na bronquiolite típica o diagnóstico é clínico; radiografia, hemograma e pesquisa viral não mudam a conduta e aumentam o uso indevido de antibióticos. Exames ficam para casos graves ou atípicos.',
    'MEDIUM',
    'SBP - Diretrizes para o manejo da bronquiolite viral aguda (questão original)',
    TRUE
),
(
    3,
    'Pneumologia Pediátrica - Pneumonia Adquirida na Comunidade',
    'MULTIPLE_CHOICE',
    'Lactente de 8 meses com pneumonia de evolução rápida, pneumatoceles e derrame pleural na radiografia, poucos dias após infecção de pele. Qual agente deve ser coberto prioritariamente?',
    'C',
    '["A) Mycoplasma pneumoniae", "B) Vírus sincicial respiratório", "C) Staphylococcus aureus", "D) Chlamydia trachomatis"]'::jsonb,
    'Pneumatoceles, empiema e progressão rápida, sobretudo após lesão de pele ou varicela, sugerem S. aureus, que exige cobertura antiestafilocócica (oxacilina, ou vancomicina se houver suspeita de MRSA). Micoplasma e clamídia causam quadros arrastados e pouco necrotizantes.',
    'MEDIUM',
    'Diretrizes da SBP para pneumonia adquirida na comunidade (questão original)',
    TRUE
),
(
    3,
    'Pneumologia Pediátrica - Pneumonia Adquirida na Comunidade',
    'MULTIPLE_CHOICE',
    'Criança de 3 anos com febre, tosse e taquipneia, sem tiragem subcostal, sem hipoxemia e aceitando bem a dieta, tem diagnóstico de pneumonia. Qual o tratamento recomendado?',
    'D',
    '["A) Ceftriaxona endovenosa com internação", "B) Azitromicina oral como primeira escolha", "C) Amoxicilina-clavulanato associada a claritromicina", "D) Amoxicilina oral em regime ambulatorial"]'::jsonb,
    'Na pneumonia sem sinais de gravidade em pré-escolar a amoxicilina oral é a primeira escolha, por cobrir bem o pneumococo. Internação e via venosa ficam para os casos graves; macrolídeos são indicados quando há suspeita de agente atípico, mais comum em escolares.',
    'MEDIUM',
    'SBP - Pneumonia adquirida na comunidade na infância (questão original)',
    TRUE
),
(
    3,
    'Pneumologia Pediátrica - Pneumonia Adquirida na Comunidade',
    'MULTIPLE_CHOICE',
    'Lactente de 7 semanas, afebril, com tosse em acessos e taquipneia, tem história de conjuntivite no período neonatal; o hemograma mostra eosinofilia. Qual o agente provável e o tratamento?',
    'B',
    '["A) Streptococcus agalactiae; ampicilina", "B) Chlamydia trachomatis; macrolídeo", "C) Vírus sincicial respiratório; corticoide oral", "D) Staphylococcus aureus; oxacilina"]'::jsonb,
    'A pneumonia afebril do lactente entre 1 e 3 meses, com tosse em staccato, conjuntivite prévia e eosinofilia, é típica de Chlamydia trachomatis adquirida no parto, tratada com macrolídeo (azitromicina ou eritromicina).',
    'HARD',
    'Tratado de Pediatria SBP - Pneumonias (questão original)',
    TRUE
),
(
    3,
    'Puericultura - Crescimento e Desenvolvimento',
    'MULTIPLE_CHOICE',
    'Na consulta de puericultura de um lactente de 2 meses nascido a termo e saudável, qual aquisição do desenvolvimento é esperada para a idade?',
