    '["A) Sentar sem apoio por alguns segundos", "B) Sorriso social em resposta ao rosto e à voz do examinador", "C) Pinça polegar-indicador para pegar objetos pequenos", "D) Ficar em pé com apoio nos móveis"]'::jsonb,
    'O sorriso social surge por volta dos 2 meses e é marco precoce da interação. Sentar sem apoio ocorre em torno de 6 a 8 meses, a pinça entre 9 e 12 meses e ficar em pé com apoio por volta de 9 a 10 meses.',
