    'Lactente a termo nasceu com 3,2 kg e vem crescendo de forma adequada no canal de sua curva. Qual peso aproximado se espera ao completar 12 meses?',
    'D',
    '["A) Cerca de 6,4 kg", "B) Cerca de 12,8 kg", "C) Cerca de 16 kg", "D) Cerca de 9,6 kg"]'::jsonb,
    'Como regra prática, o lactente a termo dobra o peso de nascimento por volta dos 4 a 5 meses e o triplica ao redor de 1 ano. 6,4 kg corresponde ao peso esperado próximo dos 5 meses; 12,8 kg seria quadruplicar, o que ocorre só por volta dos 2 anos.',
