(
    3,
    'Puericultura - Crescimento e Desenvolvimento',
    'MULTIPLE_CHOICE',
    'Criança de 3 anos tem IMC-para-idade entre os escores z +2 e +3 na curva da OMS adotada pela Caderneta da Criança. Qual a classificação do estado nutricional?',
    'A',
    '["A) Sobrepeso", "B) Eutrofia", "C) Risco de sobrepeso", "D) Obesidade"]'::jsonb,
    'Para menores de 5 anos, o MS (SISVAN, curvas OMS) classifica IMC-para-idade acima de +1 até +2 como risco de sobrepeso, acima de +2 até +3 como sobrepeso e acima de +3 como obesidade. Eutrofia vai de -2 a +1.',
    'MEDIUM',
    'Orientações SISVAN - Ministério da Saúde / curvas OMS (questão original)',
    TRUE
),
(
    3,
    'Puericultura - Suplementação de Ferro e Vitaminas',
    'MULTIPLE_CHOICE',
    'Pela recomendação da Sociedade Brasileira de Pediatria, como deve ser feita a suplementação de vitamina D em lactente saudável a termo no primeiro ano de vida?',
    'D',
    '["A) Somente se o lactente não estiver em aleitamento materno exclusivo", "B) Dose única de 100.000 UI ao nascer", "C) 400 UI/dia apenas nos meses de inverno", "D) 400 UI/dia a partir da primeira semana de vida até os 12 meses"]'::jsonb,
    'A SBP recomenda vitamina D 400 UI/dia da primeira semana até 12 meses (e 600 UI/dia de 12 a 24 meses), independentemente do tipo de aleitamento, pois o leite materno tem pouca vitamina D e a exposição solar é insegura como única fonte.',
