(
    3,
    'Puericultura - Suplementação de Ferro e Vitaminas',
    'MULTIPLE_CHOICE',
    'Lactente a termo, peso adequado ao nascer, em aleitamento materno exclusivo, consulta aos 3 meses. Pela SBP, qual a conduta quanto ao ferro?',
    'B',
    '["A) Não suplementar enquanto estiver em aleitamento materno exclusivo", "B) Iniciar ferro elementar 1 mg/kg/dia, mantendo até os 24 meses", "C) Iniciar ferro elementar 3 mg/kg/dia por 3 meses", "D) Solicitar ferritina e só suplementar se estiver baixa"]'::jsonb,
    'A SBP indica ferro profilático 1 mg/kg/dia de ferro elementar a partir do 3º mês até os 24 meses para o RN a termo de peso adequado, independentemente do tipo de aleitamento. Dose de 3 mg/kg/dia é para prematuros de muito baixo peso, e não se exige exame prévio.',
