    'SBP - Consenso sobre anemia ferropriva 2018 (questão original)',
    TRUE
),
(
    3,
    'Puericultura - Suplementação de Ferro e Vitaminas',
    'MULTIPLE_CHOICE',
    'Prematuro nascido com 1.300 g recebe alta da UTI neonatal. Segundo a SBP, qual o esquema profilático de ferro elementar?',
    'A',
    '["A) 3 mg/kg/dia a partir dos 30 dias de vida durante 1 ano e, depois, 1 mg/kg/dia até os 24 meses", "B) 1 mg/kg/dia a partir do 3º mês até os 24 meses", "C) 2 mg/kg/dia a partir dos 6 meses até os 12 meses", "D) Ferro apenas se houver anemia confirmada na alta"]'::jsonb,
    'Para prematuros a SBP escalona a dose pelo peso ao nascer: 2 mg/kg/dia entre 1.500 e 2.500 g, 3 mg/kg/dia entre 1.000 e 1.500 g e 4 mg/kg/dia abaixo de 1.000 g, a partir de 30 dias por 1 ano, seguida de 1 mg/kg/dia até 24 meses. O esquema de 1 mg/kg/dia desde o 3º mês é o do RN a termo.',
    'HARD',
    'SBP - Consenso sobre anemia ferropriva 2018 (questão original)',
    TRUE
);

