    'Puérpera com sangramento após parto vaginal tem frequência cardíaca de 120 bpm e pressão sistólica de 85 mmHg. Como interpretar o índice de choque?',
    'B',
    '["A) Cerca de 0,7, sem sinal de gravidade", "B) Cerca de 1,4, indicando quadro grave com alta probabilidade de necessidade de transfusão", "C) Cerca de 0,9, indicando apenas observação", "D) Cerca de 1,4, indicando sangramento leve"]'::jsonb,
    'Índice de choque = frequência cardíaca dividida pela pressão sistólica: 120 / 85 = 1,4. Valores a partir de 0,9 já sinalizam perda importante, e a partir de 1,4 indicam gravidade, com provável necessidade de transfusão e intervenção imediata.',
    'HARD',
    'Recomendações OPAS/MS para hemorragia pós-parto (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Hemorragias da Primeira Metade',
    'MULTIPLE_CHOICE',
    'Qual é a localização mais frequente da gravidez ectópica?',
    'B',
    '["A) Ovário", "B) Porção ampular da tuba uterina", "C) Colo uterino", "D) Cavidade abdominal"]'::jsonb,
    'Mais de 90% das gestações ectópicas são tubárias, e a ampola é o segmento mais acometido. Gestações ovarianas, cervicais e abdominais são raras.',
    'EASY',
    'Protocolo FEBRASGO de gravidez ectópica (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Hemorragias da Primeira Metade',
    'MULTIPLE_CHOICE',
    'Gestante de 8 semanas com sangramento vaginal moderado e cólicas. O colo está aberto, com restos ovulares no canal, e a ultrassonografia mostra material heterogêneo na cavidade, sem saco gestacional íntegro. Qual é o diagnóstico?',
    'D',
    '["A) Ameaça de abortamento", "B) Abortamento retido", "C) Abortamento completo", "D) Abortamento incompleto"]'::jsonb,
    'Colo aberto com eliminação parcial do conteúdo e restos na cavidade caracteriza abortamento incompleto. Na ameaça o colo está fechado e o embrião vivo; no retido o colo está fechado e o embrião sem vitalidade; no completo a cavidade está vazia.',
    'MEDIUM',
    'Manual de Gestação de Alto Risco do MS (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Hemorragias da Primeira Metade',
    'MULTIPLE_CHOICE',
    'Paciente com atraso menstrual de 10 semanas, sangramento vaginal, útero maior que o esperado, beta-hCG muito elevado e ultrassonografia com imagem em ''flocos de neve'', sem embrião. Após o esvaziamento uterino, qual seguimento é essencial?',
    'A',
    '["A) Dosagens seriadas de beta-hCG até a negativação e por um período após", "B) Nenhum, pois o esvaziamento é sempre curativo", "C) Histerectomia profilática em todas as pacientes", "D) Quimioterapia adjuvante em todas as pacientes"]'::jsonb,
    'O quadro é de mola hidatiforme. Após o esvaziamento por aspiração, o beta-hCG seriado detecta precocemente a neoplasia trofoblástica gestacional; a quimioterapia só é indicada se o hormônio persistir ou voltar a subir.',
    'MEDIUM',
    'Protocolo FEBRASGO de doença trofoblástica gestacional (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Hemorragias da Primeira Metade',
    'MULTIPLE_CHOICE',
    'Paciente hemodinamicamente estável, com gravidez ectópica tubária íntegra de 2,5 cm, sem batimentos cardíacos embrionários, beta-hCG de 2.000 mUI/mL e desejo de gestar. Qual conduta é adequada?',
    'B',
    '["A) Laparotomia com salpingectomia de urgência", "B) Metotrexato sistêmico com acompanhamento do beta-hCG", "C) Histeroscopia para retirar o saco gestacional", "D) Curetagem uterina"]'::jsonb,
    'Estabilidade hemodinâmica, massa pequena e íntegra, ausência de atividade cardíaca e beta-hCG abaixo de cerca de 5.000 mUI/mL permitem tratamento clínico com metotrexato, preservando a tuba. Cirurgia fica para instabilidade, rotura ou falha do tratamento clínico.',
    'HARD',
    'Protocolo FEBRASGO de gravidez ectópica (questão original)',
