(
    4,
    'Obstetrícia - Hemorragias da Segunda Metade',
    'MULTIPLE_CHOICE',
    'Gestante de 33 semanas apresenta sangramento vaginal vermelho vivo, indolor, de início súbito, com útero de tônus normal. Qual procedimento deve ser evitado até que a localização da placenta seja conhecida?',
    'C',
    '["A) Ultrassonografia transabdominal", "B) Cardiotocografia", "C) Toque vaginal", "D) Hemograma"]'::jsonb,
