(
    4,
    'Obstetrícia - Hemorragias da Segunda Metade',
    'MULTIPLE_CHOICE',
    'Parturiente com duas cesáreas prévias, em trabalho de parto prolongado, apresenta anel fundo-segmentar que sobe em direção à cicatriz umbilical (sinal de Bandl) e ligamentos redondos tensos (sinal de Frommel). O que esses sinais indicam?',
    'B',
    '["A) Descolamento prematuro de placenta", "B) Iminência de rotura uterina", "C) Distocia de ombro", "D) Placenta acreta"]'::jsonb,
    'Os sinais de Bandl e Frommel caracterizam a iminência de rotura uterina, típica do trabalho de parto obstruído e mais provável com cicatriz uterina prévia. A conduta é a resolução imediata da gestação por cesárea.',
    'HARD',
    'Manual de Gestação de Alto Risco do MS (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Infecções na Gestação',
    'MULTIPLE_CHOICE',
    'Gestante com sífilis foi tratada com penicilina benzatina. Pelo PCDT do Ministério da Saúde, qual condição é necessária para que o tratamento materno seja considerado adequado na avaliação do recém-nascido?',
    'B',
    '["A) Tratamento com ceftriaxona em qualquer momento da gestação", "B) Esquema completo de penicilina benzatina para o estágio clínico, iniciado até 30 dias antes do parto", "C) Tratamento obrigatório do parceiro sexual na mesma data", "D) Negativação do VDRL antes do parto"]'::jsonb,
    'É adequado o tratamento com penicilina benzatina, em esquema compatível com o estágio, iniciado até 30 dias antes do parto e documentado. O tratamento do parceiro continua recomendado, mas deixou de ser critério de adequação; não se exige negativação do VDRL, e outros antibióticos não valem como tratamento adequado.',
    'MEDIUM',
    'PCDT de Transmissão Vertical de HIV, Sífilis e Hepatites Virais, MS (questão original)',
