    'A',
    '["A) Vacina contra hepatite B e imunoglobulina anti-hepatite B, de preferência nas primeiras 12 horas de vida", "B) Apenas a vacina, aos 2 meses de idade", "C) Suspender o aleitamento materno", "D) Apenas a imunoglobulina, sem vacina"]'::jsonb,
    'O filho de mãe HBsAg reagente deve receber a vacina e a imunoglobulina específica logo após o nascimento, de preferência nas primeiras 12 horas. Com essa profilaxia o aleitamento materno é permitido.',
