(
    4,
    'Obstetrícia - Infecções na Gestação',
    'MULTIPLE_CHOICE',
    'Gestante vivendo com HIV, em TARV, chega com 38 semanas em trabalho de parto. A carga viral colhida com 35 semanas foi indetectável. Qual é a conduta quanto à via de parto e ao AZT intravenoso?',
    'D',
    '["A) Cesárea obrigatória e AZT intravenoso", "B) Parto vaginal com AZT intravenoso obrigatório", "C) Cesárea eletiva sem AZT", "D) Via de parto por indicação obstétrica, sem necessidade de AZT intravenoso, mantendo a TARV oral"]'::jsonb,
    'Com carga viral indetectável a partir de 34 semanas, a via de parto segue a indicação obstétrica e o AZT intravenoso não é necessário. Ele é indicado sobretudo quando a carga viral é desconhecida ou de 1.000 cópias/mL ou mais.',
    'HARD',
    'PCDT de Transmissão Vertical de HIV, Sífilis e Hepatites Virais, MS (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Infecções na Gestação',
    'MULTIPLE_CHOICE',
    'Gestante de 14 semanas, antes suscetível, apresenta soroconversão para toxoplasmose (IgM e IgG reagentes, com IgG não reagente em exame de 8 semanas). Enquanto se investiga a infecção fetal, qual medicamento reduz a transmissão ao feto?',
    'B',
    '["A) Sulfadiazina, pirimetamina e ácido folínico", "B) Espiramicina", "C) Azitromicina", "D) Clindamicina"]'::jsonb,
    'Na infecção materna aguda sem confirmação de infecção fetal usa-se espiramicina, que se concentra na placenta e reduz a transmissão. Sulfadiazina, pirimetamina e ácido folínico ficam para a infecção fetal confirmada ou muito provável, e a pirimetamina é evitada no primeiro trimestre.',
    'HARD',
    'Manual de Gestação de Alto Risco do MS (questão original)',
