    '["A) Alba, serosa e rubra", "B) Rubra, serosa e alba", "C) Serosa, rubra e alba", "D) Rubra, alba e serosa"]'::jsonb,
    'Nos primeiros dias os lóquios são vermelhos (rubra); depois ficam acastanhados ou serosos (fusca ou serosa) e, por fim, esbranquiçados (alba) ao longo das semanas seguintes.',
