(
    4,
    'Obstetrícia - Puerpério',
    'MULTIPLE_CHOICE',
    'Puérpera de 10 dias, amamentando, tem área quente, dolorosa e avermelhada na mama direita, febre de 38,5 °C e mal-estar. Qual orientação é correta?',
    'C',
    '["A) Suspender a amamentação até a cura", "B) Suspender a lactação com cabergolina", "C) Manter a amamentação e o esvaziamento da mama, associando antibiótico ativo contra Staphylococcus aureus", "D) Usar apenas compressas frias, sem antibiótico"]'::jsonb,
    'Na mastite puerperal o esvaziamento eficaz da mama faz parte do tratamento e a amamentação deve continuar. Com febre e sinais sistêmicos indica-se antibiótico com cobertura para S. aureus, o principal agente.',
    'MEDIUM',
    'Manual de Aleitamento Materno do MS (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Puerpério',
    'MULTIPLE_CHOICE',
    'Puérpera de 5 dias relata choro fácil, irritabilidade e oscilação do humor desde o terceiro dia, sem prejuízo para cuidar do bebê e sem ideação suicida. Qual é a hipótese e a conduta?',
    'C',
    '["A) Depressão pós-parto; iniciar antidepressivo imediatamente", "B) Psicose puerperal; internação", "C) Tristeza puerperal (baby blues); acolhimento, orientação e reavaliação se os sintomas passarem de duas semanas", "D) Transtorno bipolar; iniciar estabilizador do humor"]'::jsonb,
    'Sintomas leves e transitórios que começam nos primeiros dias e regridem em até duas semanas caracterizam a tristeza puerperal. Persistência além desse prazo ou prejuízo funcional sugere depressão pós-parto e exige avaliação.',
    'MEDIUM',
    'Manual de Gestação de Alto Risco do MS (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Síndromes Hipertensivas',
    'MULTIPLE_CHOICE',
    'Gestante de 32 semanas, previamente normotensa, apresenta PA de 150x100 mmHg em duas medidas e relação proteína/creatinina urinária de 0,5. Qual é o diagnóstico?',
    'C',
    '["A) Hipertensão arterial crônica", "B) Hipertensão gestacional", "C) Pré-eclâmpsia", "D) Eclâmpsia"]'::jsonb,
    'Hipertensão surgida após 20 semanas associada a proteinúria significativa (relação proteína/creatinina de 0,3 ou mais) define pré-eclâmpsia. Sem proteinúria nem lesão de órgão-alvo seria hipertensão gestacional; eclâmpsia exige convulsão.',
    'EASY',
    'Protocolo FEBRASGO de pré-eclâmpsia (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Síndromes Hipertensivas',
    'MULTIPLE_CHOICE',
    'Durante a infusão de sulfato de magnésio por pré-eclâmpsia com sinais de gravidade, a enfermagem nota reflexos patelares abolidos e frequência respiratória de 10 irpm. Qual é a conduta imediata?',
    'B',
    '["A) Aumentar a dose de manutenção do sulfato de magnésio", "B) Suspender a infusão e administrar gluconato de cálcio intravenoso", "C) Associar diazepam intravenoso", "D) Manter a infusão e dosar o magnésio sérico no dia seguinte"]'::jsonb,
    'Reflexo patelar abolido e depressão respiratória indicam intoxicação por magnésio: suspende-se a infusão e administra-se gluconato de cálcio, o antídoto. Reflexos, diurese e frequência respiratória devem ser monitorizados durante todo o uso.',
    'MEDIUM',
    'Protocolo FEBRASGO de pré-eclâmpsia (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Síndromes Hipertensivas',
    'MULTIPLE_CHOICE',
    'Mulher com hipertensão arterial crônica, em uso de enalapril, descobre gestação de 7 semanas. Qual é a orientação adequada?',
    'D',
    '["A) Manter o enalapril, que é seguro em toda a gestação", "B) Suspender todo anti-hipertensivo até o fim do primeiro trimestre", "C) Associar losartana para melhorar o controle pressórico", "D) Trocar o enalapril por anti-hipertensivo compatível com a gestação, como metildopa ou nifedipina"]'::jsonb,
    'Inibidores da ECA e bloqueadores do receptor de angiotensina são contraindicados na gestação pelo risco de lesão renal fetal, oligoidrâmnio e malformações. A troca deve ser feita assim que a gestação é confirmada, por fármacos como metildopa, nifedipina ou hidralazina.',
    'MEDIUM',
    'Diretriz Brasileira de Hipertensão Arterial 2020 (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Síndromes Hipertensivas',
    'MULTIPLE_CHOICE',
    'Gestante de 34 semanas com pré-eclâmpsia apresenta dor em hipocôndrio direito, plaquetas de 85.000/mm³, LDH de 900 U/L, bilirrubina indireta elevada e AST de 210 U/L. Qual é o diagnóstico mais provável?',
    'A',
    '["A) Síndrome HELLP", "B) Esteatose hepática aguda da gestação", "C) Colestase intra-hepática da gestação", "D) Hepatite viral aguda"]'::jsonb,
    'Hemólise (LDH e bilirrubina indireta elevadas), enzimas hepáticas aumentadas e plaquetopenia num quadro de pré-eclâmpsia caracterizam a síndrome HELLP, forma grave que em geral indica estabilização materna e resolução da gestação.',
    'HARD',
    'Protocolo FEBRASGO de pré-eclâmpsia (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Síndromes Hipertensivas',
    'MULTIPLE_CHOICE',
    'Gestante de 11 semanas, com pré-eclâmpsia grave na gestação anterior, pergunta se há algo que reduza o risco de recorrência. Qual medida tem benefício comprovado?',
    'C',
    '["A) Repouso absoluto a partir do segundo trimestre", "B) Dieta sem sal durante toda a gestação", "C) Ácido acetilsalicílico em baixa dose, iniciado de preferência antes de 16 semanas", "D) Diurético tiazídico profilático desde o primeiro trimestre"]'::jsonb,
    'Em gestantes de alto risco para pré-eclâmpsia, o AAS em baixa dose iniciado entre 12 e 16 semanas reduz a incidência da doença (associado ao cálcio quando a ingestão é baixa). Repouso, restrição de sal e diuréticos não previnem pré-eclâmpsia.',
    'HARD',
    'Protocolo FEBRASGO de pré-eclâmpsia (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Trabalho de Parto e Parto',
    'MULTIPLE_CHOICE',
    'No exame obstétrico, a apresentação cefálica está no plano zero de De Lee. O que isso significa?',
    'A',
    '["A) O polo cefálico está na altura das espinhas isquiáticas", "B) O feto está totalmente acima da pelve, sem contato com o estreito superior", "C) A cabeça fetal já está aflorando na vulva", "D) O colo uterino está com 10 cm de dilatação"]'::jsonb,
    'Os planos de De Lee medem, em centímetros, a altura da apresentação em relação às espinhas isquiáticas. O plano zero corresponde à apresentação na altura delas, o que indica que a cabeça está insinuada.',
    'EASY',
    'Diretriz Nacional de Assistência ao Parto Normal, MS (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Trabalho de Parto e Parto',
    'MULTIPLE_CHOICE',
    'Qual é a recomendação atual sobre a episiotomia na assistência ao parto vaginal?',
    'D',
    '["A) Deve ser feita de rotina em todas as primíparas", "B) É obrigatória em todo parto com analgesia", "C) Deve ser sempre mediana para reduzir a dor", "D) Não deve ser feita de rotina; fica restrita a situações específicas"]'::jsonb,
    'As diretrizes brasileiras e da OMS não recomendam episiotomia de rotina: ela não reduz lacerações graves e aumenta dor e complicações. O uso fica restrito a indicações individualizadas.',
    'EASY',
    'Diretriz Nacional de Assistência ao Parto Normal, MS (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Trabalho de Parto e Parto',
    'MULTIPLE_CHOICE',
    'Na cardiotocografia de uma parturiente a termo surgem, repetidamente, desacelerações que começam após o pico da contração e só retornam à linha de base depois do fim dela. O que esse padrão sugere?',
    'C',
    '["A) Compressão do polo cefálico, sem significado patológico", "B) Compressão do cordão umbilical", "C) Insuficiência uteroplacentária com hipoxemia fetal", "D) Movimentação fetal normal"]'::jsonb,
    'Desacelerações tardias (DIP II), defasadas em relação à contração, refletem queda da oxigenação fetal por insuficiência uteroplacentária. Desacelerações precoces se associam à compressão cefálica e as variáveis à compressão do cordão.',
    'MEDIUM',
    'Protocolo FEBRASGO de vitalidade fetal intraparto (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Trabalho de Parto e Parto',
    'MULTIPLE_CHOICE',
    'Qual situação é indicação absoluta de cesárea?',
    'A',
    '["A) Placenta prévia centro-total", "B) Gestante com uma cesárea anterior", "C) Apresentação pélvica em multípara", "D) Feto com peso estimado de 3.800 g"]'::jsonb,
    'Na placenta prévia que recobre totalmente o orifício interno do colo o parto vaginal é impossível sem hemorragia grave. Uma cesárea prévia, a apresentação pélvica e um peso fetal normal não impedem, por si, a tentativa de parto vaginal.',
    'MEDIUM',
    'Diretriz Nacional de Atenção à Gestante: operação cesariana, MS (questão original)',
    TRUE
),
(
    4,
    'Obstetrícia - Trabalho de Parto e Parto',
    'MULTIPLE_CHOICE',
    'Gestante a termo com uma cesárea anterior e colo desfavorável (índice de Bishop 3) tem indicação de indução do parto. Qual método de preparo cervical deve ser evitado?',
    'B',
    '["A) Sonda de Foley transcervical", "B) Misoprostol", "C) Descolamento digital das membranas", "D) Ocitocina após o amadurecimento mecânico do colo"]'::jsonb,
    'Prostaglandinas como o misoprostol aumentam o risco de rotura uterina em mulheres com cicatriz uterina prévia no terceiro trimestre e por isso são evitadas. Métodos mecânicos, como a sonda de Foley, são a opção para amadurecer o colo.',
    'HARD',
    'Diretriz Nacional de Assistência ao Parto Normal, MS (questão original)',
    TRUE
);

