VALUES
(
    5,
    'Atenção Primária - Atributos e PNAB',
    'MULTIPLE_CHOICE',
    'Dona Lúcia é acompanhada pela mesma equipe de Saúde da Família há 12 anos. A médica conhece sua história, sua família e suas preferências, e ela procura a equipe para quase todos os problemas. Qual atributo da APS, segundo Starfield, está mais evidente?',
    'A',
    '["A) Longitudinalidade", "B) Coordenação do cuidado", "C) Competência cultural", "D) Orientação comunitária"]'::jsonb,
    'Longitudinalidade é a existência de uma fonte regular de cuidado ao longo do tempo, com vínculo entre a pessoa e a equipe. Coordenação refere-se a integrar informações e cuidados prestados em outros pontos da rede.',
    'EASY',
    'Starfield, Atenção Primária (2002) (questão original)',
    TRUE
),
(
    5,
    'Atenção Primária - Atributos e PNAB',
    'MULTIPLE_CHOICE',
    'Segundo Barbara Starfield, a APS possui atributos essenciais e atributos derivados. Qual dos itens abaixo é um atributo derivado?',
    'B',
    '["A) Longitudinalidade", "B) Orientação comunitária", "C) Coordenação do cuidado", "D) Acesso de primeiro contato"]'::jsonb,
    'Os atributos essenciais são acesso de primeiro contato, longitudinalidade, integralidade e coordenação. Os derivados são orientação familiar, orientação comunitária e competência cultural.',
    'MEDIUM',
    'Starfield, Atenção Primária (2002) (questão original)',
    TRUE
),
(
    5,
    'Atenção Primária - Atributos e PNAB',
    'MULTIPLE_CHOICE',
    'Em uma UBS, as consultas só são marcadas uma manhã por mês e não há acolhimento à demanda espontânea. Muitos moradores passam a procurar diretamente o pronto-socorro para problemas simples. Qual atributo da APS está mais comprometido?',
    'B',
    '["A) Longitudinalidade", "B) Acesso de primeiro contato", "C) Orientação familiar", "D) Competência cultural"]'::jsonb,
    'Acesso de primeiro contato significa que a APS é a porta de entrada acessível e utilizada a cada novo problema. Barreiras de agenda e ausência de acolhimento empurram a população para outros serviços.',
    'MEDIUM',
    'Starfield (2002) / PNAB 2017 (questão original)',
    TRUE
),
(
    5,
    'Atenção Primária - Atributos e PNAB',
    'MULTIPLE_CHOICE',
    'Um gestor municipal quer implantar uma equipe de apoio multiprofissional (fisioterapeuta, nutricionista, psicólogo) integrada às equipes de Saúde da Família. Pela normativa federal vigente desde 2023, qual é a modalidade a ser adotada?',
    'A',
    '["A) Equipes Multiprofissionais na APS (eMulti), instituídas pela Portaria GM/MS 635/2023", "B) Núcleo Ampliado de Saúde da Família (NASF-AB), mantido como modelo vigente com custeio próprio", "C) Centro de Atenção Psicossocial (CAPS), que assume o apoio matricial de todas as especialidades", "D) Equipe de Consultório na Rua, responsável pelo apoio multiprofissional às eSF"]'::jsonb,
    'A Portaria GM/MS 635/2023 instituiu as eMulti, que passaram a ocupar o papel de apoio multiprofissional antes exercido pelo NASF-AB, cujo custeio federal específico havia sido extinto. CAPS e Consultório na Rua têm outras finalidades.',
    'HARD',
    'Portaria GM/MS 635/2023 (questão original)',
    TRUE
),
(
    5,
    'Atenção Primária - Método Clínico Centrado na Pessoa',
    'MULTIPLE_CHOICE',
    'Qual dos itens abaixo é um dos componentes do Método Clínico Centrado na Pessoa, na versão atual de Stewart e colaboradores?',
    'D',
    '["A) Solicitar uma bateria ampla de exames antes de definir a conduta", "B) Restringir a consulta à queixa principal para ganhar tempo", "C) Definir a conduta pelo médico e comunicá-la de forma diretiva", "D) Elaborar um plano conjunto de manejo dos problemas"]'::jsonb,
    'Os quatro componentes atuais são: explorar a saúde, a doença e a experiência da doença; entender a pessoa como um todo; elaborar um plano conjunto de manejo; e intensificar a relação médico-pessoa.',
    'EASY',
    'Stewart et al., Medicina Centrada na Pessoa, 3ª ed. (questão original)',
    TRUE
),
(
    5,
    'Atenção Primária - Método Clínico Centrado na Pessoa',
    'MULTIPLE_CHOICE',
    'Durante a consulta por tontura, a paciente diz: ''Acho que isso começou por causa do remédio de pressão que o senhor trocou''. No método clínico centrado na pessoa (SIFE), essa fala corresponde principalmente a qual dimensão da experiência da doença?',
    'C',
    '["A) Sentimentos em relação ao problema", "B) Impacto na funcionalidade", "C) Ideias sobre a causa do problema", "D) Expectativas em relação à consulta"]'::jsonb,
    'A explicação que a pessoa dá para o que está sentindo é a dimensão Ideias. Medos e preocupações são Sentimentos; limitações na rotina são Funcionalidade; o que ela espera do médico são Expectativas.',
    'MEDIUM',
    'Stewart et al., Medicina Centrada na Pessoa (questão original)',
    TRUE
),
(
    5,
    'Atenção Primária - Método Clínico Centrado na Pessoa',
    'MULTIPLE_CHOICE',
    'Homem de 54 anos com diabetes mal controlado recusa iniciar insulina, dizendo que ''quem toma insulina fica cego''. Pelo método clínico centrado na pessoa, qual é a abordagem mais adequada?',
    'C',
    '["A) Reforçar os riscos de complicações até que ele aceite a prescrição", "B) Registrar a recusa e manter o mesmo esquema oral sem nova discussão", "C) Explorar o significado desse medo e buscar acordo sobre o problema, as metas e os papéis de cada um no tratamento", "D) Encaminhar ao endocrinologista, já que a recusa indica falha do vínculo na APS"]'::jsonb,
    'O plano conjunto exige terreno comum sobre o problema, as metas e os papéis. Explorar a crença (muitas vezes ligada a experiências de familiares) permite corrigir a ideia e negociar, em vez de impor ou desistir.',
    'HARD',
    'Stewart et al., Medicina Centrada na Pessoa (questão original)',
