),
(
    5,
    'Atenção Primária - Princípios do SUS',
    'MULTIPLE_CHOICE',
    'Uma equipe da UBS organiza, para a mesma pessoa com DPOC, vacinação, cessação do tabagismo, tratamento das exacerbações e encaminhamento à reabilitação pulmonar. Qual princípio do SUS essa articulação expressa?',
    'B',
    '["A) Universalidade", "B) Integralidade", "C) Equidade", "D) Regionalização"]'::jsonb,
    'Integralidade é o conjunto articulado de ações de promoção, prevenção, tratamento e reabilitação, individuais e coletivas, em todos os níveis do sistema. Universalidade trata do acesso de todos; equidade, de priorizar quem mais precisa.',
    'EASY',
    'Lei 8.080/1990, art. 7º (questão original)',
    TRUE
),
(
    5,
    'Atenção Primária - Princípios do SUS',
    'MULTIPLE_CHOICE',
    'Sobre os Conselhos de Saúde, instâncias de participação da comunidade no SUS definidas pela Lei 8.142/1990, é correto afirmar que:',
    'D',
    '["A) Têm caráter consultivo e se reúnem a cada quatro anos para propor diretrizes da política de saúde", "B) São compostos exclusivamente por gestores e profissionais de saúde, cabendo aos usuários as conferências", "C) Têm a metade das vagas destinada aos prestadores privados contratados pelo SUS", "D) Têm caráter permanente e deliberativo, com representação dos usuários paritária em relação ao conjunto dos demais segmentos"]'::jsonb,
    'Pela Lei 8.142/1990, o Conselho de Saúde é permanente e deliberativo, e os usuários ocupam 50% das vagas. A reunião a cada quatro anos para propor diretrizes descreve a Conferência de Saúde, não o conselho.',
    'MEDIUM',
    'Lei 8.142/1990 (questão original)',
    TRUE
),
(
    5,
    'Atenção Primária - Princípios do SUS',
    'MULTIPLE_CHOICE',
    'Entre os itens abaixo, qual é classicamente descrito como diretriz organizativa do SUS, e não como princípio doutrinário?',
    'D',
    '["A) Universalidade de acesso aos serviços de saúde", "B) Equidade na distribuição dos recursos", "C) Integralidade da assistência", "D) Descentralização político-administrativa, com direção única em cada esfera de governo"]'::jsonb,
    'Universalidade, equidade e integralidade são os princípios doutrinários. Descentralização com direção única em cada esfera, regionalização, hierarquização e participação da comunidade são diretrizes organizativas (CF/88, art. 198, e Lei 8.080).',
    'MEDIUM',
    'Constituição Federal art. 198 / Lei 8.080/1990 (questão original)',
