(
    5,
    'Bioética e Saúde Pública - Prevenção Quaternária',
    'MULTIPLE_CHOICE',
    'A aferição da pressão arterial em um adulto assintomático para identificar hipertensão ainda não diagnosticada corresponde a qual nível de prevenção?',
    'D',
    '["A) Prevenção primária", "B) Prevenção terciária", "C) Prevenção quaternária", "D) Prevenção secundária"]'::jsonb,
    'Rastreamento busca detectar doença já presente em fase pré-clínica, o que caracteriza prevenção secundária. A primária evita que a doença surja (ex.: vacina); a terciária reduz sequelas da doença estabelecida.',
    'EASY',
    'Leavell e Clark / Cadernos de AB n. 29 (questão original)',
    TRUE
),
(
    5,
    'Bioética e Saúde Pública - Prevenção Quaternária',
    'MULTIPLE_CHOICE',
    'Homem de 45 anos, saudável e ansioso, pede ''check-up completo'' com marcadores tumorais (CEA, CA 19-9) e tomografia de corpo inteiro. Qual conduta reflete a prevenção quaternária?',
    'A',
    '["A) Explicar a falta de benefício e os riscos de falsos positivos e achados incidentais, oferecendo as medidas preventivas com evidência", "B) Solicitar todos os exames para tranquilizar o paciente e evitar conflito", "C) Solicitar apenas os marcadores tumorais, que são exames de baixo risco", "D) Encaminhar ao oncologista para decidir quais exames de rastreamento fazer"]'::jsonb,
    'Prevenção quaternária protege a pessoa de intervenções desnecessárias. Marcadores tumorais e imagem de corpo inteiro em assintomáticos geram falsos positivos, cascatas de exames e danos sem benefício comprovado.',
    'MEDIUM',
    'Jamoulle / WONCA / SBMFC (questão original)',
    TRUE
),
(
    5,
    'Bioética e Saúde Pública - Prevenção Quaternária',
    'MULTIPLE_CHOICE',
    'No modelo de Jamoulle, os níveis de prevenção surgem do cruzamento entre a perspectiva do paciente (sente-se doente ou não) e a do médico (identifica doença ou não). Em qual situação se insere a prevenção quaternária?',
    'A',
    '["A) O paciente se sente doente, mas o médico não identifica doença", "B) O paciente não se sente doente e o médico não identifica doença", "C) O paciente não se sente doente, mas o médico identifica doença", "D) O paciente se sente doente e o médico identifica doença"]'::jsonb,
    'Na matriz de Jamoulle: ninguém vê doença é prevenção primária; só o médico vê, secundária; ambos veem, terciária; só o paciente se sente doente, quaternária, em que o risco é a medicalização excessiva.',
    'HARD',
    'Jamoulle, WONCA 1986/2015 (questão original)',
    TRUE
),
(
    5,
    'Condições Crônicas na APS - Hipertensão e Diabetes',
    'MULTIPLE_CHOICE',
    'Adulta de 47 anos, assintomática, apresenta glicemia de jejum de 128 mg/dL e, em outra coleta duas semanas depois, 134 mg/dL. Qual é a interpretação correta?',
    'B',
    '["A) Pré-diabetes, devendo repetir o exame em um ano", "B) Diagnóstico confirmado de diabetes mellitus", "C) Resultado inconclusivo, exigindo obrigatoriamente o TOTG", "D) Normalidade, pois o diagnóstico exige glicemia acima de 200 mg/dL"]'::jsonb,
    'Glicemia de jejum de 126 mg/dL ou mais, confirmada em segunda amostra, estabelece o diagnóstico de diabetes. O ponto de corte de 200 mg/dL vale para glicemia ao acaso com sintomas ou para o TOTG de 2 horas.',
    'EASY',
    'Diretriz da Sociedade Brasileira de Diabetes (questão original)',
    TRUE
),
(
    5,
    'Condições Crônicas na APS - Hipertensão e Diabetes',
    'MULTIPLE_CHOICE',
    'Homem de 50 anos, sem diabetes, doença renal ou cardiovascular, tem hipertensão estágio 1 confirmada (média de 146/92 mmHg) e risco cardiovascular baixo. Pela Diretriz Brasileira de Hipertensão Arterial 2020, qual é a conduta inicial na UBS?',
    'A',
    '["A) Mudanças no estilo de vida por cerca de 3 meses e, se a PA não for controlada, iniciar medicamento", "B) Iniciar terapia dupla em comprimido único, independentemente do risco", "C) Não tratar, pois o estágio 1 não aumenta o risco cardiovascular", "D) Encaminhar ao cardiologista para iniciar o tratamento"]'::jsonb,
    'Na hipertensão estágio 1 com risco cardiovascular baixo, a diretriz admite começar só com medidas não farmacológicas (sal, dieta, atividade física, peso e álcool) por cerca de 3 meses e, sem controle, iniciar monoterapia. A terapia dupla é preferida nos estágios 2 e 3 ou no risco alto, e o acompanhamento é da própria APS.',
    'MEDIUM',
    'Diretriz Brasileira de Hipertensão Arterial 2020 (questão original)',
    TRUE
),
(
    5,
    'Condições Crônicas na APS - Hipertensão e Diabetes',
    'MULTIPLE_CHOICE',
    'Na consulta anual de uma pessoa com diabetes acompanhada pela ESF, qual instrumento é usado para identificar a perda da sensibilidade protetora dos pés?',
    'A',
    '["A) Monofilamento de 10 gramas", "B) Diapasão de 512 Hz isoladamente", "C) Martelo de reflexos para avaliar o reflexo patelar", "D) Índice tornozelo-braquial com Doppler"]'::jsonb,
    'O monofilamento de 10 g (Semmes-Weinstein) avalia a sensibilidade protetora plantar e identifica pés em risco de ulceração. O índice tornozelo-braquial avalia doença arterial periférica, não neuropatia.',
    'MEDIUM',
    'Cadernos de AB n. 36 - Diabetes / SBD (questão original)',
