(
    5,
    'Condições Crônicas na APS - Hipertensão e Diabetes',
    'MULTIPLE_CHOICE',
    'Homem de 63 anos com diabetes tipo 2 e insuficiência cardíaca com fração de ejeção reduzida usa metformina, com HbA1c de 7,2%. Qual classe deve ser associada, considerando o benefício cardiovascular e renal?',
    'D',
    '["A) Sulfonilureia", "B) Pioglitazona", "C) Insulina NPH ao deitar", "D) Inibidor de SGLT2"]'::jsonb,
    'Em pessoas com diabetes tipo 2 e insuficiência cardíaca, os inibidores de SGLT2 reduzem hospitalização por IC e são indicados independentemente da HbA1c. A pioglitazona causa retenção hídrica e é contraindicada na IC.',
