(
    5,
    'Epidemiologia Clínica - Testes Diagnósticos',
    'MULTIPLE_CHOICE',
    'O médico de família quer um exame para confirmar um diagnóstico já suspeitado, de modo que um resultado positivo praticamente não seja falso. Qual propriedade deve ser priorizada?',
    'C',
    '["A) Alta sensibilidade", "B) Baixo valor preditivo negativo", "C) Alta especificidade", "D) Baixa razão de verossimilhança positiva"]'::jsonb,
    'Testes muito específicos têm poucos falsos positivos, então um resultado positivo ajuda a confirmar a doença. Alta sensibilidade é preferida para triagem e para descartar doença quando o resultado é negativo.',
    'EASY',
    'Fletcher, Epidemiologia Clínica (questão original)',
    TRUE
),
(
    5,
    'Epidemiologia Clínica - Testes Diagnósticos',
    'MULTIPLE_CHOICE',
    'Um teste rápido com sensibilidade e especificidade fixas, validado em um ambulatório especializado, passa a ser usado na população geral, onde a prevalência da doença é bem menor. O que se espera?',
    'B',
    '["A) Queda da sensibilidade e da especificidade do teste", "B) Queda do valor preditivo positivo e aumento do valor preditivo negativo", "C) Aumento do valor preditivo positivo e queda do negativo", "D) Nenhuma mudança nos valores preditivos, pois dependem só do teste"]'::jsonb,
    'Sensibilidade e especificidade são propriedades do teste e não mudam com a prevalência. Os valores preditivos dependem dela: com prevalência menor, há mais falsos positivos entre os positivos, e o VPP cai.',
    'MEDIUM',
    'Fletcher, Epidemiologia Clínica (questão original)',
