(
    5,
    'Epidemiologia Clínica - Testes Diagnósticos',
    'MULTIPLE_CHOICE',
    'Um teste foi aplicado a 100 pessoas com a doença (90 positivos) e a 200 sem a doença (180 negativos). Qual é o valor preditivo positivo aproximado nessa amostra?',
    'A',
    '["A) 82%", "B) 90%", "C) 95%", "D) 45%"]'::jsonb,
    'Há 90 verdadeiros positivos e 20 falsos positivos (200 menos 180). VPP = 90 / (90 + 20) = 82%. O valor de 90% é a sensibilidade (e também a especificidade), e 95% é o valor preditivo negativo (180/190).',
    'HARD',
    'Fletcher, Epidemiologia Clínica (questão original)',
