    'Um teste diagnóstico tem sensibilidade de 80% e especificidade de 90%. Qual é sua razão de verossimilhança positiva?',
    'B',
    '["A) 0,22", "B) 8", "C) 1,8", "D) 0,89"]'::jsonb,
    'RV positiva = sensibilidade / (1 - especificidade) = 0,8 / 0,1 = 8. O valor 0,22 é a RV negativa, calculada por (1 - sensibilidade) / especificidade = 0,2 / 0,9.',
