    'D',
    '["A) Prevalência pontual", "B) Letalidade", "C) Prevalência de período", "D) Incidência"]'::jsonb,
    'Incidência mede casos novos em uma população em risco durante um período. Prevalência inclui todos os casos existentes (novos e antigos); letalidade é a proporção de óbitos entre os doentes.',
