    5,
    'Epidemiologia Clínica - Tipos de Estudo e Medidas',
    'MULTIPLE_CHOICE',
    'Em uma única semana, os ACS aferem a pressão arterial e aplicam um questionário a uma amostra de adultos do território para estimar quantos têm hipertensão naquele momento. Que tipo de estudo é esse?',
    'C',
    '["A) Estudo de coorte", "B) Ensaio clínico randomizado", "C) Estudo transversal", "D) Estudo de caso-controle"]'::jsonb,
