(
    5,
    'Epidemiologia Clínica - Tipos de Estudo e Medidas',
    'MULTIPLE_CHOICE',
    'Em um ensaio clínico, 20% dos pacientes do grupo controle e 15% do grupo tratado tiveram o desfecho em um ano. Qual é o número necessário para tratar (NNT)?',
    'D',
    '["A) 5", "B) 25", "C) 4", "D) 20"]'::jsonb,
    'A redução absoluta de risco é 20% - 15% = 5% (0,05). NNT = 1 / RAR = 1 / 0,05 = 20 pessoas tratadas por um ano para evitar um desfecho.',
