    5,
    'Epidemiologia Clínica - Tipos de Estudo e Medidas',
    'MULTIPLE_CHOICE',
    'Pesquisadores selecionam 100 mulheres com câncer de mama e 200 sem a doença e investigam, nos registros, o uso prévio de terapia hormonal. Qual é o desenho do estudo e a medida de associação típica?',
    'A',
    '["A) Caso-controle, com razão de chances (odds ratio)", "B) Coorte prospectiva, com risco relativo", "C) Transversal, com razão de prevalências", "D) Ensaio clínico, com redução absoluta de risco"]'::jsonb,
    'No caso-controle, os participantes são escolhidos pelo desfecho e a exposição é buscada no passado. Como não se mede incidência, a medida de associação é a odds ratio.',
    'MEDIUM',
    'Medronho, Epidemiologia (questão original)',
    TRUE
),
(
    5,
    'Epidemiologia Clínica - Tipos de Estudo e Medidas',
    'MULTIPLE_CHOICE',
    'Um medicamento reduz a ocorrência de AVC em 5 anos de 2% para 1%. Qual afirmação descreve corretamente esse efeito?',
    'D',
    '["A) Redução relativa de risco de 1%, redução absoluta de 50% e NNT de 2", "B) Redução relativa e absoluta de risco iguais a 50%, com NNT de 2", "C) Redução absoluta de risco de 1 ponto percentual e NNT de 50", "D) Redução relativa de risco de 50%, redução absoluta de 1 ponto percentual e NNT de 100"]'::jsonb,
    'RRR = (2% - 1%) / 2% = 50%. RAR = 2% - 1% = 1 ponto percentual. NNT = 1 / 0,01 = 100. Apresentar só a redução relativa faz o benefício parecer maior do que é.',
