    '["A) Até 4.000 pessoas, com média recomendada de 3.000", "B) De 2.000 a 3.500 pessoas, ajustada conforme vulnerabilidade e risco do território", "C) De 5.000 a 8.000 pessoas por equipe", "D) Até 1.000 pessoas, independentemente do perfil do território"]'::jsonb,
