(
    5,
    'Estratégia Saúde da Família - Organização e Territorialização',
    'MULTIPLE_CHOICE',
    'Uma equipe de Saúde da Família aplica a escala de Coelho e Savassi às famílias cadastradas, usando sentinelas como pessoa acamada, desnutrição grave, desemprego e relação morador por cômodo. Qual é a finalidade dessa escala?',
