    '["A) Estimar o risco cardiovascular em 10 anos de cada adulto da família", "B) Avaliar a funcionalidade familiar a partir da percepção de satisfação de um membro", "C) Estratificar o risco social e de saúde das famílias para priorizar visitas domiciliares e o planejamento da equipe", "D) Classificar a urgência das pessoas atendidas na demanda espontânea do dia"]'::jsonb,
    'A escala de risco familiar de Coelho e Savassi usa dados do cadastro para classificar famílias em risco menor, médio ou máximo, orientando prioridades de visita. Avaliar satisfação com a família é função do APGAR familiar.',
