    5,
    'Vigilância em Saúde - Notificação Compulsória',
    'MULTIPLE_CHOICE',
    'Criança de 3 anos, não vacinada, chega à UBS com febre alta, exantema maculopapular, tosse, coriza e conjuntivite. Diante da suspeita de sarampo, qual é a conduta de vigilância correta?',
