(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Alergia e Imunologia de Urgência - Anafilaxia',
    'MULTIPLE_CHOICE',
    'Adulto de 70 kg desenvolve urticária generalizada, sibilância e rouquidão minutos após receber dipirona IV. Qual é o tratamento de primeira linha?',
    'C',
    '["A) Prometazina 50 mg IV como medida inicial isolada", "B) Hidrocortisona 500 mg IV e observação", "C) Adrenalina 1 mg/mL, 0,5 mg por via intramuscular na face anterolateral da coxa", "D) Adrenalina 1 mg IV em bolus, como na PCR"]'::jsonb,
    'Na anafilaxia a adrenalina IM (0,01 mg/kg da solução 1 mg/mL, máximo de 0,5 mg no adulto) no vasto lateral é o tratamento de primeira linha, podendo ser repetida a cada 5 a 15 minutos. Anti-histamínicos e corticoides são adjuvantes. O bolus IV de 1 mg é dose de PCR e pode causar arritmias graves.',
    'EASY',
    'World Allergy Organization Anaphylaxis Guidance 2020 / ASBAI (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Alergia e Imunologia de Urgência - Anafilaxia',
    'MULTIPLE_CHOICE',
    'Homem com alergia conhecida a veneno de abelha é picado e, 10 minutos depois, apresenta tontura e PA 78/40 mmHg, sem lesões cutâneas. Como interpretar e conduzir o quadro?',
    'A',
    '["A) É anafilaxia mesmo sem pele: hipotensão logo após exposição a alérgeno conhecido basta; aplicar adrenalina IM", "B) Não é anafilaxia, pois a ausência de urticária afasta o diagnóstico", "C) Trata-se de reação vasovagal; elevar os membros inferiores basta", "D) Deve-se dosar triptase sérica antes de qualquer medicação"]'::jsonb,
    'Pelos critérios da WAO 2020, hipotensão, broncoespasmo ou acometimento laríngeo minutos a horas após exposição a alérgeno conhecido ou muito provável configuram anafilaxia mesmo sem lesão cutânea, que falta em parte dos casos. A triptase ajuda depois, mas nunca deve atrasar a adrenalina.',
    'MEDIUM',
    'World Allergy Organization Anaphylaxis Guidance 2020 / ASBAI (questão original)',
