    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Alergia e Imunologia de Urgência - Anafilaxia',
    'MULTIPLE_CHOICE',
    'Mulher hipertensa em uso de atenolol mantém hipotensão e broncoespasmo em anafilaxia, apesar de duas doses de adrenalina IM e expansão volêmica adequada. Qual medicamento adicional é mais indicado?',
    'A',
    '["A) Glucagon IV", "B) Atropina IV em doses repetidas", "C) Metoprolol IV para controle da frequência", "D) Salbutamol oral"]'::jsonb,
