    'Choque - Classificação e Manejo Inicial',
    'MULTIPLE_CHOICE',
    'Motociclista com fratura de pelve e sinais de choque hemorrágico classe III. Já recebeu 1 litro de cristaloide aquecido, sem resposta sustentada. Qual é a estratégia de reposição mais adequada?',
    'D',
    '["A) Infundir mais 3 litros de cristaloide antes de considerar sangue (regra de 3 para 1)", "B) Iniciar noradrenalina como primeira medida para elevar a pressão", "C) Repor apenas albumina 20% até normalizar a pressão arterial", "D) Iniciar precocemente hemocomponentes em proporção balanceada e buscar controle da hemorragia, limitando novos cristaloides"]'::jsonb,
