    'D',
    '["A) Repetir benzodiazepínico a cada 5 minutos até a cessação", "B) Iniciar carbamazepina por sonda nasogástrica", "C) Solicitar eletroencefalograma ambulatorial e manter observação", "D) Dose de ataque IV de droga de segunda linha, como fenitoína 20 mg/kg, levetiracetam ou valproato"]'::jsonb,
    'Após falha de duas doses de benzodiazepínico, a segunda linha é uma dose de ataque IV de fenitoína (ou fosfenitoína), levetiracetam ou valproato, com eficácia semelhante. Doses repetidas de benzodiazepínico aumentam depressão respiratória sem benefício, e a via enteral é lenta demais.',
    'MEDIUM',
    'Diretriz AES/ILAE para Estado de Mal Epiléptico (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Emergências Tempo-Dependentes - IAM, AVC e Estado de Mal Epiléptico',
    'MULTIPLE_CHOICE',
    'Paciente com IAM com supra de ST receberá fibrinólise porque não há hemodinâmica disponível em tempo hábil. Qual achado da história é contraindicação absoluta ao trombolítico?',
    'C',
    '["A) PA de 170x100 mmHg na admissão", "B) AVC isquêmico há 2 anos", "C) Hemorragia intracraniana prévia, em qualquer época", "D) Idade acima de 75 anos"]'::jsonb,
    'Hemorragia intracraniana prévia é contraindicação absoluta à fibrinólise. AVC isquêmico há mais de 3 meses, PA elevada controlável (contraindicação só acima de cerca de 180x110 mmHg) e idade avançada são contraindicações relativas ou pedem cautela, não proibição.',
    'HARD',
    'Diretriz da SBC de IAM com supra de ST (questão original)',
