    'No pacote da primeira hora, as culturas (incluindo dois pares de hemocultura) devem ser colhidas antes do antibiótico porque a primeira dose reduz a positividade. Mas a coleta não pode atrasar a antibioticoterapia, que deve começar em até 1 hora quando há choque ou sepse provável.',
    'EASY',
    'Surviving Sepsis Campaign 2021 / ILAS (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Sepse - Pacote da Primeira Hora',
    'MULTIPLE_CHOICE',
    'Mulher de 70 kg com sepse de foco pulmonar está com PA 82/48 mmHg e lactato de 4,6 mmol/L. Qual é a reposição volêmica inicial recomendada pelo pacote da primeira hora?',
    'D',
    '["A) 500 mL de soro fisiológico e aguardar o resultado da hemocultura", "B) Albumina 20% como fluido de primeira escolha", "C) Restrição hídrica com diurético, pelo risco de congestão pulmonar", "D) Cerca de 30 mL/kg de cristaloide (aproximadamente 2,1 L), iniciada na primeira hora e reavaliada"]'::jsonb,
    'Hipotensão ou lactato maior ou igual a 4 mmol/L indicam 30 mL/kg de cristaloide nas primeiras 3 horas, com reavaliação frequente da resposta. Albumina pode ser associada quando são necessários grandes volumes, mas não é o fluido inicial.',
    'MEDIUM',
    'Surviving Sepsis Campaign 2021 / ILAS (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Sepse - Pacote da Primeira Hora',
    'MULTIPLE_CHOICE',
    'Paciente com choque séptico mantém PAM de 58 mmHg após receber 30 mL/kg de cristaloide. Ainda não há cateter venoso central disponível. Qual é a melhor conduta?',
    'B',
    '["A) Aguardar a passagem do cateter central para só então iniciar vasopressor", "B) Iniciar noradrenalina por veia periférica calibrosa, com alvo de PAM de 65 mmHg, sem aguardar o acesso central", "C) Iniciar dopamina como vasopressor de primeira escolha", "D) Administrar hidrocortisona e aguardar 1 hora antes de qualquer vasopressor"]'::jsonb,
    'A noradrenalina é o vasopressor de primeira linha e a Surviving Sepsis Campaign 2021 sugere iniciá-la por via periférica em vez de atrasar o tratamento até obter acesso central, com alvo inicial de PAM 65 mmHg. Dopamina tem mais arritmias e a hidrocortisona é reservada ao choque que exige doses crescentes de vasopressor.',
    'HARD',
    'Surviving Sepsis Campaign 2021 / ILAS (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Suporte de Vida - Parada Cardiorrespiratória (BLS e ACLS)',
    'MULTIPLE_CHOICE',
    'Adulto colapsa na recepção de uma UBS, não responde e apresenta apenas respiração agônica (gasping). Ajuda e DEA já foram acionados. Como devem ser feitas as compressões torácicas?',
    'B',
    '["A) Frequência de 60 a 80 por minuto, profundidade de 2 a 3 cm, para evitar fratura de costelas", "B) Frequência de 100 a 120 por minuto, profundidade de 5 a 6 cm, permitindo retorno completo do tórax", "C) Frequência acima de 140 por minuto, sem preocupação com a profundidade", "D) Somente após checar pulso carotídeo por pelo menos 30 segundos"]'::jsonb,
    'Gasping não é respiração normal e deve ser tratado como PCR. A RCP de alta qualidade exige 100 a 120 compressões por minuto, 5 a 6 cm de profundidade, retorno total do tórax e mínimas interrupções. A checagem de pulso, se feita, não deve passar de 10 segundos.',
    'EASY',
    'AHA Guidelines for CPR and ECC (ACLS) vigentes (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Suporte de Vida - Parada Cardiorrespiratória (BLS e ACLS)',
    'MULTIPLE_CHOICE',
    'Paciente em PCR com fibrilação ventricular persistente. Já recebeu três choques, dois ciclos de RCP e uma dose de epinefrina 1 mg IV. Qual antiarrítmico está indicado neste momento?',
    'D',
    '["A) Adenosina 6 mg IV em bolus rápido", "B) Atropina 1 mg IV a cada 3 a 5 minutos", "C) Verapamil 5 mg IV lento", "D) Amiodarona 300 mg IV em bolus (alternativa: lidocaína)"]'::jsonb,
    'Na FV/TV sem pulso refratária a choques, a amiodarona 300 mg IV/IO é o antiarrítmico indicado após o terceiro choque (segunda dose de 150 mg se necessário); a lidocaína é alternativa aceita. Adenosina serve para taquicardia supraventricular com pulso e a atropina não tem papel na PCR.',
    'MEDIUM',
    'AHA Guidelines for CPR and ECC (ACLS) vigentes (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Suporte de Vida - Parada Cardiorrespiratória (BLS e ACLS)',
    'MULTIPLE_CHOICE',
    'Durante o atendimento de uma PCR, o monitor mostra linha reta, confirmada em duas derivações e com ganho adequado. Qual é a conduta correta?',
    'A',
    '["A) Manter RCP de alta qualidade e administrar epinefrina 1 mg IV/IO o mais precocemente possível, sem choque", "B) Desfibrilar com 200 J em aparelho bifásico e reiniciar a RCP", "C) Administrar atropina 1 mg IV a cada 3 minutos até 3 mg", "D) Instalar marca-passo transcutâneo como medida inicial"]'::jsonb,
    'Assistolia é ritmo não chocável: a conduta é RCP contínua com epinefrina 1 mg o quanto antes, repetida a cada 3 a 5 minutos, e busca de causas reversíveis. Choque não tem efeito em assistolia, a atropina saiu do algoritmo de PCR e o marca-passo transcutâneo não é recomendado na assistolia.',
    'MEDIUM',
    'AHA Guidelines for CPR and ECC (ACLS) vigentes (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Suporte de Vida - Parada Cardiorrespiratória (BLS e ACLS)',
    'MULTIPLE_CHOICE',
    'Homem de 62 anos, renal crônico em hemodiálise, faltou às duas últimas sessões. Chega fraco, o ECG mostra ondas T apiculadas e QRS alargado, e evolui para PCR em atividade elétrica sem pulso. Além da RCP e da epinefrina, qual medida é prioritária?',
    'C',
    '["A) Amiodarona 300 mg IV em bolus", "B) Desfibrilação imediata com carga máxima", "C) Cálcio IV (gluconato ou cloreto de cálcio) para estabilizar a membrana miocárdica", "D) Furosemida em dose alta para induzir caliurese"]'::jsonb,
    'A suspeita de hipercalemia (uma das causas reversíveis, os 5H e 5T) na AESP justifica cálcio IV imediato, associado a medidas que deslocam o potássio para dentro da célula (insulina com glicose, bicarbonato) e diálise após o retorno da circulação. AESP não é ritmo chocável e a furosemida não age a tempo na PCR.',
    'HARD',
    'AHA Guidelines for CPR and ECC (ACLS) vigentes (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Toxicologia - Intoxicações Exógenas',
    'MULTIPLE_CHOICE',
    'Trabalhador rural chega com miose, sialorreia, broncorreia, sudorese intensa, bradicardia e fasciculações após aplicar inseticida sem proteção. Qual é o antídoto inicial prioritário?',
    'C',
    '["A) Flumazenil IV", "B) Naloxona IV", "C) Atropina IV em doses repetidas até secar as secreções brônquicas", "D) N-acetilcisteína IV"]'::jsonb,
    'O quadro é de síndrome colinérgica por inibidor da acetilcolinesterase (organofosforado ou carbamato). A atropina, titulada até a secagem das secreções pulmonares, é a medida salvadora; a pralidoxima pode ser associada nos organofosforados.',
    'EASY',
    'Manual de Toxicologia Clínica - MS/ABRACIT (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Toxicologia - Intoxicações Exógenas',
    'MULTIPLE_CHOICE',
    'Jovem de 19 anos relata ter ingerido grande quantidade de comprimidos de paracetamol há 4 horas. Está assintomática. Qual é o antídoto e quando ele é mais eficaz?',
    'B',
    '["A) Flumazenil, apenas se houver rebaixamento de consciência", "B) N-acetilcisteína, com máxima proteção hepática quando iniciada nas primeiras 8 horas após a ingestão", "C) Vitamina K, somente após elevação das transaminases", "D) Não há antídoto; só suporte quando surgir icterícia"]'::jsonb,
    'A N-acetilcisteína repõe glutationa e neutraliza o metabólito tóxico do paracetamol. A decisão se baseia na dosagem sérica a partir de 4 horas no nomograma de Rumack-Matthew, e a eficácia é máxima até 8 horas. A paciente assintomática não afasta lesão hepática, que aparece depois.',
    'MEDIUM',
    'Manual de Toxicologia Clínica - MS/ABRACIT (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'URG_EMERG'),
    'Toxicologia - Intoxicações Exógenas',
    'MULTIPLE_CHOICE',
    'Mulher sonolenta após ingerir diazepam e amitriptilina. Está hipotensa e o ECG mostra QRS de 130 ms com taquicardia sinusal. Qual é a conduta específica mais adequada?',
    'D',
    '["A) Flumazenil IV para reverter o benzodiazepínico", "B) Fisostigmina IV como antídoto do tricíclico", "C) Amiodarona IV para tratar o alargamento do QRS", "D) Bicarbonato de sódio IV, evitando flumazenil"]'::jsonb,
    'O QRS alargado indica bloqueio de canais de sódio pelo tricíclico, tratado com bicarbonato de sódio. O flumazenil é contraindicado na coingestão de tricíclico (pode precipitar convulsões e arritmias), e fisostigmina e antiarrítmicos da classe III pioram a cardiotoxicidade.',
    'HARD',
    'Manual de Toxicologia Clínica - MS/ABRACIT (questão original)',
    TRUE
);

