INSERT INTO tb_flashcard (subject_id, topic, question_type, question, answer, options_json, explanation, difficulty, source, active)
VALUES
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Dependência Química - Álcool e Outras Drogas',
    'MULTIPLE_CHOICE',
    'Homem etilista pesado está internado há 30 horas por fratura e apresenta tremor, sudorese, taquicardia, ansiedade e insônia. Qual é a classe de medicamento de escolha para tratar a abstinência?',
    'B',
    '["A) Antipsicóticos como monoterapia", "B) Benzodiazepínicos", "C) Opioides de longa ação", "D) Anticonvulsivantes como fenitoína"]'::jsonb,
    'Os benzodiazepínicos são a base do tratamento da síndrome de abstinência alcoólica, pois agem no receptor GABA-A e previnem convulsões e delirium tremens. Antipsicóticos isolados reduzem o limiar convulsivo e a fenitoína não previne crises de abstinência.',
    'EASY',
    'Diretrizes ABP / ABEAD - Síndrome de Abstinência Alcoólica (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Dependência Química - Álcool e Outras Drogas',
    'MULTIPLE_CHOICE',
    'Paciente etilista desnutrido chega confuso, com marcha atáxica e nistagmo. A equipe vai iniciar soro glicosado. Qual cuidado é essencial?',
    'D',
    '["A) Administrar glicose hipertônica antes de qualquer vitamina", "B) Iniciar vitamina B12 intramuscular isolada", "C) Aguardar ressonância magnética para confirmar o diagnóstico", "D) Administrar tiamina parenteral antes ou junto com a glicose"]'::jsonb,
    'Confusão, ataxia e alterações oculomotoras sugerem encefalopatia de Wernicke por deficiência de tiamina. A glicose consome tiamina e pode precipitar ou agravar o quadro, por isso a tiamina parenteral deve vir antes ou junto. O diagnóstico é clínico e o tratamento não espera exame.',
    'MEDIUM',
    'Diretrizes ABP / ABEAD - Síndrome de Abstinência Alcoólica (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Dependência Química - Álcool e Outras Drogas',
    'MULTIPLE_CHOICE',
    'Homem com dependência de álcool fez a última ingestão há 72 horas e agora apresenta desorientação, alucinações visuais, agitação, febre e taquicardia. Qual é o diagnóstico mais provável?',
    'D',
    '["A) Alucinose alcoólica com consciência preservada", "B) Intoxicação alcoólica aguda", "C) Síndrome de Korsakoff", "D) Delirium tremens"]'::jsonb,
    'O delirium tremens surge tipicamente entre 48 e 96 horas após a última dose, com rebaixamento do nível de consciência, desorientação, alucinações e hiperatividade autonômica, sendo uma emergência médica. Na alucinose a consciência fica preservada, e o Korsakoff é amnésia crônica, sem hiperatividade autonômica.',
    'MEDIUM',
    'Diretrizes ABP / ABEAD - Síndrome de Abstinência Alcoólica (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Dependência Química - Álcool e Outras Drogas',
    'MULTIPLE_CHOICE',
    'Paciente com cirrose descompensada (Child-Pugh C) inicia sintomas de abstinência alcoólica moderada. Qual benzodiazepínico é o mais adequado?',
    'C',
    '["A) Diazepam", "B) Clordiazepóxido", "C) Lorazepam", "D) Flurazepam"]'::jsonb,
    'Na insuficiência hepática grave prefere-se lorazepam (ou oxazepam), que tem meia-vida intermediária e é metabolizado por glicuronidação, sem metabólitos ativos. Diazepam, clordiazepóxido e flurazepam dependem de oxidação hepática e geram metabólitos ativos de longa ação, com risco de acúmulo e encefalopatia.',
    'HARD',
    'Diretrizes ABP / ABEAD - Síndrome de Abstinência Alcoólica (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Políticas de Saúde Mental - RAPS, CAPS e Lei 10.216/2001',
    'MULTIPLE_CHOICE',
    'Pela Lei 10.216/2001, como se chama a internação psiquiátrica determinada pela Justiça?',
    'B',
    '["A) Internação involuntária", "B) Internação compulsória", "C) Internação voluntária", "D) Internação domiciliar"]'::jsonb,
    'A lei prevê três tipos: voluntária (com consentimento do paciente), involuntária (sem consentimento, a pedido de terceiro e com laudo médico) e compulsória (determinada pela Justiça). Em todas, a internação só é indicada quando os recursos extra-hospitalares forem insuficientes.',
    'EASY',
    'Lei 10.216/2001 e Portaria GM/MS 3.088/2011 (RAPS) (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Políticas de Saúde Mental - RAPS, CAPS e Lei 10.216/2001',
    'MULTIPLE_CHOICE',
    'Um paciente psicótico é internado involuntariamente a pedido da família. Pela Lei 10.216/2001, o que deve ser feito?',
    'C',
    '["A) É obrigatória autorização judicial prévia", "B) A internação dispensa qualquer comunicação, pois a família autorizou", "C) O responsável técnico do estabelecimento deve comunicar a internação ao Ministério Público Estadual em até 72 horas", "D) A comunicação deve ser feita ao Conselho Regional de Medicina em 30 dias"]'::jsonb,
    'A internação involuntária exige laudo médico e deve ser comunicada ao Ministério Público Estadual em até 72 horas, o mesmo ocorrendo na alta. Autorização judicial prévia caracterizaria internação compulsória, que é outra modalidade.',
    'MEDIUM',
    'Lei 10.216/2001 e Portaria GM/MS 3.088/2011 (RAPS) (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Políticas de Saúde Mental - RAPS, CAPS e Lei 10.216/2001',
    'MULTIPLE_CHOICE',
    'Na Rede de Atenção Psicossocial, qual serviço é destinado ao cuidado de adultos com uso problemático de crack, álcool e outras drogas, com funcionamento 24 horas e acolhimento noturno?',
    'D',
    '["A) CAPS I", "B) CAPS i (infantojuvenil)", "C) Serviço Residencial Terapêutico", "D) CAPS AD III"]'::jsonb,
    'Pela Portaria 3.088/2011, o CAPS AD III atende pessoas com necessidades decorrentes de álcool e outras drogas, funciona 24 horas, todos os dias, e oferece leitos de acolhimento noturno. O CAPS i atende crianças e adolescentes e o Serviço Residencial Terapêutico é moradia para egressos de longas internações.',
    'MEDIUM',
    'Lei 10.216/2001 e Portaria GM/MS 3.088/2011 (RAPS) (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Psicoses - Esquizofrenia e Antipsicóticos',
    'MULTIPLE_CHOICE',
    'Na esquizofrenia, qual dos achados abaixo é classificado como sintoma negativo?',
    'A',
    '["A) Embotamento afetivo com pobreza do discurso (alogia)", "B) Alucinações auditivas de vozes comentando", "C) Delírio de perseguição", "D) Discurso desorganizado com afrouxamento de associações"]'::jsonb,
    'Sintomas negativos são perdas de funções normais: embotamento afetivo, alogia, avolição, anedonia e isolamento social. Alucinações e delírios são sintomas positivos; a desorganização do discurso compõe a dimensão de desorganização.',
