(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Psicoses - Esquizofrenia e Antipsicóticos',
    'MULTIPLE_CHOICE',
    'Paciente iniciou haloperidol há 5 dias e apresenta febre de 40 °C, rigidez muscular intensa, confusão mental, sudorese e PA lábil. A CPK está muito elevada. Qual é a conduta inicial?',
    'A',
    '["A) Suspender o antipsicótico e iniciar suporte intensivo, com resfriamento e hidratação", "B) Aumentar a dose de haloperidol para controlar a agitação", "C) Trocar por outro antipsicótico de alta potência no mesmo dia", "D) Manter o antipsicótico e associar antitérmico"]'::jsonb,
    'O quadro é de síndrome neuroléptica maligna: febre, rigidez, alteração da consciência, instabilidade autonômica e CPK elevada. A conduta é suspender o antipsicótico, oferecer suporte (hidratação, resfriamento, prevenção de rabdomiólise e lesão renal) e, nos graves, considerar bromocriptina ou dantroleno.',
    'MEDIUM',
    'Diretrizes ABP e PCDT Esquizofrenia (MS) (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Psicoses - Esquizofrenia e Antipsicóticos',
    'MULTIPLE_CHOICE',
    'Homem com esquizofrenia mantém alucinações e delírios apesar do uso, com boa adesão, de risperidona e depois olanzapina, cada uma em dose e tempo adequados. Qual é a conduta indicada e o principal cuidado de segurança?',
    'C',
    '["A) Associar dois antipsicóticos típicos de alta potência sem monitoramento", "B) Iniciar clozapina com monitoramento apenas da função tireoidiana", "C) Iniciar clozapina com monitoramento regular do hemograma pelo risco de agranulocitose", "D) Suspender os antipsicóticos e manter apenas benzodiazepínico"]'::jsonb,
    'Falha de dois antipsicóticos em dose e tempo adequados define esquizofrenia resistente, cuja droga de escolha é a clozapina (disponível pelo PCDT). Ela pode causar neutropenia e agranulocitose, o que exige hemogramas frequentes, sobretudo nos primeiros meses.',
    'HARD',
    'Diretrizes ABP e PCDT Esquizofrenia (MS) (questão original)',
