),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Psiquiatria de Interconsulta - Delirium',
    'MULTIPLE_CHOICE',
    'Qual característica clínica mais ajuda a diferenciar delirium de demência?',
    'A',
    '["A) Início agudo, curso flutuante ao longo do dia e déficit de atenção", "B) Perda de memória para fatos recentes", "C) Idade acima de 65 anos", "D) Piora lenta e progressiva ao longo de anos"]'::jsonb,
    'O delirium é uma síndrome aguda, de horas a dias, com flutuação e desatenção como núcleo, sempre com causa orgânica a investigar (critérios do CAM). A demência tem início insidioso e progressão lenta; perda de memória e idade avançada ocorrem nas duas condições.',
    'EASY',
    'DSM-5-TR e Consenso SBGG sobre Delirium (questão original)',
