(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Psiquiatria de Interconsulta - Delirium',
    'MULTIPLE_CHOICE',
    'Idoso de 80 anos internado por pneumonia fica confuso e desatento à noite, sem agitação que ofereça risco. Qual é a abordagem inicial mais adequada?',
    'B',
    '["A) Prescrever benzodiazepínico ao deitar para dormir melhor", "B) Tratar a causa, revisar medicamentos e adotar medidas não farmacológicas, como reorientação, óculos, sono e presença da família", "C) Iniciar haloperidol fixo de 8 em 8 horas como prevenção", "D) Contenção mecânica noturna preventiva"]'::jsonb,
    'O manejo do delirium começa por identificar e tratar a causa e retirar fármacos deliriogênicos, com medidas não farmacológicas. Antipsicóticos ficam para agitação grave com risco, em baixa dose e por pouco tempo; benzodiazepínicos e contenção pioram o quadro.',
    'MEDIUM',
    'DSM-5-TR e Consenso SBGG sobre Delirium (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Psiquiatria de Interconsulta - Delirium',
    'MULTIPLE_CHOICE',
    'Idosa de 84 anos com infecção urinária passa a dormir muito, fala pouco, perde o fio da conversa e responde devagar. A família acha que ela está ''deprimida''. Qual é a hipótese mais provável?',
    'A',
    '["A) Delirium hipoativo", "B) Episódio depressivo maior com início tardio", "C) Demência frontotemporal", "D) Efeito esperado da idade, sem necessidade de investigação"]'::jsonb,
    'O delirium hipoativo cursa com sonolência, lentificação e apatia, mas mantém a desatenção e o início agudo ligado a uma causa orgânica (aqui a infecção). É a forma mais subdiagnosticada, muitas vezes confundida com depressão, e tem pior prognóstico.',
    'HARD',
    'DSM-5-TR e Consenso SBGG sobre Delirium (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Saúde Mental - Avaliação de Risco de Suicídio',
    'MULTIPLE_CHOICE',
    'Durante consulta, paciente com depressão diz que ''nada faz sentido''. O médico tem receio de que perguntar sobre suicídio possa induzir a ideia. Qual é a orientação correta?',
    'A',
    '["A) Perguntar diretamente e com empatia sobre ideação suicida, pois isso não aumenta o risco e permite avaliá-lo", "B) Evitar o tema e aguardar que o próprio paciente fale sobre isso", "C) Perguntar apenas se houver tentativa prévia documentada", "D) Encaminhar ao psiquiatra sem abordar o assunto na consulta"]'::jsonb,
    'Perguntar de forma direta e acolhedora sobre pensamentos de morte não induz comportamento suicida; ao contrário, costuma aliviar o paciente e é o único modo de estimar o risco. Esperar que o paciente fale espontaneamente deixa muitos casos sem detecção.',
    'EASY',
    'ABP - Suicídio: informando para prevenir / MS (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Saúde Mental - Avaliação de Risco de Suicídio',
    'MULTIPLE_CHOICE',
    'Na avaliação de risco de suicídio, qual fator isolado é considerado o mais forte preditor de morte por suicídio?',
    'D',
    '["A) Sexo feminino", "B) Religiosidade intensa", "C) Ter filhos pequenos em casa", "D) Tentativa de suicídio prévia"]'::jsonb,
    'A tentativa prévia é o principal fator de risco isolado para suicídio consumado, junto com transtorno mental (sobretudo depressão e uso de álcool). Mulheres tentam mais, mas homens morrem mais por suicídio; religiosidade e filhos pequenos costumam ser fatores de proteção.',
    'MEDIUM',
    'ABP - Suicídio: informando para prevenir / MS (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Saúde Mental - Avaliação de Risco de Suicídio',
    'MULTIPLE_CHOICE',
    'Homem de 52 anos, viúvo recente e etilista, diz que planeja se enforcar neste fim de semana, já comprou a corda e escreveu cartas de despedida. Qual é a conduta mais adequada?',
    'B',
    '["A) Firmar um contrato verbal de não suicídio e agendar retorno em 30 dias", "B) Não deixá-lo sozinho, envolver a família, restringir meios e encaminhar para avaliação psiquiátrica de urgência com possível internação", "C) Prescrever antidepressivo e orientar que o efeito virá em 4 semanas", "D) Encaminhar ao CAPS por ofício, com consulta em data a ser marcada"]'::jsonb,
    'Plano estruturado, acesso ao meio, preparativos (cartas) e fatores de risco somados (viuvez, álcool, sexo masculino) indicam risco alto e iminente: exigem proteção imediata e avaliação de urgência. Contrato de não suicídio não tem eficácia comprovada e antidepressivo não age a tempo.',
    'HARD',
    'ABP - Suicídio: informando para prevenir / MS (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Transtornos de Humor - Transtorno Bipolar',
    'MULTIPLE_CHOICE',
    'Mulher de 28 anos com episódio depressivo grave relata que há 2 anos passou 10 dias sem dormir, gastando todo o salário e com ideias de grandeza, sendo internada. Qual cuidado é essencial na escolha do tratamento?',
    'D',
    '["A) Iniciar ISRS em monoterapia, pois o episódio atual é depressivo", "B) Prescrever apenas benzodiazepínico até a melhora", "C) Ignorar o episódio anterior, que não interfere no tratamento", "D) Evitar antidepressivo em monoterapia, pelo risco de virada maníaca, e usar estabilizador de humor"]'::jsonb,
    'A história de episódio maníaco define transtorno bipolar tipo I. Na depressão bipolar o antidepressivo em monoterapia pode induzir mania ou ciclagem rápida; o tratamento se apoia em estabilizadores de humor ou antipsicóticos com eficácia na depressão bipolar, como quetiapina ou lurasidona.',
    'EASY',
    'Diretrizes da ABP / CANMAT para transtornos de humor (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Transtornos de Humor - Transtorno Bipolar',
    'MULTIPLE_CHOICE',
    'Paciente bipolar estável com lítio e litemia de 0,8 mEq/L passa a usar hidroclorotiazida para hipertensão. Duas semanas depois tem tremor grosseiro, náuseas e ataxia. Qual é a explicação mais provável?',
    'B',
    '["A) Efeito colateral isolado da hidroclorotiazida, sem relação com o lítio", "B) Intoxicação por lítio, pois o tiazídico reduz a excreção renal do lítio e eleva a litemia", "C) Recaída maníaca por queda da litemia causada pelo diurético", "D) Hipotireoidismo agudo induzido pelo anti-hipertensivo"]'::jsonb,
    'Tiazídicos, IECA e anti-inflamatórios não esteroidais aumentam a reabsorção do lítio e elevam a litemia, que tem janela terapêutica estreita. Tremor grosseiro, sintomas gastrointestinais e ataxia sugerem toxicidade: é preciso dosar a litemia, suspender o lítio e hidratar.',
    'MEDIUM',
    'Diretrizes da ABP / CANMAT para transtornos de humor (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Transtornos de Humor - Transtorno Bipolar',
    'MULTIPLE_CHOICE',
    'Homem de 33 anos teve dois episódios depressivos maiores. Entre eles, por 5 dias, ficou mais falante, dormindo 4 horas sem cansaço e muito produtivo, sem prejuízo no trabalho, sem sintomas psicóticos e sem internação. Qual é o diagnóstico mais provável?',
    'C',
    '["A) Transtorno bipolar tipo I", "B) Transtorno depressivo maior recorrente", "C) Transtorno bipolar tipo II", "D) Transtorno ciclotímico"]'::jsonb,
    'Episódio de pelo menos 4 dias com elevação do humor, sem prejuízo funcional marcado, psicose ou internação é hipomaníaco; com episódios depressivos maiores, configura bipolar tipo II. Mania (tipo I) exige pelo menos 7 dias ou internação; na ciclotimia não há episódios depressivos maiores.',
    'HARD',
    'DSM-5-TR - Transtornos Bipolares (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Transtornos de Humor e Ansiedade - Depressão e Ansiedade na Prática Clínica',
    'MULTIPLE_CHOICE',
    'Mulher de 35 anos tem episódio depressivo moderado há 2 meses, sem sintomas psicóticos nem história de mania. Qual classe de antidepressivo é a primeira escolha habitual na atenção primária?',
    'A',
    '["A) Inibidores seletivos da recaptação de serotonina, como sertralina ou fluoxetina", "B) Inibidores da monoaminoxidase, como tranilcipromina", "C) Benzodiazepínicos em uso contínuo", "D) Antipsicóticos típicos, como haloperidol"]'::jsonb,
    'Os ISRS são a primeira linha pela boa tolerabilidade, baixa toxicidade em superdosagem e disponibilidade no SUS (fluoxetina). IMAO exigem restrição alimentar e são reservados a casos refratários; benzodiazepínicos não tratam depressão.',
    'EASY',
    'Cadernos de Atenção Básica nº 34 - Saúde Mental (MS) (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Transtornos de Humor e Ansiedade - Depressão e Ansiedade na Prática Clínica',
    'MULTIPLE_CHOICE',
    'Paciente em primeiro episódio depressivo atinge remissão completa após 8 semanas de sertralina e pergunta quando pode parar o remédio. Qual é a orientação correta?',
    'C',
    '["A) Suspender logo, pois a remissão indica cura", "B) Manter por toda a vida, como em qualquer episódio depressivo", "C) Manter a mesma dose por pelo menos 6 a 12 meses após a remissão e depois retirar gradualmente", "D) Reduzir para metade da dose e suspender em 2 semanas"]'::jsonb,
    'Após a remissão do primeiro episódio, a fase de continuação dura de 6 a 12 meses na dose eficaz para prevenir recaída, seguida de retirada gradual para evitar síndrome de descontinuação. Uso prolongado fica para episódios recorrentes ou outros fatores de risco.',
    'MEDIUM',
    'Diretrizes da ABP / CANMAT para transtornos de humor (questão original)',
    TRUE
),
(
    (SELECT id FROM tb_subject WHERE course_id = 1 AND code = 'SAUDE_MENTAL'),
    'Transtornos de Humor e Ansiedade - Depressão e Ansiedade na Prática Clínica',
    'MULTIPLE_CHOICE',
    'Homem de 40 anos tem preocupação excessiva e difícil de controlar há 8 meses, com tensão muscular, insônia e irritabilidade, sem uso de substâncias. Qual é o tratamento de primeira linha a longo prazo?',
    'C',
    '["A) Clonazepam contínuo como monoterapia por tempo indeterminado", "B) Antipsicótico atípico em dose plena", "C) Psicoterapia (terapia cognitivo-comportamental) e/ou ISRS ou IRSN", "D) Betabloqueador como tratamento de manutenção"]'::jsonb,
    'No transtorno de ansiedade generalizada, a TCC e os antidepressivos (ISRS ou IRSN) são primeira linha. Benzodiazepínicos podem ser usados por pouco tempo, mas não como monoterapia prolongada pelo risco de dependência, tolerância e quedas.',
    'MEDIUM',
    'Diretrizes da ABP / CANMAT para transtornos de humor (questão original)',
    TRUE
);

-- -----------------------------------------------------------------------------
-- 10. SIS_INFO — ENG_SOFT (38 questões)
-- -----------------------------------------------------------------------------
INSERT INTO tb_flashcard (subject_id, topic, question_type, question, answer, options_json, explanation, difficulty, source, active)
VALUES
(
    6,
    'Arquitetura de Software - Estilos Arquiteturais',
    'MULTIPLE_CHOICE',
    'No padrão MVC, qual componente recebe a entrada do usuário e coordena a atualização do modelo e a escolha da visão?',
    'B',
    '["A) Model", "B) Controller", "C) Repository", "D) View"]'::jsonb,
    'No MVC, o Model contém dados e regras de negócio, a View apresenta a informação e o Controller trata as ações do usuário, aciona o modelo e seleciona a visão de resposta. Essa separação permite mudar a apresentação sem alterar a regra de negócio.',
    'EASY',
    'Richards e Ford, Fundamentos da Arquitetura de Software (questão original)',
    TRUE
),
(
    6,
    'Arquitetura de Software - Estilos Arquiteturais',
    'MULTIPLE_CHOICE',
    'Em uma arquitetura em camadas fechadas (apresentação, negócio, persistência), a tela de cadastro executa SQL diretamente no banco. Qual é o problema?',
    'A',
    '["A) A apresentação pula a camada de negócio, acoplando a interface ao banco e espalhando regras.", "B) A camada de persistência deveria chamar a camada de apresentação diretamente.", "C) Nenhum, pois camadas fechadas permitem que qualquer camada acesse qualquer outra.", "D) A camada de negócio deveria ficar abaixo da camada de persistência.", "E) O problema é apenas de desempenho, já que o SQL deveria ser executado em lote."]'::jsonb,
    'Em camadas fechadas, cada camada só usa a imediatamente inferior. Quando a interface acessa o banco direto, regras de negócio tendem a ser duplicadas na tela e qualquer mudança no esquema afeta a apresentação, quebrando o isolamento que justifica as camadas.',
    'MEDIUM',
    'Richards e Ford, Fundamentos da Arquitetura de Software (questão original)',
    TRUE
),
(
    6,
    'Arquitetura de Software - Estilos Arquiteturais',
    'MULTIPLE_CHOICE',
    'Qual característica é típica de uma arquitetura de microsserviços?',
    'C',
    '["A) Elimina a necessidade de monitoramento, pois as falhas ficam isoladas.", "B) A aplicação inteira é um único artefato, separado apenas por pacotes.", "C) Cada serviço é implantado de forma independente e é dono dos seus próprios dados.", "D) Os serviços se comunicam apenas por chamadas de método na mesma JVM.", "E) Todos os serviços compartilham um único esquema de banco e são implantados juntos."]'::jsonb,
    'Microsserviços são serviços pequenos, organizados por capacidade de negócio, com implantação independente e banco próprio, comunicando-se pela rede (HTTP, mensageria). O preço é a complexidade de sistema distribuído: latência, falhas parciais e necessidade de observabilidade. Um artefato único é um monolito.',
    'MEDIUM',
    'Richards e Ford, Fundamentos da Arquitetura de Software (questão original)',
    TRUE
),
(
    6,
    'Arquitetura de Software - Estilos Arquiteturais',
    'MULTIPLE_CHOICE',
    'Em uma arquitetura orientada a eventos, o serviço de Pedidos publica ''PedidoCriado'' em um broker, e Estoque e Faturamento consomem o evento de forma assíncrona. Qual consequência deve ser aceita no projeto?',
    'D',
    '["A) Acoplamento temporal: Pedidos só conclui quando Estoque e Faturamento responderem.", "B) Pedidos precisa conhecer o endereço e a interface de cada consumidor.", "C) Transações ACID distribuídas garantidas automaticamente pelo broker.", "D) Consistência eventual: por um intervalo, os serviços podem ter visões diferentes do mesmo pedido.", "E) Impossibilidade de adicionar novos consumidores sem alterar o produtor."]'::jsonb,
    'Com eventos assíncronos, o produtor não conhece os consumidores nem espera por eles, o que reduz o acoplamento e permite incluir novos consumidores sem mudar o produtor. Em troca, cada serviço processa no seu ritmo e o estado converge depois (consistência eventual), exigindo idempotência e tratamento de falhas.',
    'HARD',
    'Richards e Ford, Fundamentos da Arquitetura de Software (questão original)',
    TRUE
),
(
    6,
    'Clean Architecture & SOLID',
    'MULTIPLE_CHOICE',
    'Em projeto de software, qual combinação de coesão e acoplamento é considerada desejável?',
    'C',
    '["A) Alta coesão e alto acoplamento", "B) Baixa coesão e alto acoplamento", "C) Alta coesão e baixo acoplamento", "D) Baixa coesão e baixo acoplamento"]'::jsonb,
    'Alta coesão significa que cada módulo tem responsabilidades fortemente relacionadas; baixo acoplamento significa pouca dependência entre módulos. Juntos facilitam manutenção, teste e reuso, porque uma mudança fica localizada e não se propaga pelo sistema.',
    'EASY',
    'Pressman, Engenharia de Software, 9ª ed. (questão original)',
    TRUE
),
(
    6,
    'Clean Architecture & SOLID',
    'MULTIPLE_CHOICE',
    'A classe RelatorioVendas calcula os totais do mês, gera o PDF formatado e envia o arquivo por e-mail para a diretoria. Qual princípio SOLID ela viola mais diretamente?',
    'B',
    '["A) Princípio da Segregação de Interfaces (ISP)", "B) Princípio da Responsabilidade Única (SRP)", "C) Princípio da Inversão de Dependência (DIP)", "D) Princípio da Substituição de Liskov (LSP)"]'::jsonb,
    'O SRP diz que um módulo deve ter um único motivo para mudar, ou seja, responder a um único ator. Regras de cálculo, layout do PDF e forma de envio mudam por motivos e pessoas diferentes; juntá-los em uma classe faz qualquer alteração arriscar as outras. A correção é separar em classes distintas.',
    'MEDIUM',
    'Robert C. Martin, Clean Architecture (questão original)',
    TRUE
),
(
    6,
    'Clean Architecture & SOLID',
    'MULTIPLE_CHOICE',
    'A interface Multifuncional exige imprimir(), digitalizar() e enviarFax(). A classe ImpressoraSimples só imprime e implementa os outros métodos lançando exceção. Qual princípio está sendo violado?',
    'A',
    '["A) Princípio da Segregação de Interfaces (ISP)", "B) Princípio da Inversão de Dependência (DIP)", "C) Princípio Aberto/Fechado (OCP)", "D) Princípio da Responsabilidade Única (SRP)"]'::jsonb,
    'O ISP afirma que clientes não devem ser forçados a depender de métodos que não usam. A solução é dividir a interface grande em interfaces menores (Impressora, Digitalizador, Fax), e cada classe implementa só o que oferece. Métodos que lançam exceção por não se aplicarem também são sinal de problema de substituição.',
    'MEDIUM',
    'Robert C. Martin, Clean Architecture (questão original)',
    TRUE
),
(
    6,
    'Clean Architecture & SOLID',
    'MULTIPLE_CHOICE',
    'PedidoService cria internamente new PedidoRepositoryMySQL() e, por isso, não pode ser testado sem banco. Qual refatoração aplica corretamente a Inversão de Dependência?',
    'B',
    '["A) Transformar PedidoRepositoryMySQL em Singleton acessado de forma estática.", "B) Fazer PedidoService depender de uma interface PedidoRepository recebida pelo construtor.", "C) Tornar públicos os atributos de PedidoRepositoryMySQL.", "D) Fazer PedidoService herdar de PedidoRepositoryMySQL para reaproveitar seus métodos.", "E) Mover as consultas SQL para dentro do próprio PedidoService."]'::jsonb,
    'Pelo DIP, a regra de negócio (alto nível) depende de uma abstração, e o detalhe de infraestrutura a implementa. Recebendo a interface pelo construtor (injeção de dependência), o serviço fica desacoplado do MySQL e pode receber um dublê em testes. Singleton estático e herança mantêm o acoplamento ao detalhe concreto.',
    'HARD',
    'Robert C. Martin, Clean Architecture (questão original)',
    TRUE
),
(
    6,
    'Clean Architecture & SOLID',
    'MULTIPLE_CHOICE',
    'Na Clean Architecture de Robert C. Martin, o que estabelece a regra de dependência?',
    'D',
    '["A) As entidades de negócio devem conhecer o framework web para validar requisições.", "B) Os casos de uso devem importar as classes do banco de dados para persistir os dados.", "C) A interface com o usuário fica no centro, e o banco de dados envolve todas as camadas.", "D) Dependências de código-fonte apontam apenas para dentro, das camadas externas para as entidades e casos de uso.", "E) Cada camada pode depender livremente de qualquer outra, desde que haja testes."]'::jsonb,
    'A regra de dependência diz que nada em um círculo interno sabe sobre algo de um círculo externo. Entidades e casos de uso não conhecem frameworks, banco ou interface; quando precisam deles, definem interfaces que as camadas externas implementam. Isso mantém a regra de negócio independente de detalhes.',
    'HARD',
    'Robert C. Martin, Clean Architecture (questão original)',
    TRUE
),
(
    6,
    'Design Patterns GoF',
    'MULTIPLE_CHOICE',
    'Na classificação dos padrões GoF, a qual categoria pertencem Adapter, Decorator e Composite?',
    'C',
    '["A) Arquiteturais", "B) Comportamentais", "C) Estruturais", "D) Criacionais"]'::jsonb,
    'O catálogo GoF divide os 23 padrões em criacionais (como Factory Method e Builder), estruturais (como Adapter, Decorator, Composite, Facade e Proxy) e comportamentais (como Observer, Strategy e Command). Padrões estruturais tratam da composição de classes e objetos em estruturas maiores.',
    'EASY',
    'Gamma et al., Padrões de Projeto (GoF) (questão original)',
    TRUE
),
(
    6,
    'Design Patterns GoF',
    'MULTIPLE_CHOICE',
    'Quando o status de um pedido muda, vários módulos (e-mail, estoque, painel) precisam ser avisados, e novos módulos interessados devem poder se inscrever sem alterar a classe Pedido. Qual padrão GoF atende a isso?',
    'A',
    '["A) Observer", "B) Singleton", "C) Prototype", "D) Builder", "E) Facade"]'::jsonb,
    'O Observer define uma dependência um-para-muitos: o sujeito mantém uma lista de observadores e os notifica quando seu estado muda. Novos observadores se registram sem que o sujeito conheça suas classes concretas. Facade apenas simplifica o acesso a um subsistema.',
    'MEDIUM',
    'Gamma et al., Padrões de Projeto (GoF) (questão original)',
    TRUE
),
(
    6,
    'Design Patterns GoF',
    'MULTIPLE_CHOICE',
    'Um sistema espera a interface Pagamento com o método pagar(valor), mas o gateway legado só oferece efetuarTransacao(centavos, moeda). Sem alterar o código legado, qual padrão permite usá-lo?',
    'B',
    '["A) Template Method", "B) Adapter", "C) Composite", "D) Abstract Factory", "E) Observer"]'::jsonb,
    'O Adapter converte a interface de uma classe em outra esperada pelo cliente. A classe adaptadora implementa Pagamento e, internamente, chama efetuarTransacao convertendo os parâmetros. Composite organiza objetos em árvore; Template Method define o esqueleto de um algoritmo.',
    'MEDIUM',
    'Gamma et al., Padrões de Projeto (GoF) (questão original)',
    TRUE
),
(
    6,
    'Design Patterns GoF',
    'MULTIPLE_CHOICE',
    'Um fluxo de dados precisa receber, em tempo de execução e em qualquer combinação, compressão, criptografia e buffer, sem criar uma subclasse para cada combinação. Qual padrão GoF é o mais indicado?',
    'D',
    '["A) Factory Method", "B) Mediator", "C) Singleton", "D) Decorator", "E) Memento"]'::jsonb,
    'O Decorator envolve um objeto com outro que implementa a mesma interface e acrescenta comportamento, permitindo empilhar responsabilidades dinamicamente (buffer sobre criptografia sobre compressão). Usar herança para cada combinação causaria explosão de subclasses.',
    'MEDIUM',
    'Gamma et al., Padrões de Projeto (GoF) (questão original)',
    TRUE
),
(
    6,
    'Design Patterns GoF',
    'MULTIPLE_CHOICE',
    'A classe abstrata GeradorRelatorio tem um método final gerar() que chama, em ordem fixa, buscarDados(), formatar() e exportar(); as subclasses só redefinem esses passos. Qual padrão foi aplicado?',
    'A',
    '["A) Template Method", "B) Strategy", "C) Chain of Responsibility", "D) Bridge", "E) State"]'::jsonb,
    'O Template Method define o esqueleto de um algoritmo em uma superclasse e deixa subclasses redefinirem passos sem mudar a estrutura, usando herança. O Strategy, que é a confusão mais comum, encapsula o algoritmo inteiro em um objeto separado e intercambiável via composição.',
    'HARD',
    'Gamma et al., Padrões de Projeto (GoF) (questão original)',
    TRUE
),
(
    6,
    'DevOps - Versionamento e Integração Contínua',
    'MULTIPLE_CHOICE',
    'O que caracteriza a prática de integração contínua (CI)?',
    'C',
    '["A) Juntar o trabalho de todos apenas no fim do projeto, em uma grande integração.", "B) Publicar automaticamente em produção todo código sem executar testes.", "C) Integrar o código ao ramo principal com frequência, com build e testes automatizados a cada integração.", "D) Testar manualmente o sistema uma vez por mês em ambiente de homologação.", "E) Manter cada desenvolvedor em um ramo próprio por meses para evitar conflitos."]'::jsonb,
    'Na integração contínua, os desenvolvedores integram pequenas mudanças várias vezes ao dia, e um servidor de CI compila e roda os testes automaticamente, dando retorno rápido sobre quebras. Ramos longos e integração tardia geram conflitos grandes e defeitos descobertos tarde.',
    'EASY',
    'Humble e Farley, Entrega Contínua; SemVer 2.0.0 (questão original)',
    TRUE
),
(
    6,
    'DevOps - Versionamento e Integração Contínua',
    'MULTIPLE_CHOICE',
    'Uma biblioteca segue o Versionamento Semântico (SemVer) e está na versão 2.4.1. A nova versão remove um método público usado pelos clientes. Qual deve ser o número da nova versão?',
    'A',
    '["A) 3.0.0", "B) 2.4.2", "C) 3.4.1", "D) 2.5.0", "E) 2.5.1"]'::jsonb,
    'No SemVer (MAIOR.MENOR.CORREÇÃO), mudanças incompatíveis na API pública incrementam a versão maior e zeram as demais. Funcionalidade nova compatível incrementa a menor (2.5.0) e correção compatível incrementa a de correção (2.4.2). Remover um método público quebra os clientes.',
    'MEDIUM',
    'Humble e Farley, Entrega Contínua; SemVer 2.0.0 (questão original)',
    TRUE
),
(
    6,
    'DevOps - Versionamento e Integração Contínua',
    'MULTIPLE_CHOICE',
    'Qual é a diferença entre entrega contínua (continuous delivery) e implantação contínua (continuous deployment)?',
    'D',
    '["A) A entrega contínua publica automaticamente em produção; a implantação contínua exige aprovação manual.", "B) A implantação contínua só compila o código, enquanto a entrega contínua também o testa.", "C) A entrega contínua dispensa testes automatizados; a implantação contínua os exige.", "D) Na entrega contínua o código está sempre pronto para produção, mas a liberação é uma decisão manual; na implantação contínua, toda mudança aprovada no pipeline vai automaticamente para produção.", "E) São sinônimos; os dois termos descrevem a mesma prática de integração."]'::jsonb,
    'Ambas dependem de um pipeline automatizado com testes. Na entrega contínua, cada versão aprovada fica implantável e a ida para produção é acionada por uma decisão de negócio. Na implantação contínua, essa última etapa também é automática. A opção que inverte os conceitos é o distrator mais comum.',
    'HARD',
    'Humble e Farley, Entrega Contínua; SemVer 2.0.0 (questão original)',
    TRUE
),
(
    6,
    'Engenharia de Requisitos - Requisitos e Histórias de Usuário',
    'MULTIPLE_CHOICE',
    'Em um sistema de agendamento de consultas, qual requisito é classificado como não funcional?',
    'A',
    '["A) O sistema deve responder a 95% das buscas de horários em até 2 segundos.", "B) O sistema deve enviar um lembrete ao paciente um dia antes da consulta.", "C) O sistema deve permitir que o paciente cancele uma consulta agendada.", "D) O sistema deve listar os horários livres de cada médico."]'::jsonb,
    'Requisitos não funcionais descrevem qualidades ou restrições do sistema (desempenho, segurança, usabilidade). O tempo de resposta é um requisito de desempenho. Cancelar, lembrar e listar horários são funções que o sistema executa, portanto requisitos funcionais.',
    'EASY',
    'Sommerville, Engenharia de Software, 10ª ed. (questão original)',
    TRUE
),
(
    6,
    'Engenharia de Requisitos - Requisitos e Histórias de Usuário',
    'MULTIPLE_CHOICE',
    'Qual formato é o mais usado para escrever uma história de usuário?',
    'C',
    '["A) Caso de uso <nome>: ator principal, pré-condições e fluxo alternativo.", "B) Se <condição>, então o sistema executa <ação>, senão exibe <erro>.", "C) Como <tipo de usuário>, quero <objetivo>, para <benefício>.", "D) O sistema deve <função> utilizando <tecnologia> no banco <nome>."]'::jsonb,
    'A história de usuário descreve uma necessidade sob a perspectiva de quem usa: quem quer, o que quer e por que quer. Ela é curta e serve de lembrete para uma conversa, com detalhes registrados nos critérios de aceitação. Especificar tecnologia ou fluxo completo de caso de uso foge desse propósito.',
    'EASY',
    'Mike Cohn, User Stories Applied (questão original)',
    TRUE
),
(
    6,
    'Engenharia de Requisitos - Requisitos e Histórias de Usuário',
    'MULTIPLE_CHOICE',
    'No acrônimo INVEST, usado para avaliar histórias de usuário, qual característica indica que deve ser possível verificar objetivamente se a história foi atendida?',
    'B',
    '["A) Independente", "B) Testável", "C) Negociável", "D) Pequena", "E) Valiosa"]'::jsonb,
    'Uma história testável possui critérios claros que permitem dizer se ela está pronta, como ''a busca retorna em até 2 segundos''. Negociável significa que os detalhes são combinados em conversa; independente, que não depende de outras; valiosa, que gera valor ao usuário; pequena, que cabe em uma iteração.',
    'MEDIUM',
    'Mike Cohn, User Stories Applied (questão original)',
    TRUE
),
(
    6,
    'Engenharia de Requisitos - Requisitos e Histórias de Usuário',
    'MULTIPLE_CHOICE',
    'Um critério de aceitação foi escrito no formato Dado/Quando/Então: ''Dado que o carrinho tem itens, Quando o cliente aplica o cupom VALE10, Então...''. O que deve vir após o ''Então''?',
    'D',
    '["A) A pré-condição do cenário, como o cliente estar autenticado.", "B) O nome do desenvolvedor responsável pela implementação.", "C) A justificativa de negócio da história, como aumentar as vendas.", "D) O resultado observável esperado, como o desconto de 10% aplicado ao total.", "E) A ação disparada pelo usuário, como clicar em finalizar compra."]'::jsonb,
    'No formato Dado/Quando/Então (Given/When/Then, usado no BDD), ''Dado'' descreve o contexto ou pré-condição, ''Quando'' descreve a ação ou evento e ''Então'' descreve o resultado esperado e verificável. A justificativa de negócio fica na própria história (''para...'').',
    'MEDIUM',
    'North, Introducing BDD; Gherkin (questão original)',
    TRUE
),
(
    6,
    'Engenharia de Requisitos - Requisitos e Histórias de Usuário',
    'MULTIPLE_CHOICE',
    'O cliente pediu: ''o aplicativo deve ser fácil de usar''. Qual reescrita torna esse requisito não funcional verificável?',
    'D',
    '["A) A equipe deve se esforçar ao máximo para que o aplicativo seja simples.", "B) O aplicativo deve ser desenvolvido com um framework de interface reconhecido.", "C) O aplicativo deve seguir as melhores práticas de usabilidade do mercado.", "D) Usuários novos devem concluir um agendamento em até 3 minutos, sem ajuda, em 90% dos testes de usabilidade.", "E) O aplicativo deve ter uma interface moderna, intuitiva e agradável para todos os usuários."]'::jsonb,
    'Requisitos não funcionais vagos não podem ser testados. A versão correta define métrica (tempo de conclusão), condição (usuário novo, sem ajuda) e meta (90% dos testes), permitindo verificar. As demais continuam subjetivas (''intuitiva'', ''melhores práticas'') ou prescrevem tecnologia em vez de qualidade mensurável.',
    'HARD',
    'Sommerville, Engenharia de Software, 10ª ed. (questão original)',
    TRUE
),
(
    6,
    'Processos de Software - Modelos de Processo',
    'MULTIPLE_CHOICE',
    'Qual é uma característica do modelo cascata (waterfall)?',
    'A',
    '["A) As fases são executadas em sequência, e mudanças de requisito tardias costumam ser caras.", "B) O software é entregue em pequenos incrementos a cada duas semanas.", "C) Requisitos, código e testes são feitos simultaneamente pela mesma pessoa.", "D) Não há fase de levantamento de requisitos, que surgem durante a codificação.", "E) Cada ciclo começa obrigatoriamente por uma análise de riscos com protótipo."]'::jsonb,
    'No cascata, requisitos, projeto, implementação, testes e implantação ocorrem em fases sequenciais, cada uma partindo da anterior concluída. Por isso funciona melhor com requisitos estáveis e torna caro absorver mudanças tardias. Entregas curtas são típicas de processos iterativos e ágeis; análise de risco a cada ciclo é marca do espiral.',
    'EASY',
    'Sommerville, Engenharia de Software, 10ª ed. (questão original)',
    TRUE
),
(
    6,
    'Processos de Software - Modelos de Processo',
    'MULTIPLE_CHOICE',
    'Qual modelo de processo, proposto por Boehm, organiza o desenvolvimento em ciclos que começam pela análise e redução de riscos?',
    'B',
    '["A) Kanban", "B) Modelo espiral", "C) Modelo cascata", "D) Modelo em V", "E) Scrum"]'::jsonb,
    'O modelo espiral de Boehm organiza o projeto em voltas; em cada uma definem-se objetivos, avaliam-se e reduzem-se os riscos (por exemplo, com protótipos), desenvolve-se e planeja-se a próxima volta. O modelo em V associa cada fase de desenvolvimento a um nível de teste, mas não é orientado a riscos.',
    'MEDIUM',
    'Pressman, Engenharia de Software, 9ª ed. (questão original)',
    TRUE
),
(
    6,
    'Processos de Software - Modelos de Processo',
    'MULTIPLE_CHOICE',
    'Qual frase NÃO corresponde a um dos valores do Manifesto Ágil?',
    'C',
    '["A) Colaboração com o cliente mais que negociação de contratos.", "B) Software em funcionamento mais que documentação abrangente.", "C) Processos e ferramentas mais que indivíduos e interações.", "D) Responder a mudanças mais que seguir um plano."]'::jsonb,
    'O Manifesto Ágil valoriza indivíduos e interações mais que processos e ferramentas; a frase que coloca processos acima das pessoas inverte esse valor. As outras três reproduzem valores do manifesto. Os itens da direita continuam tendo valor, apenas menos que os da esquerda.',
    'MEDIUM',
    'Manifesto para Desenvolvimento Ágil de Software, 2001 (questão original)',
    TRUE
),
(
    6,
    'Processos de Software - Modelos de Processo',
    'MULTIPLE_CHOICE',
    'No Processo Unificado (UP), iterativo e incremental, em qual fase o objetivo principal é estabelecer uma arquitetura estável (linha de base arquitetural) e mitigar os maiores riscos técnicos?',
    'D',
    '["A) Construção", "B) Transição", "C) Concepção", "D) Elaboração"]'::jsonb,
    'O UP tem quatro fases: Concepção (visão e viabilidade), Elaboração (requisitos principais, arquitetura de base e redução dos riscos críticos), Construção (desenvolvimento da maior parte das funcionalidades) e Transição (implantação para os usuários). Cada fase contém várias iterações.',
    'HARD',
    'Jacobson, Booch e Rumbaugh, O Processo Unificado (questão original)',
    TRUE
),
(
    6,
    'Test-Driven Development (TDD)',
    'MULTIPLE_CHOICE',
    'No TDD, o desenvolvedor escreveu um teste novo e o viu falhar. Qual é o próximo passo?',
    'D',
    '["A) Escrever todos os demais testes da funcionalidade antes de codificar.", "B) Enviar o código para produção e observar o comportamento real.", "C) Apagar o teste, pois testes que falham indicam erro de especificação.", "D) Escrever o código mínimo de produção que faça esse teste passar.", "E) Refatorar todo o sistema antes de escrever qualquer código novo."]'::jsonb,
    'O ciclo do TDD é: escrever um teste que falha (vermelho), escrever o mínimo de código para que ele passe (verde) e então refatorar mantendo os testes verdes. Escrever todos os testes antes de codificar ou refatorar sem testes passando quebra o ritmo de pequenos passos.',
    'EASY',
    'Kent Beck, TDD by Example (questão original)',
    TRUE
),
(
    6,
    'Test-Driven Development (TDD)',
    'MULTIPLE_CHOICE',
    'Qual é o objetivo da etapa de refatoração no ciclo do TDD?',
    'C',
    '["A) Adicionar novas funcionalidades que ainda não têm testes.", "B) Otimizar o desempenho, mesmo que alguns testes passem a falhar.", "C) Melhorar a estrutura do código, removendo duplicação, sem alterar o comportamento verificado pelos testes.", "D) Aumentar a cobertura escrevendo testes para código legado.", "E) Corrigir o teste que está falhando para que ele passe."]'::jsonb,
    'Refatorar é mudar a estrutura interna sem mudar o comportamento externo. No TDD isso é feito com todos os testes passando, o que dá segurança para eliminar duplicação e melhorar nomes e design. Funcionalidade nova só entra por meio de um novo teste vermelho.',
    'MEDIUM',
    'Kent Beck, TDD by Example (questão original)',
    TRUE
),
(
    6,
    'Test-Driven Development (TDD)',
    'MULTIPLE_CHOICE',
    'Por que o TDD recomenda ver o teste novo falhar antes de escrever o código de produção?',
    'A',
    '["A) Para confirmar que o teste realmente verifica o comportamento e não passaria por engano.", "B) Porque testes que nunca falharam não entram no cálculo de cobertura.", "C) Para garantir que o banco de dados de teste foi criado corretamente.", "D) Para medir o tempo de execução do teste antes da implementação.", "E) Porque a ferramenta de build só registra testes que já falharam uma vez."]'::jsonb,
    'Um teste que passa sem o código existir pode estar mal escrito (sem asserção, testando a coisa errada ou nunca executado). Ver o vermelho primeiro prova que o teste é capaz de detectar a ausência do comportamento, e o verde seguinte passa a ter significado.',
    'HARD',
    'Kent Beck, TDD by Example (questão original)',
    TRUE
),
(
    6,
    'Testes de Software - Níveis, Tipos e Dublês de Teste',
    'MULTIPLE_CHOICE',
    'Na pirâmide de testes, qual tipo de teste deve existir em maior quantidade, por ser rápido e barato?',
    'C',
    '["A) Testes manuais exploratórios", "B) Testes ponta a ponta pela interface", "C) Testes de unidade", "D) Testes de aceitação com o cliente"]'::jsonb,
    'A pirâmide de testes propõe uma base larga de testes de unidade (rápidos, isolados e baratos), uma camada intermediária de testes de integração e poucos testes ponta a ponta no topo, que são lentos e frágeis. Inverter essa proporção deixa a suíte lenta e cara de manter.',
    'EASY',
    'Mike Cohn, Succeeding with Agile; Fowler, Test Pyramid (questão original)',
    TRUE
),
(
    6,
    'Testes de Software - Níveis, Tipos e Dublês de Teste',
    'MULTIPLE_CHOICE',
    'Um teste de unidade precisa confirmar que, ao finalizar uma compra, EmailService.enviar() foi chamado exatamente uma vez com o e-mail do cliente. Qual dublê de teste é o adequado?',
    'B',
    '["A) Stub", "B) Mock", "C) Dummy", "D) Fake"]'::jsonb,
    'O mock é configurado com expectativas e verifica as interações, ou seja, se um método foi chamado, quantas vezes e com quais argumentos. O stub só devolve respostas pré-programadas, sem verificar chamadas; o dummy só preenche parâmetros; o fake é uma implementação funcional simplificada.',
    'MEDIUM',
    'ISTQB Foundation Level Syllabus e Meszaros, xUnit Test Patterns (questão original)',
    TRUE
),
(
    6,
    'Testes de Software - Níveis, Tipos e Dublês de Teste',
    'MULTIPLE_CHOICE',
    'Após corrigir um defeito no cálculo de juros, a equipe reexecuta a suíte de testes existente para garantir que outras funções não foram afetadas. Que tipo de teste é esse?',
    'C',
    '["A) Teste de fumaça de instalação", "B) Teste de aceitação do usuário", "C) Teste de regressão", "D) Teste de usabilidade", "E) Teste de carga"]'::jsonb,
    'O teste de regressão verifica se mudanças no código (correções ou novas funções) não introduziram defeitos em partes que já funcionavam. Por ser repetido a cada mudança, é o principal candidato à automação. Teste de carga avalia desempenho sob volume; aceitação valida com o usuário.',
    'MEDIUM',
    'ISTQB Foundation Level Syllabus e Meszaros, xUnit Test Patterns (questão original)',
    TRUE
),
(
    6,
    'Testes de Software - Níveis, Tipos e Dublês de Teste',
    'MULTIPLE_CHOICE',
    'Um campo aceita idades de 18 a 60 anos, inclusive. Usando análise de valor limite com dois valores por fronteira, quais valores devem ser testados?',
    'A',
    '["A) 17, 18, 60 e 61", "B) 0, 18, 60 e 100", "C) 18, 39 e 60", "D) 18 e 60", "E) 19, 20, 58 e 59"]'::jsonb,
    'A análise de valor limite foca as fronteiras das partições, onde defeitos como usar ''>'' no lugar de ''>='' são comuns. Com dois valores por fronteira testa-se o limite e o vizinho imediatamente fora: 17 e 18 na fronteira inferior, 60 e 61 na superior. Testar só 18 e 60 não detecta a fronteira aberta.',
    'MEDIUM',
    'ISTQB Foundation Level Syllabus e Meszaros, xUnit Test Patterns (questão original)',
    TRUE
),
(
    6,
    'Testes de Software - Níveis, Tipos e Dublês de Teste',
    'MULTIPLE_CHOICE',
    'Para testar um serviço sem banco real, a equipe cria RepositorioEmMemoria, que guarda e busca objetos em um HashMap com comportamento funcional, mas simplificado. Como Meszaros classifica esse dublê?',
    'D',
    '["A) Spy", "B) Dummy", "C) Mock", "D) Fake", "E) Stub"]'::jsonb,
    'O fake é uma implementação que funciona de verdade, mas usa um atalho inadequado para produção, como um repositório em memória. O stub só devolve respostas fixas; o mock verifica interações esperadas; o spy registra as chamadas para conferência posterior; o dummy apenas preenche parâmetros não usados.',
    'HARD',
    'ISTQB Foundation Level Syllabus e Meszaros, xUnit Test Patterns (questão original)',
    TRUE
),
(
    6,
    'UML - Diagramas de Casos de Uso, Classes e Sequência',
    'MULTIPLE_CHOICE',
    'Qual diagrama UML representa os atores e as funcionalidades que o sistema oferece a eles, sem detalhar a ordem das mensagens?',
    'B',
    '["A) Diagrama de sequência", "B) Diagrama de casos de uso", "C) Diagrama de classes", "D) Diagrama de implantação"]'::jsonb,
    'O diagrama de casos de uso mostra quem interage com o sistema (atores) e quais objetivos o sistema atende (casos de uso), dando uma visão funcional de alto nível. O de sequência mostra a troca de mensagens no tempo; o de classes, a estrutura estática; o de implantação, nós físicos.',
    'EASY',
    'OMG UML 2.5 e Booch, Rumbaugh e Jacobson (questão original)',
    TRUE
),
(
    6,
    'UML - Diagramas de Casos de Uso, Classes e Sequência',
    'MULTIPLE_CHOICE',
    'Em um diagrama de casos de uso, ''Realizar Saque'' sempre executa ''Autenticar Cliente'', e só às vezes executa ''Imprimir Comprovante'', se o cliente pedir. Quais relacionamentos são usados, respectivamente?',
    'B',
    '["A) include para ambos, pois os dois ocorrem no saque", "B) include para autenticar e extend para imprimir comprovante", "C) associação simples para ambos, sem estereótipo", "D) extend para autenticar e include para imprimir comprovante", "E) generalização para ambos os casos de uso"]'::jsonb,
    'O include indica comportamento obrigatório, sempre incorporado pelo caso de uso base (o saque sempre autentica). O extend indica comportamento opcional ou condicional, acionado em um ponto de extensão (imprimir só se pedido). Trocar os dois inverte o sentido de obrigatoriedade.',
    'MEDIUM',
    'OMG UML 2.5 e Booch, Rumbaugh e Jacobson (questão original)',
    TRUE
),
(
    6,
    'UML - Diagramas de Casos de Uso, Classes e Sequência',
    'MULTIPLE_CHOICE',
    'No diagrama de classes, Pedido e ItemPedido estão ligados por um losango preenchido do lado de Pedido. O que isso significa?',
    'D',
    '["A) Agregação: os itens podem existir independentemente do pedido.", "B) Herança: ItemPedido é uma especialização de Pedido.", "C) Realização: Pedido implementa a interface ItemPedido.", "D) Composição: os itens não existem sem o pedido e são destruídos junto com ele.", "E) Dependência: Pedido apenas usa ItemPedido como parâmetro de método."]'::jsonb,
    'O losango preenchido indica composição, uma relação todo-parte forte em que a parte pertence a um único todo e tem o ciclo de vida ligado a ele. O losango vazio indica agregação, em que a parte pode existir sem o todo. Herança usa seta de triângulo vazado.',
    'MEDIUM',
    'OMG UML 2.5 e Booch, Rumbaugh e Jacobson (questão original)',
    TRUE
),
(
    6,
    'UML - Diagramas de Casos de Uso, Classes e Sequência',
    'MULTIPLE_CHOICE',
    'Em um diagrama de sequência, a mensagem de pagamento deve seguir dois caminhos alternativos e mutuamente exclusivos: ''aprovado'' ou ''recusado''. Qual fragmento combinado representa isso?',
    'A',
    '["A) alt", "B) loop", "C) ref", "D) par", "E) opt"]'::jsonb,
    'O fragmento alt divide o trecho em operandos com condições de guarda e apenas um deles é executado, como um if/else. O opt tem um único operando, executado ou não; loop repete; par executa operandos em paralelo; ref referencia outra interação.',
    'HARD',
    'OMG UML 2.5 e Booch, Rumbaugh e Jacobson (questão original)',
    TRUE
);

-- -----------------------------------------------------------------------------
-- 11. SIS_INFO — BD_PERSIST (38 questões)
-- -----------------------------------------------------------------------------
INSERT INTO tb_flashcard (subject_id, topic, question_type, question, answer, options_json, explanation, difficulty, source, active)
VALUES
(
    7,
    'Modelagem Conceitual - Modelo Entidade-Relacionamento',
    'MULTIPLE_CHOICE',
    'Num sistema acadêmico, um aluno pode se matricular em várias disciplinas e cada disciplina recebe vários alunos. Como esse relacionamento N:N costuma ser implementado no modelo relacional?',
    'B',
    '["A) Com uma chave estrangeira para disciplina dentro da tabela de alunos", "B) Com uma tabela associativa contendo as chaves estrangeiras de aluno e de disciplina, que juntas formam a chave primária", "C) Com uma chave estrangeira para aluno dentro da tabela de disciplinas", "D) Com uma coluna em aluno que guarda a lista de códigos das disciplinas separados por vírgula"]'::jsonb,
    'Relacionamentos N:N viram uma tabela associativa (ex.: matricula) com as duas FKs. Uma única FK em qualquer lado só representa 1:N, e a lista em uma coluna viola a 1FN.',
    'EASY',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Modelagem Conceitual - Modelo Entidade-Relacionamento',
    'MULTIPLE_CHOICE',
    'Em um modelo ER, cada Dependente só é identificado pelo seu nome combinado com a matrícula do Funcionário ao qual pertence; sem o funcionário, o dependente não existe. Como Dependente é classificado?',
    'A',
    '["A) Entidade fraca, com relacionamento identificador e chave parcial (nome)", "B) Entidade associativa resultante de um relacionamento N:N", "C) Especialização (subclasse) da entidade Funcionário", "D) Atributo composto da entidade Funcionário"]'::jsonb,
    'Entidade fraca não tem chave própria suficiente: é identificada pela chave do dono mais uma chave parcial, por meio de um relacionamento identificador. Não é subclasse, pois um dependente não é um funcionário.',
    'MEDIUM',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Modelagem Conceitual - Modelo Entidade-Relacionamento',
    'MULTIPLE_CHOICE',
    'Regra de negócio: todo pedido pertence a exatamente um cliente, e um cliente pode ter zero ou muitos pedidos. Qual implementação relacional representa fielmente essa regra?',
    'A',
    '["A) Coluna cliente_id em pedido, como chave estrangeira declarada NOT NULL", "B) Coluna pedido_id em cliente, como chave estrangeira declarada NOT NULL", "C) Coluna cliente_id em pedido, como chave estrangeira que aceita NULL", "D) Tabela associativa cliente_pedido com restrição UNIQUE em cliente_id"]'::jsonb,
    'Em 1:N a FK fica no lado N (pedido). NOT NULL impõe a participação total do pedido (sempre tem cliente). Aceitar NULL permitiria pedido sem cliente, e UNIQUE em cliente_id limitaria cada cliente a um pedido.',
    'MEDIUM',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Modelo Relacional - Chaves e Integridade Referencial',
    'MULTIPLE_CHOICE',
    'A tabela usuario tem as colunas id, cpf e email, todas únicas e não nulas, e id foi escolhida como chave primária. Como se classificam cpf e email?',
    'B',
    '["A) Chaves estrangeiras, pois identificam o usuário em outras tabelas", "B) Chaves candidatas não escolhidas (chaves alternativas), normalmente declaradas com UNIQUE", "C) Superchaves não mínimas, por isso não podem ser chaves candidatas", "D) Chaves parciais, típicas de entidades fracas"]'::jsonb,
    'Cada uma identifica unicamente a linha e é mínima (um único atributo), logo é chave candidata. As que não viram PK são chaves alternativas e recebem UNIQUE NOT NULL. Não referenciam outra tabela, então não são FKs.',
    'EASY',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Modelo Relacional - Chaves e Integridade Referencial',
    'MULTIPLE_CHOICE',
    'A coluna item_pedido.pedido_id é chave estrangeira para pedido(id), declarada com ON DELETE CASCADE. O que acontece ao excluir um pedido que possui 3 itens?',
    'D',
    '["A) A exclusão falha por violação de integridade referencial", "B) O pedido é excluído e os itens ficam com pedido_id igual a NULL", "C) Só o pedido é excluído e os itens permanecem apontando para ele", "D) O pedido e seus 3 itens são excluídos na mesma operação"]'::jsonb,
    'CASCADE propaga a exclusão para as linhas que referenciam o pedido. Falhar é o comportamento de RESTRICT/NO ACTION, e anular a FK é o de SET NULL. Itens órfãos nunca são permitidos com a FK ativa.',
    'MEDIUM',
    'Documentação oficial do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'Modelo Relacional - Chaves e Integridade Referencial',
    'MULTIPLE_CHOICE',
    'No PostgreSQL, uma FK simples (uma só coluna, sem NOT NULL, com o MATCH SIMPLE padrão) recebe o valor NULL em um INSERT. O que acontece?',
    'D',
    '["A) A linha é rejeitada, porque toda FK precisa apontar para uma linha existente", "B) A linha só é aceita se a tabela referenciada tiver uma linha com chave primária nula", "C) O SGBD substitui o NULL pelo menor valor de chave primária da tabela referenciada", "D) A linha é aceita, pois a restrição de chave estrangeira não é verificada quando o valor da FK é nulo"]'::jsonb,
    'Pelo SQL padrão, FK com valor nulo satisfaz a restrição; para obrigar o vínculo é preciso NOT NULL. Chave primária nunca pode ser nula, então não existe linha referenciada com PK nula.',
    'HARD',
    'Padrão ISO/IEC 9075 SQL e documentação do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'NoSQL - Modelos de Dados e Teorema CAP',
    'MULTIPLE_CHOICE',
    'Uma aplicação precisa guardar sessões de usuário acessadas exclusivamente por um identificador, com latência muito baixa e expiração automática (TTL). Qual modelo NoSQL é o mais adequado?',
    'C',
    '["A) Orientado a grafos", "B) Família de colunas (wide-column)", "C) Chave-valor", "D) Orientado a documentos com agregações complexas"]'::jsonb,
    'O acesso é sempre pela chave e o valor é opaco, o caso típico de bancos chave-valor em memória como o Redis, que oferecem TTL nativo. Grafos servem a travessias de relacionamentos.',
    'EASY',
    'Sadalage e Fowler, NoSQL Essencial (questão original)',
    TRUE
),
(
    7,
    'NoSQL - Modelos de Dados e Teorema CAP',
    'MULTIPLE_CHOICE',
    'Uma rede social quer recomendar ''amigos de amigos'' e encontrar caminhos curtos entre usuários, com consultas de profundidade variável. Qual modelo NoSQL atende melhor?',
    'C',
    '["A) Chave-valor", "B) Orientado a documentos", "C) Orientado a grafos", "D) Família de colunas (wide-column)"]'::jsonb,
    'Bancos de grafos armazenam nós e arestas de forma explícita e percorrem relacionamentos sem junções custosas, o que favorece travessias de vários níveis. Nos outros modelos, cada salto exigiria consultas extras na aplicação.',
    'MEDIUM',
    'Sadalage e Fowler, NoSQL Essencial (questão original)',
    TRUE
),
(
    7,
    'NoSQL - Modelos de Dados e Teorema CAP',
    'MULTIPLE_CHOICE',
    'Um catálogo de produtos tem atributos muito variáveis entre categorias. Cada produto é lido inteiro como uma unidade, mas também é preciso consultar por campos internos com índices secundários. Qual modelo NoSQL é o mais indicado?',
    'A',
    '["A) Orientado a documentos", "B) Chave-valor", "C) Orientado a grafos", "D) Família de colunas (wide-column)"]'::jsonb,
    'Documentos (como JSON no MongoDB) armazenam o agregado completo, aceitam esquemas flexíveis e permitem consultar e indexar campos internos. No chave-valor, o valor é opaco e só se consulta pela chave.',
    'MEDIUM',
    'Sadalage e Fowler, NoSQL Essencial (questão original)',
    TRUE
),
(
    7,
    'NoSQL - Modelos de Dados e Teorema CAP',
    'MULTIPLE_CHOICE',
    'Durante uma partição de rede, um banco distribuído continua aceitando leituras e escritas nos dois lados e reconcilia as divergências depois (consistência eventual). Pelo teorema CAP, o que ele prioriza?',
    'B',
    '["A) Consistência e tolerância a partição (CP), abrindo mão da disponibilidade", "B) Disponibilidade e tolerância a partição (AP), abrindo mão da consistência forte", "C) Consistência e disponibilidade (CA), sem tolerar partições", "D) Consistência forte e disponibilidade ao mesmo tempo, graças à reconciliação"]'::jsonb,
    'Responder nos dois lados durante a partição é escolher disponibilidade; como as réplicas podem divergir, a consistência forte é sacrificada. Um sistema CP recusaria operações em um dos lados para não divergir.',
    'HARD',
    'Sadalage e Fowler, NoSQL Essencial (questão original)',
    TRUE
),
(
    7,
    'Normalização - Formas Normais e Dependências Funcionais',
    'MULTIPLE_CHOICE',
    'A tabela cliente tem a coluna telefones com valores como ''3499-1111, 3499-2222''. Qual forma normal é violada diretamente por esse desenho?',
    'A',
    '["A) Primeira Forma Normal (1FN)", "B) Segunda Forma Normal (2FN)", "C) Terceira Forma Normal (3FN)", "D) Forma Normal de Boyce-Codd (FNBC)"]'::jsonb,
    'A 1FN exige atributos atômicos, sem grupos repetidos ou listas em uma coluna. A solução é uma tabela telefone com FK para cliente. 2FN, 3FN e FNBC tratam de dependências funcionais e pressupõem a 1FN.',
    'EASY',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Normalização - Formas Normais e Dependências Funcionais',
    'MULTIPLE_CHOICE',
    'A tabela item_pedido(pedido_id, produto_id, quantidade, nome_produto) tem chave primária composta (pedido_id, produto_id). Qual é o problema de normalização?',
    'D',
    '["A) quantidade tem dependência transitiva, o que viola a 3FN", "B) A chave primária composta, por si só, viola a 1FN", "C) Nenhum: a tabela já está na FNBC", "D) nome_produto depende só de produto_id, uma dependência parcial que viola a 2FN"]'::jsonb,
    'Na 2FN, todo atributo não chave deve depender da chave inteira. nome_produto depende apenas de parte dela (produto_id) e deve ir para a tabela produto. quantidade depende do par completo, o que está correto.',
    'MEDIUM',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Normalização - Formas Normais e Dependências Funcionais',
    'MULTIPLE_CHOICE',
    'Na relação R(W, X, Y, Z), valem as dependências funcionais W -> X, X -> Y e Y -> Z. O que se conclui ao calcular o fecho de W?',
    'A',
    '["A) W+ = {W, X, Y, Z}, logo W é chave candidata de R", "B) W+ = {W, X}, logo W não é chave de R", "C) W+ = {W, X, Y}, logo é preciso o par {W, Z} como chave", "D) W+ = {W, X, Y, Z}, mas W não pode ser chave porque Z depende de W só por transitividade"]'::jsonb,
    'Pela transitividade (axiomas de Armstrong), W determina X, depois Y, depois Z: W+ contém todos os atributos e W é mínimo, então é chave candidata. Depender por transitividade não impede W de ser chave, mas indica violação da 3FN.',
    'MEDIUM',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Normalização - Formas Normais e Dependências Funcionais',
    'MULTIPLE_CHOICE',
    'Em aula(aluno, disciplina, professor), valem {aluno, disciplina} -> professor e professor -> disciplina (cada professor leciona uma só disciplina). As chaves candidatas são {aluno, disciplina} e {aluno, professor}. Qual afirmação é correta?',
    'C',
    '["A) A relação não está na 2FN, pois professor depende parcialmente da chave", "B) A relação está na FNBC, pois todos os atributos fazem parte de alguma chave candidata", "C) A relação está na 3FN, mas não na FNBC, pois professor determina disciplina sem ser superchave", "D) A relação não está na 1FN, pois tem duas chaves candidatas"]'::jsonb,
    'Na FNBC, todo determinante deve ser superchave; professor não é. Já a 3FN aceita X -> Y quando Y é atributo primo, e disciplina pertence a uma chave candidata. Ter atributos primos não basta para a FNBC.',
    'HARD',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Propriedades ACID',
    'MULTIPLE_CHOICE',
    'Numa transferência bancária, o débito na conta de origem foi executado, mas o crédito na conta de destino falhou. O SGBD desfaz o débito, e nada da transação permanece. Qual propriedade ACID foi garantida?',
    'A',
    '["A) Atomicidade", "B) Durabilidade", "C) Isolamento", "D) Consistência"]'::jsonb,
    'Atomicidade é o ''tudo ou nada'': ou todas as operações da transação são efetivadas, ou nenhuma. Durabilidade trata de manter o que já recebeu commit, e Isolamento trata da interferência entre transações concorrentes.',
    'EASY',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Propriedades ACID',
    'MULTIPLE_CHOICE',
    'Duas transações executam ao mesmo tempo, e o resultado final deve ser o mesmo de executá-las uma após a outra, sem que uma veja estados intermediários da outra. Qual propriedade ACID descreve essa garantia?',
    'C',
    '["A) Atomicidade", "B) Durabilidade", "C) Isolamento", "D) Consistência"]'::jsonb,
    'Isolamento controla a interferência entre transações concorrentes; em sua forma mais forte (serializabilidade), o efeito equivale a alguma execução serial. Consistência é preservar as restrições de integridade, e Atomicidade é o ''tudo ou nada''.',
    'EASY',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Propriedades ACID',
    'MULTIPLE_CHOICE',
    'Qual mecanismo o PostgreSQL usa principalmente para garantir a Durabilidade de uma transação confirmada, mesmo que o servidor caia logo após o COMMIT?',
    'A',
    '["A) O log de escrita antecipada (WAL), gravado em disco antes de o COMMIT ser confirmado", "B) O bloqueio em duas fases (2PL) das linhas alteradas", "C) Os índices B-tree das tabelas modificadas", "D) O cache de páginas em memória compartilhada (shared buffers)"]'::jsonb,
    'O WAL registra as alterações e é descarregado em armazenamento persistente no commit; após uma queda, o banco refaz as alterações a partir do log. Bloqueios servem ao isolamento, e o cache em memória se perde em uma falha.',
    'MEDIUM',
    'Documentação oficial do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - DDL, DML e Agregação com GROUP BY',
    'MULTIPLE_CHOICE',
    'Qual destes comandos SQL pertence à DDL (linguagem de definição de dados)?',
    'A',
    '["A) ALTER TABLE", "B) UPDATE", "C) INSERT", "D) DELETE"]'::jsonb,
    'DDL define ou altera a estrutura (CREATE, ALTER, DROP, TRUNCATE). UPDATE, INSERT e DELETE manipulam linhas, portanto são DML.',
    'EASY',
    'Padrão ISO/IEC 9075 SQL e documentação do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - DDL, DML e Agregação com GROUP BY',
    'MULTIPLE_CHOICE',
    'Deseja-se listar os departamentos com mais de 10 funcionários a partir de SELECT depto_id, COUNT(*) FROM funcionario GROUP BY depto_id. Qual cláusula completa corretamente a consulta?',
    'C',
    '["A) WHERE COUNT(*) > 10, escrita antes do GROUP BY", "B) WHERE COUNT(*) > 10, escrita após o GROUP BY", "C) HAVING COUNT(*) > 10, escrita após o GROUP BY", "D) ORDER BY COUNT(*) > 10, escrita após o GROUP BY"]'::jsonb,
    'WHERE filtra linhas antes do agrupamento e não aceita funções de agregação. HAVING filtra os grupos já formados, então é onde entra COUNT(*) > 10. ORDER BY só ordena, não filtra.',
    'MEDIUM',
    'Padrão ISO/IEC 9075 SQL e documentação do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - DDL, DML e Agregação com GROUP BY',
    'MULTIPLE_CHOICE',
    'A tabela cliente tem 100 linhas, e 20 delas têm email NULL. Qual o resultado de SELECT COUNT(*), COUNT(email) FROM cliente?',
    'A',
    '["A) 100 e 80", "B) 80 e 80", "C) 100 e 100", "D) 80 e 100"]'::jsonb,
    'COUNT(*) conta linhas, sem olhar valores. COUNT(coluna) ignora os NULLs dessa coluna. As demais agregações (SUM, AVG etc.) também descartam NULLs.',
    'MEDIUM',
    'Padrão ISO/IEC 9075 SQL e documentação do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - Funções de Janela',
    'MULTIPLE_CHOICE',
    'Os salários 5000, 5000 e 4000 são ordenados de forma decrescente. Que valores DENSE_RANK() OVER (ORDER BY salario DESC) atribui a essas linhas?',
    'C',
    '["A) 1, 2 e 3", "B) 1, 1 e 3", "C) 1, 1 e 2", "D) 1, 2 e 2"]'::jsonb,
    'DENSE_RANK dá a mesma posição aos empates e não deixa lacunas, então o próximo valor é 2. RANK deixaria lacuna (1, 1, 3) e ROW_NUMBER numeraria sem empates (1, 2, 3).',
    'MEDIUM',
    'Documentação oficial do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - Funções de Janela',
    'MULTIPLE_CHOICE',
    'Qual é a diferença entre SELECT id, cliente_id, SUM(valor) OVER (PARTITION BY cliente_id) FROM pedido e uma consulta com SUM(valor) e GROUP BY cliente_id?',
    'B',
    '["A) As duas devolvem exatamente o mesmo resultado, uma linha por cliente", "B) A versão com janela mantém todas as linhas e repete o total do cliente em cada uma; o GROUP BY devolve uma linha por cliente", "C) PARTITION BY funciona como um WHERE e descarta pedidos de outros clientes", "D) A versão com janela só é válida se houver também ORDER BY dentro do OVER"]'::jsonb,
    'Funções de janela calculam sobre um conjunto de linhas relacionadas sem colapsá-las, por isso permitem mostrar cada pedido ao lado do total do cliente. ORDER BY no OVER é opcional; sem ele a partição inteira é o frame.',
    'MEDIUM',
    'Documentação oficial do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - Funções de Janela',
    'MULTIPLE_CHOICE',
    'No PostgreSQL, sem cláusula de frame explícita, o que SUM(valor) OVER (ORDER BY data) calcula em cada linha?',
    'B',
    '["A) A soma de todas as linhas da tabela, repetida em cada linha", "B) A soma acumulada desde a primeira linha até a linha atual, incluindo as linhas empatadas na mesma data", "C) A soma apenas da linha atual com a linha imediatamente anterior", "D) Nada, pois a consulta falha por não ter PARTITION BY"]'::jsonb,
    'Com ORDER BY, o frame padrão é RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, o que dá um total acumulado; em RANGE, as linhas empatadas entram juntas. Sem ORDER BY, o frame seria a partição inteira. PARTITION BY é opcional.',
    'HARD',
    'Documentação oficial do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - JOINs e Subconsultas',
    'MULTIPLE_CHOICE',
    'Um relatório precisa listar todos os clientes com seus pedidos, inclusive os clientes que ainda não fizeram nenhum pedido. Qual junção atende?',
    'B',
    '["A) cliente c INNER JOIN pedido p ON p.cliente_id = c.id", "B) cliente c LEFT JOIN pedido p ON p.cliente_id = c.id", "C) cliente c RIGHT JOIN pedido p ON p.cliente_id = c.id", "D) cliente c CROSS JOIN pedido p"]'::jsonb,
    'LEFT JOIN mantém todas as linhas da tabela à esquerda e preenche com NULL quando não há par. INNER descarta os clientes sem pedido, RIGHT preserva os pedidos (não os clientes) e CROSS JOIN gera o produto cartesiano.',
    'EASY',
    'Padrão ISO/IEC 9075 SQL e documentação do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - JOINs e Subconsultas',
    'MULTIPLE_CHOICE',
    'Qual consulta retorna corretamente os clientes que nunca fizeram pedido?',
    'A',
    '["A) SELECT c.* FROM cliente c LEFT JOIN pedido p ON p.cliente_id = c.id WHERE p.id IS NULL", "B) SELECT c.* FROM cliente c INNER JOIN pedido p ON p.cliente_id = c.id WHERE p.id IS NULL", "C) SELECT c.* FROM cliente c LEFT JOIN pedido p ON p.cliente_id = c.id WHERE p.id = NULL", "D) SELECT c.* FROM cliente c RIGHT JOIN pedido p ON p.cliente_id = c.id WHERE c.id IS NULL"]'::jsonb,
    'O anti-join com LEFT JOIN deixa p.id nulo para clientes sem pedido, e IS NULL os seleciona. A comparação ''= NULL'' nunca é verdadeira, INNER JOIN nunca gera p.id nulo e a versão com RIGHT JOIN busca pedidos sem cliente.',
    'MEDIUM',
    'Padrão ISO/IEC 9075 SQL e documentação do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'SQL - JOINs e Subconsultas',
    'MULTIPLE_CHOICE',
    'SELECT * FROM cliente WHERE id NOT IN (SELECT cliente_id FROM pedido) retorna zero linhas, mesmo existindo clientes sem pedido. Qual é a causa mais provável?',
    'D',
    '["A) NOT IN não aceita subconsultas, somente listas de valores literais", "B) Falta DISTINCT na subconsulta, e valores repetidos anulam o NOT IN", "C) NOT IN exige que a subconsulta seja correlacionada com a consulta externa", "D) A subconsulta retorna algum cliente_id NULL, e a comparação com NULL resulta em UNKNOWN para todas as linhas"]'::jsonb,
    'x NOT IN (..., NULL) equivale a x <> ... AND x <> NULL, e o último termo é UNKNOWN, então nenhuma linha passa. NOT EXISTS ou um filtro WHERE cliente_id IS NOT NULL resolvem. Duplicatas não alteram o resultado do NOT IN.',
    'HARD',
    'Padrão ISO/IEC 9075 SQL e documentação do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'Transações - Concorrência, Bloqueios e Deadlock',
    'MULTIPLE_CHOICE',
    'T1 bloqueou a linha 10 e aguarda a linha 20; T2 bloqueou a linha 20 e aguarda a linha 10. Como o PostgreSQL lida com essa situação?',
    'B',
    '["A) Aguarda indefinidamente até um administrador encerrar as sessões", "B) Detecta o ciclo de espera (deadlock) e aborta uma das transações com erro, liberando seus bloqueios", "C) Confirma as duas transações na ordem em que começaram", "D) Converte automaticamente os bloqueios exclusivos em compartilhados"]'::jsonb,
    'É um deadlock clássico. Após um tempo de espera (deadlock_timeout), o PostgreSQL procura ciclos no grafo de espera e cancela uma transação vítima; a aplicação deve tratar o erro e repetir a operação.',
    'EASY',
    'Documentação oficial do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'Transações - Concorrência, Bloqueios e Deadlock',
    'MULTIPLE_CHOICE',
    'Uma aplicação de transferências entre contas sofre deadlocks frequentes quando duas transferências opostas ocorrem ao mesmo tempo. Qual prática reduz o problema na origem?',
    'D',
    '["A) Trocar o nível de isolamento para READ UNCOMMITTED", "B) Aumentar o número de conexões no pool da aplicação", "C) Criar mais índices nas colunas de saldo", "D) Bloquear as contas sempre na mesma ordem, por exemplo pelo menor id primeiro"]'::jsonb,
    'O deadlock exige uma espera circular; uma ordem global de aquisição de bloqueios impede que o ciclo se forme. Mudar o isolamento não elimina os bloqueios de escrita, e mais conexões só aumentam a concorrência.',
    'MEDIUM',
    'Elmasri e Navathe, Sistemas de Banco de Dados (questão original)',
    TRUE
),
(
    7,
    'Transações - Concorrência, Bloqueios e Deadlock',
    'MULTIPLE_CHOICE',
    'Duas sessões em READ COMMITTED leem estoque = 10 com SELECT, calculam 10 - 1 na aplicação e gravam UPDATE produto SET estoque = 9. O estoque final fica 9, e não 8. Como corrigir?',
    'D',
    '["A) Criar um índice na coluna estoque", "B) Trocar o nível de isolamento para READ UNCOMMITTED", "C) Executar cada comando em autocommit, fora de transação", "D) Ler com SELECT ... FOR UPDATE, ou fazer o decremento atômico com SET estoque = estoque - 1"]'::jsonb,
    'Ocorreu uma atualização perdida: a segunda gravação sobrescreveu a primeira com base em uma leitura velha. FOR UPDATE bloqueia a linha até o fim da transação, e o UPDATE relativo lê o valor atual no momento da escrita.',
    'HARD',
    'Documentação oficial do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'Transações ACID - Níveis de Isolamento ANSI SQL',
    'MULTIPLE_CHOICE',
    'T1 altera um saldo sem confirmar; T2 lê o novo valor; em seguida T1 faz ROLLBACK. Qual anomalia ocorreu e qual é o menor nível de isolamento ANSI que a impede?',
    'C',
    '["A) Leitura fantasma; REPEATABLE READ", "B) Leitura não repetível; SERIALIZABLE", "C) Leitura suja; READ COMMITTED", "D) Leitura suja; READ UNCOMMITTED"]'::jsonb,
    'T2 leu um dado que nunca foi confirmado (dirty read). READ COMMITTED só mostra dados confirmados e é o primeiro nível acima de READ UNCOMMITTED, que no padrão ANSI permite essa anomalia.',
    'MEDIUM',
    'Padrão ISO/IEC 9075 SQL e documentação do PostgreSQL (questão original)',
    TRUE
),
(
    7,
    'Transações ACID - Níveis de Isolamento ANSI SQL',
    'MULTIPLE_CHOICE',
    'T1 executa SELECT COUNT(*) FROM funcionario WHERE depto = 5 duas vezes. Entre as duas leituras, T2 insere um funcionário no depto 5 e confirma, e as contagens diferem. Qual anomalia é essa?',
    'C',
