(
    7,
    'Transações ACID - Níveis de Isolamento ANSI SQL',
    'MULTIPLE_CHOICE',
    'Sobre os níveis de isolamento no PostgreSQL, qual afirmação está correta?',
    'C',
    '["A) O padrão é SERIALIZABLE, como exige o padrão SQL para todos os SGBDs", "B) O padrão é REPEATABLE READ, e READ UNCOMMITTED permite leituras sujas", "C) O padrão é READ COMMITTED, e READ UNCOMMITTED se comporta como READ COMMITTED, pois leituras sujas nunca ocorrem", "D) O padrão é READ UNCOMMITTED, para maximizar a concorrência"]'::jsonb,
    'Com MVCC, o PostgreSQL nunca expõe dados não confirmados; READ UNCOMMITTED é aceito na sintaxe, mas funciona como READ COMMITTED, que é o nível padrão. O padrão SQL fixa garantias mínimas, não o nível padrão de cada SGBD.',
    'HARD',
