(
    7,
    'Índices - B-tree e Índices Compostos',
    'MULTIPLE_CHOICE',
    'Uma tabela tem um índice B-tree na coluna data_venda. Que tipo de consulta esse índice atende bem?',
    'B',
    '["A) Apenas igualdade exata, sem suporte a intervalos", "B) Igualdade, intervalos (como BETWEEN, < e >) e ordenação pela coluna", "C) Apenas buscas do tipo LIKE ''%texto%'' em qualquer posição", "D) Apenas buscas textuais (full-text) por palavras"]'::jsonb,
    'A B-tree mantém as chaves ordenadas e balanceadas, o que serve para igualdade, faixas e ORDER BY. O índice hash é o que só atende igualdade, e padrões com curinga no início não aproveitam a ordenação.',
    'EASY',
    'Documentação oficial do PostgreSQL (questão original)',
