    '["A) WHERE sobrenome = ''Silva''", "B) WHERE sobrenome = ''Silva'' AND nome = ''Ana''", "C) WHERE sobrenome = ''Silva'' ORDER BY nome", "D) WHERE nome = ''Ana''"]'::jsonb,
    'O índice composto é ordenado primeiro pela coluna líder (sobrenome). Filtros que começam por ela usam o índice bem; filtrar só pela segunda coluna exige varrer o índice inteiro ou a tabela.',
    'MEDIUM',
