INSERT INTO tb_flashcard (subject_id, topic, question_type, question, answer, options_json, explanation, difficulty, source, active)
VALUES
(
    8,
    'Algoritmos de Busca - Busca Binária',
    'MULTIPLE_CHOICE',
    'Qual o número máximo de comparações com o elemento central que a busca binária faz em um array ordenado de 1.000 elementos?',
    'D',
    '["A) 100", "B) 500", "C) 32", "D) 10"]'::jsonb,
    'Cada comparação descarta metade do intervalo: ⌊log₂ 1000⌋ + 1 = 9 + 1 = 10, já que 2¹⁰ = 1024 ≥ 1000. Valores como 500 refletem busca linear no caso médio.',
    'EASY',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Algoritmos de Busca - Busca Binária',
    'MULTIPLE_CHOICE',
    'Em uma busca binária com inteiros de 32 bits, por que se recomenda calcular o meio como low + (high − low) / 2, em vez de (low + high) / 2?',
    'B',
    '["A) Para que a busca funcione em arrays desordenados", "B) Para evitar estouro de inteiro na soma low + high quando os índices são grandes", "C) Para reduzir a complexidade de O(log n) para O(1)", "D) Para garantir que o meio seja sempre um número par"]'::jsonb,
    'Com índices próximos do limite do tipo, low + high pode ultrapassar o valor máximo e virar negativo. A forma low + (high − low) / 2 dá o mesmo resultado matemático sem estourar. A complexidade não muda.',
    'MEDIUM',
    'Sedgewick e Wayne, Algorithms, 4ª ed. (questão original)',
    TRUE
),
(
    8,
    'Algoritmos de Busca - Busca Binária',
    'MULTIPLE_CHOICE',
    'Um array ordenado tem valores repetidos e você quer o índice da primeira ocorrência de x em O(log n). Ao encontrar a[mid] igual a x, o que a busca deve fazer?',
    'D',
    '["A) Retornar mid imediatamente", "B) Andar posição por posição para a esquerda até a primeira ocorrência", "C) Continuar buscando na metade direita", "D) Registrar mid como candidato e continuar buscando na metade esquerda"]'::jsonb,
    'Pode haver ocorrências anteriores; registrar e seguir à esquerda (high = mid − 1) mantém O(log n). Andar posição por posição degrada para O(n) quando há muitas repetições.',
    'HARD',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Algoritmos de Ordenação - Estabilidade e Complexidade',
    'MULTIPLE_CHOICE',
    'Qual a complexidade do insertion sort quando o array de entrada já está ordenado?',
    'D',
