    'Com a entrada ordenada, o laço interno para na primeira comparação, sobrando n−1 comparações. O(n²) é o pior caso, com a entrada em ordem inversa.',
    'EASY',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
