(
    8,
    'Algoritmos de Ordenação - Estabilidade e Complexidade',
    'MULTIPLE_CHOICE',
    'Em sua implementação clássica, qual algoritmo de ordenação é estável, isto é, preserva a ordem relativa de elementos com chaves iguais?',
    'A',
    '["A) Merge sort", "B) Heap sort", "C) Quick sort com partição de Lomuto", "D) Selection sort com trocas"]'::jsonb,
    'O merge sort, ao intercalar, pega da metade esquerda em caso de empate e preserva a ordem original. Heap sort, quick sort e selection sort com trocas podem mover um elemento por cima de outro de mesma chave.',
    'MEDIUM',
    'Sedgewick e Wayne, Algorithms, 4ª ed. (questão original)',
    TRUE
),
(
    8,
    'Algoritmos de Ordenação - Estabilidade e Complexidade',
    'MULTIPLE_CHOICE',
    'Um quick sort escolhe sempre o primeiro elemento como pivô. Em qual situação ele atinge o pior caso, e qual é esse custo?',
    'C',
    '["A) Com o array aleatório, custo O(n log n)", "B) Com todos os elementos distintos, custo O(n³)", "C) Com o array já ordenado, gerando partições de tamanho 0 e n−1, custo O(n²)", "D) Com o array já ordenado, custo O(n)"]'::jsonb,
    'Com a entrada ordenada, o pivô é sempre o menor elemento, e cada partição reduz o problema em apenas um: n + (n−1) + ... = O(n²). Pivô aleatório ou mediana de três tornam esse caso improvável.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
