(
    8,
    'Algoritmos de Ordenação - Estabilidade e Complexidade',
    'MULTIPLE_CHOICE',
    'O counting sort ordena n inteiros no intervalo de 0 a k em O(n + k). Como isso é compatível com o limite inferior Ω(n log n) para ordenação?',
    'C',
    '["A) O limite Ω(n log n) vale apenas para o caso médio", "B) O counting sort é O(n log n) disfarçado, pois k ≥ log n", "C) O limite Ω(n log n) vale só para ordenação por comparação, e o counting sort não compara elementos", "D) O limite foi superado por algoritmos in-place modernos"]'::jsonb,
    'O limite vem da árvore de decisão: comparações precisam distinguir n! permutações, exigindo log(n!) = Θ(n log n). O counting sort usa os valores como índices, fugindo desse modelo; com k grande, perde a vantagem.',
    'HARD',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
