(
    8,
    'Algoritmos de Ordenação - Estabilidade e Complexidade',
    'MULTIPLE_CHOICE',
    'Você precisa de ordenação com garantia de O(n log n) no pior caso e apenas O(1) de memória extra. Qual algoritmo clássico atende aos dois requisitos?',
    'A',
    '["A) Heap sort", "B) Merge sort sobre array", "C) Quick sort com pivô fixo", "D) Insertion sort"]'::jsonb,
    'O heap sort é O(n log n) no pior caso e ordena no próprio array. O merge sort sobre array precisa de O(n) auxiliar; o quick sort tem pior caso O(n²); o insertion sort é O(n²).',
    'HARD',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
