(
    8,
    'Complexidade Assintótica (Big-O)',
    'MULTIPLE_CHOICE',
    'Um trecho de código tem dois laços aninhados: o externo varia i de 0 a n−1 e o interno varia j de 0 a n−1, executando uma operação de custo constante. Qual a complexidade de tempo?',
    'B',
    '["A) O(n)", "B) O(n²)", "C) O(n log n)", "D) O(2ⁿ)"]'::jsonb,
    'O laço interno executa n vezes para cada uma das n iterações do externo: n × n = n² operações constantes, logo O(n²). O(n log n) exigiria que um dos laços fosse logarítmico.',
    'EASY',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Complexidade Assintótica (Big-O)',
    'MULTIPLE_CHOICE',
    'Na análise assintótica, o que significa afirmar que f(n) = Ω(g(n))?',
    'C',
    '["A) g(n) é um limite superior assintótico de f(n)", "B) f(n) e g(n) crescem exatamente na mesma taxa, sem constantes", "C) g(n) é um limite inferior assintótico de f(n), a menos de uma constante", "D) f(n) representa o tempo médio do algoritmo"]'::jsonb,
    'Ω indica limite inferior: existe c > 0 e n₀ tal que f(n) ≥ c·g(n) para n ≥ n₀. Limite superior é O; limite justo (superior e inferior ao mesmo tempo) é Θ. Nenhuma das notações é, por si, sinônimo de caso médio.',
    'EASY',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Complexidade Assintótica (Big-O)',
    'MULTIPLE_CHOICE',
    'O laço externo começa com i = 1 e dobra i a cada passo enquanto i < n; dentro dele, um laço interno percorre j de 0 a n−1 com custo constante. Qual a complexidade total?',
    'D',
    '["A) O(n²)", "B) O(log n)", "C) O(n)", "D) O(n log n)"]'::jsonb,
    'Como i dobra a cada passo, o laço externo roda cerca de log₂ n vezes; cada rodada executa o laço interno de n passos. Total ≈ n · log n. Não é O(n²) porque o externo não é linear.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Complexidade Assintótica (Big-O)',
    'MULTIPLE_CHOICE',
    'Para i de 0 a n−1, um laço interno percorre j de 0 a i−1 com operação constante. Qual o crescimento do número total de operações?',
    'A',
    '["A) Θ(n²), pois são n(n−1)/2 iterações", "B) Θ(n), pois o laço interno é menor que o externo", "C) Θ(n log n), pois o laço interno cresce aos poucos", "D) Θ(n³), pois há dependência entre os índices"]'::jsonb,
    'Soma 0 + 1 + ... + (n−1) = n(n−1)/2, que é Θ(n²): a constante 1/2 não altera a ordem de crescimento. O laço interno ser menor não reduz a ordem para linear.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
