    'Estruturas Lineares - Listas, Pilhas e Filas',
    'MULTIPLE_CHOICE',
    'Uma fila é implementada com duas pilhas: enfileirar empilha na pilha de entrada; desenfileirar desempilha da pilha de saída, transferindo tudo da entrada quando a saída está vazia. Qual o custo?',
    'D',
