    'Dijkstra assume que, ao fixar a distância de um vértice, ela não diminuirá mais, o que pesos negativos violam. Bellman-Ford relaxa todas as arestas V−1 vezes e ainda detecta ciclos negativos.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Grafos - Representações, Caminho Mínimo e Árvore Geradora',
    'MULTIPLE_CHOICE',
    'Arestas dirigidas com pesos: P→Q (4), P→R (1), R→Q (2), Q→S (1), R→S (6). Pelo algoritmo de Dijkstra a partir de P, qual a distância mínima até S?',
    'C',
    '["A) 5", "B) 7", "C) 4", "D) 6"]'::jsonb,
    'O caminho P→R→Q→S custa 1 + 2 + 1 = 4. P→Q→S custa 5 e P→R→S custa 7. Dijkstra fixa R (1), depois Q (3, via R) e por fim S (4).',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Grafos - Representações, Caminho Mínimo e Árvore Geradora',
    'MULTIPLE_CHOICE',
    'Qual é a ideia central do algoritmo de Kruskal para árvore geradora mínima?',
    'B',
    '["A) Crescer uma única árvore a partir de um vértice, sempre pela aresta mais leve que sai dela", "B) Ordenar as arestas por peso e adicionar cada uma se ela não formar ciclo, usando union-find", "C) Relaxar todas as arestas V−1 vezes", "D) Remover a aresta mais pesada de cada vértice até restarem V−1 arestas"]'::jsonb,
    'Kruskal é guloso sobre a lista global de arestas e usa union-find para saber se os extremos já estão no mesmo componente. Crescer uma única árvore a partir de um vértice descreve o algoritmo de Prim.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Grafos - Representações, Caminho Mínimo e Árvore Geradora',
    'MULTIPLE_CHOICE',
    'Em um grafo conexo, não dirigido, com todos os pesos de aresta distintos, qual afirmação sobre a árvore geradora mínima (AGM) é correta?',
    'B',
    '["A) A AGM contém o caminho mínimo entre quaisquer dois vértices", "B) A AGM é única, e a aresta mais leve que cruza qualquer corte pertence a ela", "C) A aresta mais pesada do grafo nunca pertence à AGM", "D) Prim e Kruskal podem gerar AGMs com pesos totais diferentes"]'::jsonb,
    'Com pesos distintos a AGM é única, e a propriedade do corte garante a aresta mais leve de cada corte. A aresta mais pesada pode ser ponte e entrar obrigatoriamente; AGM não preserva caminhos mínimos.',
    'HARD',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Paradigmas - Recursão, Programação Dinâmica e Gulosos',
    'MULTIPLE_CHOICE',
    'O que acontece ao executar uma função recursiva que não possui caso base alcançável?',
    'B',
    '["A) O compilador converte a recursão em laço e ela termina", "B) Ela se chama indefinidamente até esgotar a pilha de chamadas", "C) Ela retorna zero após a primeira chamada", "D) Ela executa normalmente, apenas mais devagar"]'::jsonb,
    'Sem caso base, cada chamada empilha outra, e a pilha de execução se esgota (em Java, StackOverflowError). Otimização de chamada de cauda não cria um caso base; só evita crescer a pilha em algumas linguagens.',
    'EASY',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Paradigmas - Recursão, Programação Dinâmica e Gulosos',
    'MULTIPLE_CHOICE',
    'A função recursiva ingênua fib(n) = fib(n−1) + fib(n−2) tem custo exponencial. O que muda ao aplicar memoização?',
    'A',
    '["A) Cada fib(k) é calculado uma vez e o tempo cai para O(n)", "B) O tempo cai para O(log n) sem memória extra", "C) O tempo continua exponencial, apenas com menos memória", "D) O resultado passa a ser aproximado"]'::jsonb,
    'A versão ingênua recalcula os mesmos subproblemas muitas vezes. Guardar cada fib(k) já calculado faz com que existam apenas n subproblemas distintos, cada um resolvido em O(1): O(n) de tempo e O(n) de memória.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Paradigmas - Recursão, Programação Dinâmica e Gulosos',
    'MULTIPLE_CHOICE',
    'Quais duas propriedades indicam que um problema é bom candidato à programação dinâmica?',
    'C',
    '["A) Entrada ordenada e ausência de recursão", "B) Escolha gulosa e subproblemas independentes", "C) Subestrutura ótima e subproblemas sobrepostos", "D) Grafo acíclico e pesos positivos"]'::jsonb,
    'A subestrutura ótima permite compor a solução a partir de soluções de subproblemas; a sobreposição faz valer a pena guardá-las. Subproblemas independentes, sem sobreposição, caracterizam divisão e conquista.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Paradigmas - Recursão, Programação Dinâmica e Gulosos',
    'MULTIPLE_CHOICE',
    'Com moedas de valores 1, 3 e 4 e troco de 6, compare o algoritmo guloso (sempre a maior moeda possível) com a solução ótima.',
    'A',
    '["A) O guloso usa 3 moedas (4 + 1 + 1) e o ótimo usa 2 (3 + 3)", "B) Ambos usam 2 moedas", "C) O guloso usa 2 moedas e o ótimo usa 3", "D) O guloso usa 6 moedas de 1"]'::jsonb,
    'O guloso pega 4 e completa com duas moedas de 1, totalizando 3; a combinação 3 + 3 usa só 2. Em sistemas de moedas como esse, a escolha gulosa não é ótima, e a programação dinâmica resolve o problema.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Paradigmas - Recursão, Programação Dinâmica e Gulosos',
    'MULTIPLE_CHOICE',
    'Sobre o problema da mochila, qual afirmação é correta?',
    'D',
    '["A) O guloso por valor/peso é ótimo nas duas versões", "B) A versão 0/1 é resolvida em tempo polinomial no tamanho da entrada por PD", "C) A versão fracionária exige programação dinâmica", "D) Na versão fracionária o guloso por valor/peso é ótimo; na 0/1, não, e a programação dinâmica resolve em O(n·W)"]'::jsonb,
    'Na fracionária pode-se pegar parte de um item, e a melhor razão valor/peso sempre compensa. Na 0/1 essa escolha pode desperdiçar capacidade. O(n·W) é pseudo-polinomial: depende do valor W, não do seu número de bits.',
    'HARD',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Tabelas Hash - Tratamento de Colisões',
    'MULTIPLE_CHOICE',
    'Em uma tabela hash com boa função de dispersão e fator de carga mantido limitado, qual o custo esperado de busca por uma chave?',
    'C',
    '["A) O(log n) em média", "B) O(n) em média", "C) O(1) em média", "D) O(n log n) em média"]'::jsonb,
    'Com dispersão uniforme e fator de carga constante, o número esperado de chaves examinadas por busca é constante. O pior caso, com todas as chaves colidindo, pode chegar a O(n), mas não é o esperado.',
    'EASY',
    'Sedgewick e Wayne, Algorithms, 4ª ed. (questão original)',
    TRUE
),
(
    8,
    'Tabelas Hash - Tratamento de Colisões',
    'MULTIPLE_CHOICE',
    'Tabela hash com 7 posições (0 a 6), função h(k) = k mod 7 e sondagem linear. Inserem-se 10, 17 e 24, nessa ordem, na tabela vazia. Em que posição fica a chave 24?',
    'B',
    '["A) 3", "B) 5", "C) 4", "D) 6"]'::jsonb,
    'As três chaves têm h = 3. A 10 ocupa a posição 3; a 17 colide e vai para 4; a 24 encontra 3 e 4 ocupadas e vai para 5. Esse acúmulo de chaves vizinhas é o agrupamento primário da sondagem linear.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Tabelas Hash - Tratamento de Colisões',
    'MULTIPLE_CHOICE',
    'Em uma tabela hash com endereçamento aberto, por que a remoção de uma chave costuma ser feita com um marcador de removido (lápide), em vez de simplesmente esvaziar a posição?',
    'A',
    '["A) Porque esvaziar a posição interromperia a sequência de sondagem e faria buscas por outras chaves pararem cedo, falhando", "B) Porque a função hash precisaria ser recalculada para todas as chaves", "C) Porque o marcador reduz o fator de carga imediatamente", "D) Porque o encadeamento separado proíbe remoções físicas"]'::jsonb,
    'A busca em endereçamento aberto para ao encontrar posição vazia. Se uma chave no meio de uma cadeia de sondagem for apagada, chaves inseridas depois dela ficam inalcançáveis. A lápide mantém a cadeia e pode ser reaproveitada em inserções.',
    'HARD',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Árvores - Busca Binária, AVL e Heap',
    'MULTIPLE_CHOICE',
    'Ao percorrer uma árvore binária de busca em ordem simétrica (in-order: esquerda, raiz, direita), em que ordem as chaves são visitadas?',
    'B',
    '["A) Na ordem em que foram inseridas", "B) Em ordem crescente", "C) Nível a nível, da raiz para as folhas", "D) Em ordem decrescente"]'::jsonb,
    'Na árvore binária de busca, tudo à esquerda é menor e tudo à direita é maior que a raiz; visitar esquerda, raiz e direita recursivamente produz as chaves ordenadas. Nível a nível é o percurso em largura.',
    'EASY',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Árvores - Busca Binária, AVL e Heap',
    'MULTIPLE_CHOICE',
    'Inserem-se as chaves 1, 2, 3, 4 e 5, nessa ordem, em uma árvore binária de busca sem balanceamento. Qual a consequência?',
    'A',
    '["A) A árvore degenera em uma cadeia e a busca passa a custar O(n)", "B) A árvore fica perfeitamente balanceada com altura log₂ 5", "C) A raiz passa a ser a chave 3 automaticamente", "D) A inserção falha por violar a propriedade de busca"]'::jsonb,
    'Cada nova chave é maior que todas as anteriores e vai sempre para a direita, formando uma lista com altura n−1. Só árvores autobalanceadas (AVL, rubro-negra) reorganizam a raiz automaticamente.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Árvores - Busca Binária, AVL e Heap',
    'MULTIPLE_CHOICE',
    'Um heap binário está armazenado em um array indexado a partir de 0. Em quais posições ficam os filhos do nó na posição i?',
    'C',
    '["A) 2i e 2i + 1", "B) i + 1 e i + 2", "C) 2i + 1 e 2i + 2", "D) 2i − 1 e 2i"]'::jsonb,
    'Com índice inicial 0, a raiz está em 0 e seus filhos em 1 e 2; generalizando, 2i + 1 e 2i + 2, e o pai fica em ⌊(i − 1)/2⌋. A fórmula 2i e 2i + 1 vale para arrays indexados a partir de 1.',
    'MEDIUM',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Árvores - Busca Binária, AVL e Heap',
    'MULTIPLE_CHOICE',
    'Em uma árvore AVL vazia inserem-se 30, 10 e 20, nessa ordem. Que rebalanceamento ocorre e qual a raiz final?',
    'A',
    '["A) Rotação dupla esquerda-direita, com raiz final 20", "B) Rotação simples à direita, com raiz final 10", "C) Nenhuma rotação, com raiz final 30", "D) Rotação simples à esquerda, com raiz final 30"]'::jsonb,
    'Após inserir 20 como filho direito de 10, o nó 30 fica com fator de balanceamento +2 pelo lado esquerdo e o desvio é esquerda-direita: gira-se à esquerda em 10 e depois à direita em 30, e 20 sobe para a raiz.',
    'HARD',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
),
(
    8,
    'Árvores - Busca Binária, AVL e Heap',
    'MULTIPLE_CHOICE',
    'Qual o custo de construir um heap binário a partir de um array desordenado de n elementos, aplicando o procedimento de descida (heapify) do último nó interno até a raiz?',
    'D',
    '["A) O(n log n)", "B) O(log n)", "C) O(n²)", "D) O(n)"]'::jsonb,
    'A maioria dos nós está perto das folhas e desce pouco; a soma dos custos por altura converge para O(n). O(n log n) é um limite válido, porém folgado, e corresponde a inserir os elementos um a um.',
    'HARD',
    'Cormen et al., Algoritmos: Teoria e Prática, 3ª ed. (questão original)',
    TRUE
);

-- -----------------------------------------------------------------------------
-- 13. SIS_INFO — SEG_INFO (33 questões)
-- -----------------------------------------------------------------------------
INSERT INTO tb_flashcard (subject_id, topic, question_type, question, answer, options_json, explanation, difficulty, source, active)
VALUES
(
    9,
    'Autenticação - JWT (JSON Web Token)',
    'MULTIPLE_CHOICE',
    'Um JWT assinado com HS256 é interceptado. O atacante consegue ler as claims do payload sem conhecer a chave secreta?',
    'D',
    '["A) Não, a assinatura HS256 cifra o payload", "B) Só se também conseguir a chave secreta usada na assinatura", "C) Não, o header indica que o conteúdo é cifrado com AES", "D) Sim, o payload é apenas codificado em Base64URL; por isso não se deve colocar dados sensíveis nele"]'::jsonb,
    'Um JWT assinado (JWS) garante integridade e autenticidade, não sigilo: qualquer um decodifica o payload. A chave serve para gerar e verificar a assinatura. Para sigilo existe o JWE, ou basta não incluir dados sensíveis.',
    'EASY',
    'RFC 7519 - JWT / RFC 7515 - JWS (questão original)',
    TRUE
),
(
    9,
    'Autenticação - JWT (JSON Web Token)',
    'MULTIPLE_CHOICE',
    'Qual é a principal desvantagem de um JWT stateless de longa duração em comparação com uma sessão guardada no servidor?',
    'B',
    '["A) Não pode carregar informações de autorização, como papéis", "B) É difícil revogá-lo antes do ''exp'' sem manter estado, por isso se usa access token curto com refresh token", "C) Exige consultar o banco a cada requisição para validar a assinatura", "D) Não funciona em APIs que usam HTTPS"]'::jsonb,
    'O JWT é validado só pela assinatura e pelo ''exp'', sem consulta ao servidor. Isso escala bem, mas um token vazado vale até expirar. Tokens curtos, refresh tokens e listas de bloqueio reduzem o problema; sessões são revogadas apagando o registro.',
    'MEDIUM',
    'RFC 7519 / OWASP JWT Cheat Sheet (questão original)',
    TRUE
),
(
    9,
    'Autenticação - JWT (JSON Web Token)',
    'MULTIPLE_CHOICE',
    'Uma API decide como validar o JWT lendo o campo ''alg'' do header do próprio token recebido. Qual risco isso cria e como mitigá-lo?',
    'B',
    '["A) Replay de tokens; mitigar aumentando o ''exp'' para 30 dias", "B) Aceitar tokens forjados com ''alg'' none ou trocado de RS256 para HS256; mitigar fixando no servidor o algoritmo esperado", "C) XSS no header; mitigar codificando o header duas vezes em Base64URL", "D) Nenhum risco, pois o atacante não consegue criar um header novo"]'::jsonb,
    'O atacante monta um token novo e escolhe o ''alg''. Se a API aceitar ''none'' ou usar a chave pública RSA como segredo HMAC, a assinatura forjada passa. O servidor deve impor o algoritmo e a chave esperados, sem confiar no header.',
    'HARD',
    'RFC 8725 - JWT Best Current Practices (questão original)',
    TRUE
),
(
    9,
    'Autenticação - MFA e Gerenciamento de Sessões',
    'MULTIPLE_CHOICE',
    'Qual combinação de fatores caracteriza autenticação multifator (MFA)?',
    'C',
    '["A) Senha e resposta a uma pergunta secreta", "B) Duas senhas diferentes cadastradas pelo usuário", "C) Senha e código TOTP gerado por aplicativo autenticador no celular", "D) PIN numérico e data de nascimento"]'::jsonb,
    'MFA exige fatores de categorias diferentes: algo que você sabe, algo que você tem e algo que você é. Senha (sabe) com TOTP do celular (tem) é MFA. Senha com pergunta secreta são dois fatores da mesma categoria.',
    'EASY',
    'NIST SP 800-63B (questão original)',
    TRUE
),
(
    9,
    'Autenticação - MFA e Gerenciamento de Sessões',
    'MULTIPLE_CHOICE',
    'Após o login, uma aplicação mantém o mesmo identificador de sessão que o navegador já tinha antes da autenticação. Qual é o risco e a correção?',
    'A',
    '["A) Fixação de sessão; gerar um novo ID de sessão no login e invalidar o anterior", "B) SQL Injection; parametrizar a consulta de login", "C) Nenhum risco, desde que o site use HTTPS", "D) Força bruta; exigir senhas com mais caracteres"]'::jsonb,
    'Se o ID não muda no login, o atacante pode plantar um ID conhecido na vítima e, após ela se autenticar, usar a mesma sessão. Regenerar o ID a cada mudança de privilégio elimina o ataque; HTTPS não resolve isso.',
    'MEDIUM',
    'OWASP Session Management Cheat Sheet (questão original)',
    TRUE
),
(
    9,
    'Autenticação - MFA e Gerenciamento de Sessões',
    'MULTIPLE_CHOICE',
    'Quais atributos do cookie de sessão impedem, respectivamente, que um script injetado leia o cookie e que ele seja enviado por HTTP sem criptografia?',
    'D',
    '["A) Domain e Path", "B) Max-Age e Expires", "C) SameSite=None e Path=/", "D) HttpOnly e Secure"]'::jsonb,
    'HttpOnly impede o acesso via document.cookie, reduzindo o roubo por XSS. Secure faz o navegador enviar o cookie só por HTTPS. Domain e Path definem escopo; Max-Age e Expires definem duração; SameSite trata do envio entre sites.',
    'MEDIUM',
    'RFC 6265 / OWASP Session Management Cheat Sheet (questão original)',
    TRUE
),
(
    9,
    'Autenticação e Autorização - OAuth 2.0 e OpenID Connect',
    'MULTIPLE_CHOICE',
    'Qual é a relação correta entre OAuth 2.0 e OpenID Connect (OIDC)?',
    'C',
    '["A) OAuth 2.0 é um protocolo de autenticação e o OIDC, de autorização", "B) São nomes diferentes para a mesma especificação", "C) OAuth 2.0 trata de autorização delegada; o OIDC acrescenta autenticação sobre ele, com o ID Token", "D) O OIDC substitui o TLS na proteção do canal"]'::jsonb,
    'OAuth 2.0 permite que um aplicativo acesse recursos em nome do usuário, mas não define como identificá-lo. O OIDC é uma camada de identidade sobre o OAuth 2.0 e entrega o ID Token (um JWT) com dados de quem se autenticou.',
    'EASY',
    'RFC 6749 / OpenID Connect Core 1.0 (questão original)',
    TRUE
),
(
    9,
    'Autenticação e Autorização - OAuth 2.0 e OpenID Connect',
    'MULTIPLE_CHOICE',
    'Um aplicativo de estudos pede permissão para ler a agenda do Google do aluno, que aprova o acesso. Pelos papéis do OAuth 2.0, quem é o resource owner?',
    'A',
    '["A) O aluno, dono dos dados que concede o acesso", "B) O aplicativo de estudos", "C) O servidor de autorização do Google", "D) A API da agenda que guarda os eventos"]'::jsonb,
    'Resource owner é quem pode conceder acesso ao recurso: o aluno. O aplicativo de estudos é o client, o servidor do Google que emite tokens é o authorization server, e a API da agenda é o resource server.',
    'MEDIUM',
    'RFC 6749 - OAuth 2.0 (questão original)',
    TRUE
),
(
    9,
    'Autenticação e Autorização - OAuth 2.0 e OpenID Connect',
    'MULTIPLE_CHOICE',
    'Uma SPA envia o ID Token obtido via OpenID Connect como credencial Bearer para chamar a API de notas. Por que isso é inadequado?',
    'D',
    '["A) O ID Token não é assinado e pode ser alterado livremente", "B) O ID Token contém a senha do usuário em texto claro", "C) O ID Token só pode ser usado em aplicativos mobile", "D) O ID Token é destinado ao cliente (aud = client_id) para provar a autenticação; para chamar a API usa-se o access token"]'::jsonb,
    'O ID Token informa ao cliente quem se autenticou e tem como audiência o client_id. Autorizar chamadas à API é papel do access token, emitido para aquela API e com escopos. O ID Token é um JWT assinado e não carrega senha.',
    'HARD',
    'OpenID Connect Core 1.0 / RFC 6749 (questão original)',
    TRUE
),
(
    9,
    'Criptografia - Criptografia Assimétrica',
    'MULTIPLE_CHOICE',
    'Por que o TLS combina criptografia assimétrica e simétrica em vez de usar apenas a assimétrica para todo o tráfego?',
    'C',
    '["A) A simétrica autentica o servidor e a assimétrica cifra o volume de dados", "B) A assimétrica cifra todo o tráfego e a simétrica serve apenas para gerar hashes", "C) A troca de chaves assimétrica estabelece uma chave de sessão, e a cifra simétrica, muito mais rápida, protege os dados", "D) A simétrica é sempre mais segura, e a assimétrica é mantida apenas por compatibilidade"]'::jsonb,
    'Algoritmos assimétricos são caros computacionalmente. No TLS, o handshake usa assimétrica (por exemplo ECDHE e a assinatura do certificado) para acordar a chave e autenticar o servidor; depois, AES-GCM ou ChaCha20 cifra o tráfego.',
    'MEDIUM',
    'RFC 8446 - TLS 1.3 (questão original)',
    TRUE
),
(
    9,
    'Criptografia - Criptografia Assimétrica',
    'MULTIPLE_CHOICE',
    'Ana precisa assinar digitalmente um relatório para que qualquer pessoa possa verificar a autoria e a integridade. Como funciona esse processo?',
    'B',
    '["A) Ana cifra o documento com a chave pública do destinatário, e ele verifica com a própria chave privada", "B) Ana assina o hash do documento com a sua chave privada, e o verificador usa a chave pública de Ana", "C) Ana assina com a própria chave pública, e o verificador usa a chave privada de Ana", "D) Ana cifra o documento com uma chave simétrica compartilhada, o que garante o não repúdio"]'::jsonb,
    'Na assinatura digital, calcula-se o hash e assina-se com a chave privada do autor; qualquer um verifica com a chave pública dele. Cifrar com a chave pública do destinatário dá sigilo, não autoria. Chave compartilhada não garante não repúdio.',
    'MEDIUM',
    'Stallings, Criptografia e Segurança de Redes (questão original)',
    TRUE
),
(
    9,
    'Criptografia - Criptografia Assimétrica',
    'MULTIPLE_CHOICE',
    'No handshake TLS, o navegador recebe o certificado X.509 do servidor. O que ele verifica para confiar nesse certificado?',
    'D',
    '["A) Se a chave privada do servidor veio junto com o certificado", "B) Apenas se a chave do certificado é RSA de 4096 bits", "C) Se o certificado foi assinado com a chave pública da autoridade certificadora", "D) Se a cadeia de assinaturas leva a uma AC raiz confiável, se o host consta no certificado e se está válido e não revogado"]'::jsonb,
    'O navegador valida a cadeia até uma raiz do repositório confiável, confere o nome do host no SAN, a validade e o status de revogação. A AC assina com a chave privada dela, não com a pública. A chave privada do servidor nunca é enviada.',
    'HARD',
    'RFC 5280 / RFC 8446 (questão original)',
    TRUE
),
(
    9,
    'Criptografia - Hash e Armazenamento de Senhas',
    'MULTIPLE_CHOICE',
    'Qual afirmação sobre funções hash criptográficas, como o SHA-256, está correta?',
    'A',
    '["A) São funções de mão única: não existe chave para reverter o hash ao texto original", "B) Com a chave correta, o hash pode ser decifrado para recuperar a entrada", "C) O tamanho da saída cresce conforme o tamanho da entrada", "D) Duas entradas diferentes nunca podem produzir o mesmo hash, nem em teoria"]'::jsonb,
    'Hash não é cifra: não usa chave e não é reversível. A saída tem tamanho fixo (256 bits no SHA-256). Colisões existem em teoria, pois as entradas são infinitas; a função apenas torna inviável encontrá-las.',
    'EASY',
    'NIST FIPS 180-4 (questão original)',
    TRUE
),
(
    9,
    'Criptografia - Hash e Armazenamento de Senhas',
    'MULTIPLE_CHOICE',
    'Ao armazenar senhas, um sistema gera um salt aleatório e único para cada usuário antes de calcular o hash. Qual é o principal benefício do salt?',
    'A',
    '["A) Senhas iguais passam a gerar hashes diferentes, inviabilizando tabelas pré-computadas (rainbow tables)", "B) Permite recuperar a senha original quando o usuário a esquece", "C) Dispensa o uso de um algoritmo lento, pois o salt já basta", "D) Precisa ser mantido em segredo, como uma chave criptográfica"]'::jsonb,
    'O salt não é secreto e costuma ficar junto do hash. Ele impede ataques com tabelas pré-computadas e esconde usuários com senhas iguais. Não substitui um algoritmo lento, que é o que encarece a força bruta.',
    'MEDIUM',
    'OWASP Password Storage Cheat Sheet (questão original)',
    TRUE
),
(
    9,
    'Criptografia - Hash e Armazenamento de Senhas',
    'MULTIPLE_CHOICE',
    'Uma auditoria aponta falha criptográfica (A02:2021): as senhas do sistema estão em SHA-256 com salt. Qual recomendação corrige o problema?',
    'C',
    '["A) Cifrar as senhas com AES e guardar a chave na mesma base de dados", "B) Aplicar SHA-256 duas vezes seguidas e remover o salt", "C) Usar uma função lenta e adaptativa própria para senhas, como Argon2id, bcrypt ou PBKDF2, com custo configurável", "D) Codificar o hash em Base64 para acrescentar uma camada de cifragem"]'::jsonb,
    'SHA-256 é rápido e permite bilhões de tentativas por segundo em GPU. Funções de senha como Argon2id têm custo ajustável e resistem à força bruta. Cifra com a chave no mesmo banco é reversível; Base64 é só codificação.',
    'HARD',
    'OWASP Password Storage Cheat Sheet / OWASP Top 10 2021 A02 (questão original)',
    TRUE
),
(
    9,
    'Engenharia Social - Phishing e Manipulação',
    'MULTIPLE_CHOICE',
    'Alguém telefona dizendo ser do suporte de TI da faculdade e pede ao professor o código de verificação que acabou de chegar por SMS, ''para concluir a manutenção''. Que tipo de ataque é esse?',
    'C',
    '["A) Ataque de força bruta contra a senha", "B) Injeção de SQL no sistema de login", "C) Engenharia social com pretexto, em que o atacante inventa um cenário para obter o código", "D) Negação de serviço contra o servidor de SMS"]'::jsonb,
    'O atacante explora a confiança, não uma falha técnica: cria um pretexto (suporte de TI) por telefone (vishing) para obter o segundo fator. Nenhum suporte legítimo pede códigos de verificação; a defesa é treinamento e procedimento.',
    'EASY',
    'CERT.br - Cartilha de Segurança para Internet (questão original)',
    TRUE
),
(
    9,
    'Engenharia Social - Phishing e Manipulação',
    'MULTIPLE_CHOICE',
    'A tesouraria recebe um e-mail personalizado, citando o nome do diretor e um fornecedor real, pedindo urgência na troca da conta bancária para o próximo pagamento. Qual é a melhor classificação e defesa?',
    'B',
    '["A) Spam genérico; basta confiar no filtro antispam", "B) Spear phishing (fraude de e-mail corporativo); confirmar a troca por um canal independente já conhecido", "C) Phishing em massa; responder ao próprio e-mail pedindo confirmação", "D) Tailgating; reforçar o controle de acesso físico"]'::jsonb,
    'O ataque é direcionado e usa informações reais para parecer legítimo, típico do BEC. Responder ao mesmo e-mail pode cair no próprio atacante; deve-se ligar para um contato já cadastrado. Tailgating é entrada física indevida.',
    'MEDIUM',
    'CERT.br - Cartilha de Segurança para Internet (questão original)',
    TRUE
),
(
    9,
    'Engenharia Social - Phishing e Manipulação',
    'MULTIPLE_CHOICE',
    'Um atacante que já tem a senha de uma funcionária dispara dezenas de notificações push de aprovação de MFA de madrugada, até que ela aprove por cansaço. Qual contramedida é mais eficaz?',
    'A',
    '["A) Exigir correspondência de número no push ou adotar métodos resistentes a phishing, como FIDO2/passkeys", "B) Desativar o MFA e exigir senhas mais longas", "C) Trocar o push por uma pergunta secreta", "D) Aumentar o limite diário de notificações permitidas"]'::jsonb,
    'É a fadiga de MFA (MFA bombing). Com number matching, a vítima precisa digitar o número exibido na tela de login, o que impede aprovar às cegas; FIDO2 vincula a autenticação ao site. Pergunta secreta é um fator fraco.',
    'MEDIUM',
    'CISA - Implementing Number Matching in MFA (questão original)',
    TRUE
),
(
    9,
    'Fundamentos - Pilares da Segurança da Informação',
    'MULTIPLE_CHOICE',
    'Durante uma transferência bancária, um atacante intercepta a requisição e altera o valor de R$ 100 para R$ 10.000 sem que o sistema perceba. Qual pilar da segurança da informação foi violado principalmente?',
    'B',
    '["A) Disponibilidade", "B) Integridade", "C) Confidencialidade", "D) Não repúdio"]'::jsonb,
    'Integridade é a garantia de que a informação não foi alterada de forma indevida. Aqui o dado foi modificado em trânsito. Ler o valor violaria a confidencialidade; alterá-lo viola a integridade.',
    'EASY',
    'ABNT NBR ISO/IEC 27001:2022 (questão original)',
    TRUE
),
(
    9,
    'Fundamentos - Pilares da Segurança da Informação',
    'MULTIPLE_CHOICE',
    'Ao acessar o internet banking, o navegador confirma pelo certificado digital que o servidor é de fato o do banco, e não um site falso. Qual pilar da segurança está sendo garantido principalmente?',
    'A',
    '["A) Autenticidade", "B) Disponibilidade", "C) Não repúdio", "D) Integridade"]'::jsonb,
    'Autenticidade é a garantia de que uma entidade é quem afirma ser. Validar o certificado confirma a identidade do servidor. A integridade trata de alteração do conteúdo, não da identidade da origem.',
    'EASY',
    'ABNT NBR ISO/IEC 27001:2022 (questão original)',
    TRUE
),
(
    9,
    'Fundamentos - Pilares da Segurança da Informação',
    'MULTIPLE_CHOICE',
    'Um fornecedor assina digitalmente, com certificado ICP-Brasil, um contrato com a faculdade. Meses depois, alega que nunca assinou o documento. Qual propriedade da segurança impede que essa negação seja aceita?',
    'D',
    '["A) Confidencialidade", "B) Disponibilidade", "C) Integridade apenas", "D) Não repúdio (irretratabilidade)"]'::jsonb,
    'Não repúdio impede que o autor negue uma ação que praticou. A assinatura é feita com a chave privada, que só o titular controla. A integridade mostra que o texto não mudou, mas sozinha não comprova a autoria.',
    'MEDIUM',
    'ABNT NBR ISO/IEC 27001:2022 / MP 2.200-2/2001 (questão original)',
    TRUE
),
(
    9,
    'Gestão de Riscos - Continuidade e Resposta a Incidentes',
    'MULTIPLE_CHOICE',
    'O que significa a regra de backup 3-2-1?',
    'D',
    '["A) Três backups por dia, guardados por dois meses, em um único servidor", "B) Três servidores espelhados, dois data centers e um administrador responsável", "C) Backup completo a cada 3 dias, diferencial a cada 2 e incremental a cada 1", "D) Três cópias dos dados, em dois tipos de mídia diferentes, com uma cópia fora do local"]'::jsonb,
    'A regra 3-2-1 pede três cópias (a original e dois backups), em dois tipos de mídia ou armazenamento e uma cópia fora do local, de preferência offline ou imutável. Assim um único incidente, como incêndio ou ransomware, não destrói tudo.',
    'EASY',
    'Boas práticas de continuidade - ISO 22301 (questão original)',
    TRUE
),
(
    9,
    'Gestão de Riscos - Continuidade e Resposta a Incidentes',
    'MULTIPLE_CHOICE',
    'O sistema acadêmico pode perder no máximo 4 horas de dados após uma falha e deve voltar a funcionar em até 1 hora. Como essas metas se chamam?',
    'D',
    '["A) RTO de 4 horas e RPO de 1 hora", "B) MTBF de 4 horas e MTTR de 1 hora", "C) SLA de 4 horas e SLO de 1 hora", "D) RPO de 4 horas e RTO de 1 hora"]'::jsonb,
    'RPO (Recovery Point Objective) é a perda máxima de dados tolerada, medida em tempo, e define a frequência dos backups. RTO (Recovery Time Objective) é o tempo máximo para restabelecer o serviço. MTBF e MTTR são métricas de confiabilidade.',
    'MEDIUM',
    'ABNT NBR ISO 22301 (questão original)',
    TRUE
),
(
    9,
    'Gestão de Riscos - Continuidade e Resposta a Incidentes',
    'MULTIPLE_CHOICE',
    'A equipe confirma ransomware cifrando arquivos em um servidor da rede corporativa. Seguindo o ciclo de resposta a incidentes do NIST, qual deve ser a prioridade imediata?',
    'A',
    '["A) Conter: isolar o servidor afetado da rede, preservando evidências, antes de erradicar e recuperar", "B) Formatar o servidor na hora e restaurar o backup, sem nenhuma análise", "C) Pagar o resgate para recuperar os arquivos o mais rápido possível", "D) Aguardar o fim da cifragem para avaliar o tamanho do estrago"]'::jsonb,
    'Após detectar e analisar, a contenção limita a propagação. Formatar antes da análise destrói evidências e pode restaurar um sistema ainda vulnerável. Pagar resgate não garante recuperação e financia o crime. Esperar amplia o dano.',
    'HARD',
    'NIST SP 800-61 - Incident Handling Guide (questão original)',
    TRUE
),
(
    9,
    'LGPD - Lei Geral de Proteção de Dados Pessoais',
    'MULTIPLE_CHOICE',
    'Uma universidade contrata uma empresa de nuvem para hospedar os dados dos alunos, e essa empresa só trata os dados conforme as instruções da universidade. Pela LGPD, a empresa de nuvem é:',
    'B',
    '["A) Controladora", "B) Operadora", "C) Encarregada (DPO)", "D) Titular dos dados"]'::jsonb,
    'Controlador é quem toma as decisões sobre o tratamento (a universidade). Operador trata em nome do controlador (a nuvem). Encarregado é o canal de comunicação com titulares e ANPD. Titular é a pessoa a quem os dados se referem.',
    'EASY',
    'Lei 13.709/2018 (LGPD), art. 5º (questão original)',
    TRUE
),
(
    9,
    'LGPD - Lei Geral de Proteção de Dados Pessoais',
    'MULTIPLE_CHOICE',
    'Um aluno solicita à faculdade que informe quais dados pessoais dele são tratados e que forneça uma cópia. Qual direito do titular previsto na LGPD ele está exercendo?',
    'B',
    '["A) Revogação do consentimento", "B) Confirmação da existência de tratamento e acesso aos dados", "C) Oposição ao tratamento", "D) Anonimização dos dados desnecessários"]'::jsonb,
    'O art. 18 da LGPD garante ao titular a confirmação de que há tratamento e o acesso aos dados. Revogar consentimento encerra um tratamento baseado nele; oposição contesta tratamento irregular; anonimização remove a identificação.',
    'MEDIUM',
    'Lei 13.709/2018 (LGPD), art. 18 (questão original)',
    TRUE
),
(
    9,
    'LGPD - Lei Geral de Proteção de Dados Pessoais',
    'MULTIPLE_CHOICE',
    'Uma empresa envia ao eSocial os dados de seus empregados, como exige a legislação trabalhista. Qual base legal da LGPD fundamenta esse tratamento?',
    'C',
    '["A) Consentimento do titular, exigido para qualquer tratamento", "B) Proteção do crédito", "C) Cumprimento de obrigação legal ou regulatória pelo controlador", "D) Tutela da saúde"]'::jsonb,
    'O consentimento é só uma das bases do art. 7º. Quando a lei obriga o tratamento, a base é a obrigação legal ou regulatória, e o empregado não pode recusá-lo. Proteção do crédito e tutela da saúde não se aplicam ao caso.',
    'MEDIUM',
    'Lei 13.709/2018 (LGPD), art. 7º (questão original)',
    TRUE
),
(
    9,
    'LGPD - Lei Geral de Proteção de Dados Pessoais',
    'MULTIPLE_CHOICE',
    'Uma clínica descobre o vazamento de prontuários, incidente que pode gerar risco ou dano relevante aos titulares. Qual é a obrigação do controlador?',
    'A',
    '["A) Comunicar o incidente à ANPD e aos titulares afetados, no prazo de 3 dias úteis do conhecimento", "B) Comunicar apenas à polícia, sem envolver a ANPD", "C) Comunicar somente se a ANPD solicitar, em até 30 dias", "D) Nada comunicar, pois o dever cabe só ao operador"]'::jsonb,
    'O art. 48 da LGPD obriga o controlador a comunicar à ANPD e ao titular incidentes que possam causar risco ou dano relevante. O Regulamento de Comunicação de Incidente (Resolução CD/ANPD 15/2024) fixa 3 dias úteis. Dados de saúde são sensíveis.',
    'HARD',
    'LGPD art. 48 / Resolução CD/ANPD nº 15/2024 (questão original)',
    TRUE
),
(
    9,
    'OWASP Top 10 - Vulnerabilidades Web',
    'MULTIPLE_CHOICE',
    'Um aluno digita manualmente a URL /admin/relatorios e o servidor exibe a página, pois o único controle era esconder o link do menu para quem não é administrador. Em qual categoria do OWASP Top 10 2021 isso se enquadra?',
    'C',
    '["A) Falhas criptográficas (A02)", "B) Injeção (A03)", "C) Quebra de controle de acesso (A01 - Broken Access Control)", "D) Componentes vulneráveis e desatualizados (A06)"]'::jsonb,
    'A permissão deve ser verificada no servidor a cada requisição. Esconder o link na interface não é controle de acesso, e o recurso ficou acessível a qualquer usuário: A01:2021, a primeira categoria da lista.',
    'EASY',
    'OWASP Top 10 2021 - A01 Broken Access Control (questão original)',
    TRUE
),
(
    9,
    'OWASP Top 10 - Vulnerabilidades Web',
    'MULTIPLE_CHOICE',
    'O sistema acadêmico usa uma biblioteca de log com vulnerabilidade crítica divulgada há meses, já corrigida pelo fornecedor, mas a equipe nunca atualizou a dependência. Em qual categoria do OWASP Top 10 2021 esse problema se enquadra?',
    'C',
    '["A) Injeção (A03)", "B) Falhas de registro e monitoramento de segurança (A09)", "C) Componentes vulneráveis e desatualizados (A06)", "D) Falhas de integridade de software e dados (A08)"]'::jsonb,
    'Usar bibliotecas e componentes com vulnerabilidades conhecidas, sem atualizar, é a categoria A06:2021. A defesa é manter inventário das dependências, acompanhar alertas de vulnerabilidade e atualizar continuamente. A08 trata da integridade de atualizações e pipelines, e A09 da falta de logs e monitoramento.',
    'MEDIUM',
    'OWASP Top 10 2021 (questão original)',
    TRUE
),
(
    9,
    'OWASP Top 10 - Vulnerabilidades Web',
    'MULTIPLE_CHOICE',
    'Em um fórum acadêmico, um usuário publica um comentário contendo uma tag <script> que é salva no banco e executada no navegador de todos que abrem a página. Qual é a vulnerabilidade e a defesa principal?',
    'A',
    '["A) XSS armazenado; codificar a saída conforme o contexto (HTML, atributo, JS) ao renderizar", "B) SQL Injection; usar consultas parametrizadas no INSERT", "C) CSRF; incluir um token anti-CSRF no formulário", "D) XSS refletido; aplicar hash ao comentário antes de salvar"]'::jsonb,
    'O script persiste no servidor e atinge outros usuários: XSS armazenado, que no OWASP Top 10 2021 integra A03 (Injeção). A defesa central é a codificação de saída contextual, complementada por CSP. Token anti-CSRF não impede execução de script.',
    'MEDIUM',
    'OWASP Top 10 2021 - A03 Injeção / OWASP XSS Cheat Sheet (questão original)',
    TRUE
),
(
    9,
    'OWASP Top 10 - Vulnerabilidades Web',
    'MULTIPLE_CHOICE',
    'Um banco autentica usuários por cookie de sessão. Um site malicioso contém um formulário oculto que faz POST para /transferir quando a vítima logada o visita. Qual medida mitiga esse ataque?',
    'D',
    '["A) Marcar o cookie de sessão como HttpOnly", "B) Trocar o método da operação de POST para GET", "C) Exigir HTTPS em todas as páginas do banco", "D) Exigir um token anti-CSRF imprevisível validado no servidor, aliado ao cookie com SameSite=Lax ou Strict"]'::jsonb,
    'É CSRF: o navegador envia o cookie automaticamente na requisição forjada. O token anti-CSRF, que o site atacante não conhece, e o SameSite bloqueiam o envio. HttpOnly só impede leitura do cookie por script; HTTPS não muda o envio automático.',
    'HARD',
    'OWASP CSRF Prevention Cheat Sheet (questão original)',
    TRUE
),
(
    9,
    'OWASP Top 10 - Vulnerabilidades Web',
    'MULTIPLE_CHOICE',
    'Uma aplicação na nuvem tem o recurso ''importar foto por URL''. Um atacante informa http://169.254.169.254/latest/meta-data/ e recebe credenciais da instância. Qual é a vulnerabilidade e a mitigação adequada?',
    'B',
    '["A) CSRF; adicionar token anti-CSRF ao formulário de importação", "B) SSRF; validar o destino no servidor com lista de permissões e bloquear endereços internos após resolver o DNS", "C) XSS refletido; aplicar Content Security Policy na página", "D) SSRF; validar o formato da URL apenas no navegador"]'::jsonb,
    'O servidor foi induzido a requisitar um endereço interno (metadados da nuvem): SSRF, categoria A10:2021. A defesa é no servidor, com allowlist e bloqueio de faixas internas e link-local. Validação no navegador é trivialmente contornada.',
    'HARD',
    'OWASP Top 10 2021 - A10 SSRF (questão original)',
    TRUE
);

-- -----------------------------------------------------------------------------
-- 14. SIS_INFO — REDES_DISTRIB (33 questões)
-- -----------------------------------------------------------------------------
INSERT INTO tb_flashcard (subject_id, topic, question_type, question, answer, options_json, explanation, difficulty, source, active)
VALUES
(
    10,
    'Camada de Aplicação - DNS, HTTP e TLS',
    'MULTIPLE_CHOICE',
    'Qual tipo de registro DNS associa um nome de domínio a um endereço IPv6?',
    'C',
    '["A) A", "B) MX", "C) AAAA", "D) CNAME"]'::jsonb,
    'O registro A aponta para IPv4 e o AAAA para IPv6. O MX indica servidores de e-mail do domínio e o CNAME cria um apelido para outro nome.',
    'EASY',
    'RFC 3596 - DNS para IPv6 (questão original)',
    TRUE
),
(
    10,
    'Camada de Aplicação - DNS, HTTP e TLS',
    'MULTIPLE_CHOICE',
    'Segundo a semântica do HTTP (RFC 9110), qual método é idempotente, mas não é seguro?',
    'A',
    '["A) PUT", "B) GET", "C) POST", "D) PATCH"]'::jsonb,
    'PUT altera o estado do servidor (não é seguro), mas repetir a mesma requisição deixa o mesmo resultado (é idempotente). GET é seguro e idempotente; POST e PATCH não têm idempotência garantida pela especificação.',
    'MEDIUM',
    'RFC 9110 - HTTP Semantics (questão original)',
    TRUE
),
(
    10,
    'Camada de Aplicação - DNS, HTTP e TLS',
    'MULTIPLE_CHOICE',
    'Um resolvedor DNS recursivo, sem nada em cache, precisa resolver www.exemplo.com.br. Qual a sequência de servidores consultados?',
    'B',
    '["A) Servidor autoritativo do domínio, depois o TLD e por fim a raiz", "B) Servidor raiz, depois servidores do TLD .br e por fim o servidor autoritativo do domínio", "C) Apenas o servidor raiz, que conhece todos os nomes", "D) Servidor DHCP da rede local e depois o autoritativo"]'::jsonb,
    'A raiz indica os servidores do TLD; estes delegam para os autoritativos do domínio, que respondem o endereço. O resolvedor guarda as respostas em cache pelo TTL. A raiz não conhece todos os nomes, apenas as delegações.',
    'MEDIUM',
    'Kurose e Ross, Redes de Computadores, 8ª ed. (questão original)',
    TRUE
),
(
    10,
    'Camada de Aplicação - DNS, HTTP e TLS',
    'MULTIPLE_CHOICE',
    'Sobre o TLS 1.3, qual afirmação é correta?',
    'D',
    '["A) Permite troca de chaves por RSA estático para compatibilidade", "B) Cifra os dados de aplicação com a chave privada do certificado", "C) Exige 2 RTTs no handshake e não oferece modo 0-RTT", "D) O handshake completo leva 1 RTT e usa Diffie-Hellman efêmero, garantindo sigilo futuro"]'::jsonb,
    'O TLS 1.3 removeu o RSA estático: usa (EC)DHE, então vazar a chave privada depois não revela sessões passadas. O certificado só autentica; os dados usam chaves simétricas. Há ainda retomada 0-RTT opcional.',
    'HARD',
    'RFC 8446 - TLS 1.3 (questão original)',
    TRUE
),
(
    10,
    'Camada de Rede - Roteamento e NAT',
    'MULTIPLE_CHOICE',
    'Como o NAT com sobrecarga (PAT) permite que vários hosts com IP privado compartilhem um único IP público?',
    'D',
    '["A) Atribuindo um IP público diferente a cada host da rede", "B) Usando o endereço MAC como identificador na internet", "C) Encaminhando todo o tráfego por broadcast", "D) Traduzindo cada conexão para uma porta de origem distinta e mantendo uma tabela de mapeamentos"]'::jsonb,
    'O roteador reescreve IP e porta de origem e registra o par interno-externo; na volta, a porta de destino indica a qual host privado entregar. Endereços como 192.168.0.0/16 (RFC 1918) não são roteados na internet.',
    'EASY',
    'RFC 3022 - NAT (questão original)',
    TRUE
),
(
    10,
    'Camada de Rede - Roteamento e NAT',
    'MULTIPLE_CHOICE',
    'A tabela de um roteador tem: 10.0.0.0/8 pela interface 1; 10.1.0.0/16 pela 2; 10.1.2.0/24 pela 3; rota padrão 0.0.0.0/0 pela 4. Por qual interface sai um pacote para 10.1.3.9?',
    'B',
    '["A) Interface 1", "B) Interface 2", "C) Interface 3", "D) Interface 4"]'::jsonb,
    'Vale a regra do prefixo mais longo. 10.1.3.9 casa com /8 e /16, mas não com 10.1.2.0/24 (o terceiro octeto é 3). O prefixo mais específico que casa é o /16.',
    'MEDIUM',
