    '["A) Processar normalmente e gerar uma nova cobrança", "B) Rejeitar sempre com erro, mesmo que a primeira tenha falhado por timeout no cliente", "C) Ignorar a chave, pois POST já é idempotente", "D) Devolver o resultado já registrado da primeira execução, sem cobrar de novo"]'::jsonb,
