    10,
    'Sistemas Distribuídos - Consistência e Replicação',
    'MULTIPLE_CHOICE',
    'Um banco usa replicação assíncrona do primário para uma réplica. O primário cai logo depois de confirmar algumas transações ao cliente, e a réplica é promovida a primário. Qual risco existe?',
    'A',
    '["A) Perder transações já confirmadas ao cliente que ainda não tinham chegado à réplica", "B) Nenhum, pois a replicação assíncrona dá as mesmas garantias da síncrona", "C) Aumento obrigatório da latência de escrita no primário", "D) Leituras sujas na réplica promovida"]'::jsonb,
    'Na replicação assíncrona o primário confirma sem esperar a réplica, o que reduz a latência de escrita mas abre uma janela em que commits confirmados ainda não foram replicados; no failover, eles se perdem. A replicação síncrona elimina essa perda ao custo de escrita mais lenta.',
