    10,
    'Sistemas Distribuídos - Consistência e Replicação',
    'MULTIPLE_CHOICE',
    'Um armazenamento replicado em N = 5 nós usa quóruns de escrita W = 3. Qual o menor quórum de leitura R que garante que toda leitura alcance ao menos um nó com a última escrita confirmada?',
    'D',
    '["A) 1", "B) 2", "C) 5", "D) 3"]'::jsonb,
    'A interseção entre quóruns exige W + R > N: 3 + R > 5, logo R ≥ 3. Com R = 2, a leitura pode consultar só os dois nós que não receberam a escrita.',
