(
    10,
    'Sistemas Distribuídos - Tolerância a Falhas e Relógios Lógicos',
    'MULTIPLE_CHOICE',
    'Um cluster com algoritmo de consenso Raft tem 5 nós. Quantas falhas por parada (crash) ele tolera e continua aceitando escritas?',
    'A',
    '["A) 2", "B) 1", "C) 3", "D) 4"]'::jsonb,
    'O Raft exige maioria (quórum de 3 em 5) para eleger líder e confirmar entradas. Com 2 nós parados, ainda há 3; com 3 parados, não há maioria. Em geral, 2f + 1 nós toleram f falhas.',
    'MEDIUM',
    'Ongaro e Ousterhout, Raft, USENIX ATC 2014 (questão original)',
    TRUE
),
(
    10,
    'Sistemas Distribuídos - Tolerância a Falhas e Relógios Lógicos',
    'MULTIPLE_CHOICE',
    'Com relógios lógicos de Lamport, observa-se L(a) < L(b) para dois eventos a e b. O que se pode concluir?',
    'C',
    '["A) Que a precede b causalmente", "B) Que a e b são concorrentes", "C) Apenas que b não precede a; a pode ter causado b ou ser concorrente a ele", "D) Que os relógios físicos dos processos estão sincronizados"]'::jsonb,
    'Lamport garante: se a precede b, então L(a) < L(b). Pela contrapositiva, L(a) < L(b) exclui que b preceda a, mas não prova que a precede b, pois eventos concorrentes também podem ter essa relação. Relógios vetoriais resolvem isso.',
    'HARD',
    'Lamport, Time, Clocks and the Ordering of Events, 1978 (questão original)',
    TRUE
);

