    'Story points comparam itens entre si: um item de 8 pontos é cerca de quatro vezes maior que um de 2. Não são horas nem valor de negócio, e a mesma escala só faz sentido dentro da equipe que a calibrou. Escalas com intervalos crescentes, como a de Fibonacci, refletem a incerteza maior dos itens grandes.',
