    'A revelação simultânea impede que estimativas iniciais influenciem as demais (efeito de ancoragem). Quando há divergência, quem deu as estimativas mais alta e mais baixa explica seu raciocínio, a equipe discute e vota de novo até convergir, o que costuma revelar premissas ocultas.',
    'MEDIUM',
    'Mike Cohn, Agile Estimating and Planning (questão original)',
